window.BASAIR_QUESTIONS=(window.BASAIR_QUESTIONS||[]).concat([{"id":"s7-1214","number":1214,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لم بُني ﴿سيُغفر لنا﴾ للمجهول؟","answer":"حذف الفاعل للعلم به؛ فالمغفرة المقصودة لا تكون إلا من الله. ويركز البناء على دعواهم وقوع المغفرة لأنفسهم، وهي الدعوى التي تكشف غرورهم مع إصرارهم على الذنب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص76، تحت «سر بناء الفعل سيغفر لما لم يسم فاعله»","url":""}]},{"id":"s7-1215","number":1215,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا عبروا بالسين: ﴿سيغفر لنا﴾؟","answer":"السين تخلص الفعل للاستقبال، فتحكي قولهم إن المغفرة ستقع لهم لاحقًا مع إصرارهم على المعصية. فموضع الذم ثقتهم بهذا الوعد الذي ادعوه لأنفسهم من غير توبة، لا أن السين بذاتها توجب قرب الزمن أو ضمان المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص75–76، تحت «نكتة مجيء حرف التنفيس في سيغفر»","url":""}]},{"id":"s7-1216","number":1216,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿وإن يأتهم عرض مثله يأخذوه﴾؟","answer":"يكشف تكرر الجشع: كلما جاءهم متاع حرام مماثل أخذوه، مع استمرارهم في دعوى المغفرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص76، تحت عنوان «دلالة الواو في قوله وإن يأتهم»","url":""}]},{"id":"s7-1217","number":1217,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما نكتة التعبير بالمضارع في يأخذون؟","answer":"يأخذون العرض أولًا ثم يعاودون أخذه متى تجدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص74، تحت عنوان «نكتة التعبير بالمضارع في يأخذون»","url":""}]},{"id":"s7-1626","number":1626,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما سر التعبير بالجملة الشرطية؟","answer":"تكرار اللفظين يجسد تكرر السلوك نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص77، تحت عنوان «بلاغة التعبير بالجملة الشرطية»","url":""}]},{"id":"s7-1218","number":1218,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا وبخهم باستفهام: ﴿ألم يؤخذ عليهم ميثاق الكتاب﴾؟","answer":"الاستفهام تقريري توبيخي؛ يثبت أن الميثاق أُخذ عليهم بالفعل، فلا عذر لهم في القول على الله بغير الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص78–79، تحت «غرض الاستفهام ونوعه»","url":""}]},{"id":"s7-1219","number":1219,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا أضيف الميثاق إلى الكتاب؟","answer":"لأن مضمون الميثاق ثابت في الكتاب الذي ورثوه ودرسوه؛ فهو عهد مرتبط بحفظ أحكامه وعدم تحريفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص80، تحت «نكتة إضافة الميثاق إلى الكتاب»","url":""}]},{"id":"s7-1220","number":1220,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿أن لا يقولوا على الله إلا الحق﴾؟","answer":"هذا تفسير للميثاق: ألا ينسبوا إلى الله إلا ما ثبت حقًا، وفيه تعريض بأن دعوى ﴿سيغفر لنا﴾ قول بلا حجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص78، تحت عنوان «الموقع البياني لقوله ألم يؤخذ عليهم»","url":""}]},{"id":"s7-1221","number":1221,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا عقب بقوله: ﴿ودرسوا ما فيه﴾؟","answer":"ذكّر بأنهم قرؤوا ما في الكتاب وعرفوه، فمخالفتهم ليست عن جهل بل بعد درس وعلم، وهو أبلغ في إقامة الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص82، تحت «غرض التعبير بقوله ﴿ودرسوا ما فيه﴾»","url":""}]},{"id":"s7-1222","number":1222,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"ما سرّ التعبير في قوله تعالى: ﴿والدار الآخرة خير للذين يتقون﴾؟","answer":"متاع الآخرة أبقى وأعظم من العرض الأدنى الذي يأخذونه، فالمقابلة ترد ميزانهم من العاجل الزائل إلى الباقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص82–83، تحت «الموقع البياني لجملة ﴿والدار الآخرة خير﴾».","url":""}]},{"id":"s7-1223","number":1223,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا قيد خيرية الآخرة بـ﴿للذين يتقون﴾؟","answer":"لأن خير الآخرة لا يناله من آثر الحرام واغتر بالمغفرة، وإنما ينتفع به من اتقى الله ووفى بميثاق الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص83–84، تحت عنوان «معنى اللام في للذين»","url":""}]},{"id":"s7-1224","number":1224,"surah":7,"verses":[169],"references":[{"surah":7,"verses":[169]}],"verseLabel":"الأعراف: 169","question":"لماذا ختم بـ﴿أفلا تعقلون﴾، وفي قراءة ﴿يعقلون﴾؟","answer":"الاستفهام يحض على إدراك التفاوت الواضح بين عرض الدنيا والآخرة. وفي قراءة الخطاب مواجهة لهم، وفي الغيبة حكاية لحالهم وتعجيب السامعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص85، تحت عنوان «فائدة الالتفات في قوله أفلا تعقلون»","url":""}]},{"id":"s7-1225","number":1225,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170؛ قراءة التخفيف والتشديد","question":"ما دلالة التوجيه البلاغي للقراءات في يمسكون؟","answer":"قراءة التخفيف من أمسك تدل على التعلق بالكتاب وحفظه والعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص91–92، تحت عنوان «التوجيه البلاغي للقراءات في يمسكون»","url":""}]},{"id":"s7-1627","number":1627,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170؛ قراءة التخفيف والتشديد","question":"ما سر مجيء جملة صلة الموصول بمادتها وصيغتها؟","answer":"قراءة التشديد من مسّك تزيد معنى شدة الحرص والمبالغة والتكرير في التمسك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص91–92، تحت عنوان «سر مجيء جملة صلة الموصول بمادتها وصيغتها»","url":""}]},{"id":"s7-1226","number":1226,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿يمسكون بالكتاب﴾ لا «يقرؤون الكتاب»؟","answer":"التمسك هو الأخذ الجاد بما في الكتاب علمًا وعملًا، لا مجرد تلاوته بلا امتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص91–92، تحت عنوان «بلاغة المجاز في قوله يمسكون بالكتاب»","url":""}]},{"id":"s7-1227","number":1227,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170","question":"لماذا عطف ﴿وأقاموا الصلاة﴾ بالماضي على المضارع ﴿يمسكون﴾؟","answer":"المضارع يستحضر دوام تمسكهم، والماضي في ﴿أقاموا﴾ يقرر تحقق إقامة الصلاة وثباتها منهم؛ فجمع الاستمرار والتحقق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص93، تحت «غرض التغاير بين الجمل المعطوفة»","url":""}]},{"id":"s7-1228","number":1228,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170","question":"لماذا خُصت الصلاة بعد التمسك بالكتاب؟","answer":"خُصت لأنها عماد العمل وأظهر ما يدل على صدق التمسك بالكتاب، وتجمع صلة العبد بربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص93–94، تحت عنوان «نكتة عطف وأقاموا الصلاة على ما تقدمها»","url":""}]},{"id":"s7-1229","number":1229,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170","question":"ما أثر توكيد الوعد في ﴿إنا لا نضيع أجر المصلحين﴾؟","answer":"أكد الوعد بإن والجملة الاسمية ليطمئن المتمسكين بالكتاب والمصلحين إلى حفظ أجرهم، ويحثهم على الاستمرار في العمل. فلا يذهب إصلاحهم سدى عند الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص94–95، تحت عنوان «بلاغة تتابع المؤكدات في فاصلة الآية»","url":""}]},{"id":"s7-1230","number":1230,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170","question":"ما سرّ التعبير في قوله تعالى: ﴿لا نضيع أجر المصلحين﴾، دون أن يقال: أجرهم؟","answer":"أظهر وصف ﴿المصلحين﴾ بدل الضمير ليبين علة حفظ الأجر، ويعم الوعد كل من تحقق بالإصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص96، تحت عنوان «معنى أل في المصلحين»","url":""}]},{"id":"s7-1231","number":1231,"surah":7,"verses":[170],"references":[{"surah":7,"verses":[170]}],"verseLabel":"الأعراف: 170","question":"لماذا وصفهم بـ﴿المصلحين﴾ لا «الصالحين»؟","answer":"المصلح يتعدى صلاحه إلى إقامة الكتاب والصلاة وإصلاح غيره، وهو أبلغ من الصالح الذي قد يقتصر خيره على نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص96، تحت عنوان «غرض إضافة الأجر إلى المصلحين»","url":""}]},{"id":"s7-1233","number":1233,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ نتقنا الجبل﴾، وما دلالة «نتقنا»؟","answer":"النتق اقتلاع الشيء من أصله ورفعه بقوة، فصوّر رفع الجبل بعد اقتلاعه فوقهم تصويرًا مهيبًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص110، تحت عنوان «نتقنا ورفعنا»","url":""}]},{"id":"s7-1234","number":1234,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿فوقهم﴾؟","answer":"يبين أنه صار معلقًا في جهة العلو مباشرة فوق رؤوسهم، فكان التهديد حاضرًا لا بعيدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص102، تحت عنوان «دلالة حذف الجار من في قوله فوقهم»","url":""}]},{"id":"s7-1235","number":1235,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"لماذا شُبّه الجبل بـ﴿ظلة﴾ مع أنه أعظم منها؟","answer":"التشبيه من جهة كونه ساترًا معلقًا فوقهم كالسحابة المظلة، لا من جهة الحجم؛ فهو يصف هيئته بالنسبة إليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص102–103، تحت عنوان «الدلالة البلاغية لموقع كأنه ظلة بعد فوقهم»","url":""}]},{"id":"s7-1236","number":1236,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما أثر تشبيه الجبل بظلة من الغمام وهو مرفوع فوقهم؟","answer":"يصور الجبل مرفوعًا فوقهم من غير عمد كالغمام، فيبرز هيئة الارتفاع المحيطة بهم. ويذكر المصدر أن صورة الغمام المعتادة للرحمة صارت هنا صورة تهديد بالعذاب؛ فزاد المشهد رهبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص103، تحت «بلاغة الصورة التشبيهية في قوله كأنه ظلة»","url":""}]},{"id":"s7-1237","number":1237,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿وظنوا أنه واقع بهم﴾ مع رؤيتهم الجبل فوقهم؟","answer":"يذكر المصدر وجهين: أن الظن بمعنى اليقين لقوة أمارات وقوع الجبل، أو أنه باقٍ على معناه لأنهم شاهدوا رفعه ولم يقع بهم بعد، فغلب على نفوسهم توقع سقوطه. والوجهان يبرزان شدة الخوف الذي أحدثه المشهد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص104–105، تحت «بلاغة التعبير بفعل الظن في وظنوا»","url":""}]},{"id":"s7-1238","number":1238,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿واقع بهم﴾ لا «واقع عليهم»؟","answer":"الباء تفيد الإلصاق والوقوع المتلبس بهم، فتشعر بأنه سيصيبهم ويحيط بهم، لا مجرد سقوط في جهة فوقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص106–107، تحت «سر التعبير بحرف الباء في بهم»","url":""}]},{"id":"s7-1239","number":1239,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"لماذا حُذف فعل القول قبل ﴿خذوا ما آتيناكم بقوة﴾؟","answer":"حذف القول للإيجاز وسرعة الانتقال من مشهد التهديد إلى الأمر المقصود؛ والتقدير: وقلنا خذوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص107، تحت «موقع جملة خذوا ما آتيناكم بقوة مما قبله وبلاغته»","url":""}]},{"id":"s7-1240","number":1240,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"لماذا تكرر الأمر بالأخذ بقوة لقوم موسى بعد أن سبق توجيهه إلى موسى؟","answer":"لأن تكليف موسى كان أشد: يأخذ الكتاب بعزم ثم يبلغه ويؤديه، أما قومه فيأخذون ما بلغهم به قبولًا والتزامًا وطاعة؛ فاختلاف المخاطب ووظيفته اقتضى تجديد الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص513، تحت «فائدة التفريق بين أخذ موسى ﷺ، وأخذ قومه»","url":""}]},{"id":"s7-1241","number":1241,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى: ﴿واذكروا ما فيه﴾ بعد ﴿خذوا﴾؟","answer":"عقب الأخذ بالذكر تنبيهًا إلى الحفظ والتدبر والعمل، ودفعًا للنسيان والغفلة. فالمطلوب ملازمة مضمون الكتاب علمًا وامتثالًا؛ والذكر يعين على دوام الأخذ به بقوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص108، تحت «سر العطف بالأمر بالذكر»","url":""}]},{"id":"s7-1242","number":1242,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"لماذا ختم بـ﴿لعلكم تتقون﴾؟","answer":"غاية الأخذ الجاد والذكر أن تنشأ التقوى، فيحجزهم الكتاب عن المخالفة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص108–109، تحت عنوان «بلاغة الختم بجملة الإنشاء غير الطلبي في قوله لعلكم تتقون»","url":""}]},{"id":"s7-1243","number":1243,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما سرّ التعبير في قوله تعالى في الأعراف: ﴿وإذ نتقنا الجبل فوقهم﴾، وفي البقرة: ﴿ورفعنا فوقكم الطور﴾؟","answer":"﴿نتقنا﴾ في الأعراف يلائم تفصيل مشهد التهديد واقتلاع الجبل، أما ﴿رفعنا﴾ في البقرة فيوجز الحدث ضمن تعداد النعم والمواثيق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص110، تحت عنوان «نتقنا ورفعنا»","url":""}]},{"id":"s7-1244","number":1244,"surah":7,"verses":[171],"references":[{"surah":7,"verses":[171]}],"verseLabel":"الأعراف: 171","question":"ما الفرق الدلالي بين التعبير بـ﴿نتقنا الجبل﴾ في الأعراف و﴿رفعنا فوقكم الطور﴾ في البقرة؟","answer":"الرَّفع أعمّ، فهو نقل الشيء إلى أعلى، أما النَّتق فيدل على اقتلاع الشيء من أصله ثم رفعه؛ لذلك يصوّر لفظ ﴿نتقنا﴾ شدة اقتلاع الجبل ورفعه فوقهم تصويرًا أخص وأقوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص555، تحت «الرَّفع والنَّتق»","url":""}]},{"id":"s7-1245","number":1245,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذ أخذ ربك من بني آدم﴾، دون أن يقال: من آدم؟","answer":"يعم التعبير ذرية بني آدم المتناسلة من ظهور آبائها، فيشمل البشر جيلًا بعد جيل. ويبين المصدر أن ذكر بني آدم وظهورهم يقرر عموم الأخذ للنسل، ولا يحصر الحجة في شخص آدم وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص116، تحت عنوان «سر التعبير بعبارة بني آدم للذكور»","url":""}]},{"id":"s7-1246","number":1246,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"لماذا أضيف الرب إلى النبي ﷺ: ﴿ربك﴾؟","answer":"إضافة الرب إلى النبي ﷺ تستحضر عنايته وتربيته وهو يقص عليه أصل الحجة على البشر، وتثبت أن آخذ الميثاق هو ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص115–116، تحت عنوان «نكتة إضافة كلمة الرب إلى ضمير الخطاب ربك»","url":""}]},{"id":"s7-1247","number":1247,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿من ظهورهم ذريتهم﴾ فكرر معنى النسل؟","answer":"﴿من ظهورهم﴾ يبين موضع خروج النسل من الآباء، و﴿ذريتهم﴾ يبين المأخوذ؛ فليس تكرارًا بل تفصيل للمصدر والمستخرج.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص116–117، تحت عنوان «بلاغة التعبير بالبدل من ظهورهم»","url":""}]},{"id":"s7-1248","number":1248,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"لماذا جمع ﴿ظهورهم﴾ وأفرد جنس ﴿ذريتهم﴾؟","answer":"جُمعت الظهور لتعدد الآباء، وجاءت الذرية اسم جنس أو جمعًا يدل على مجموع النسل الخارج منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص117–118، تحت «تنوع القراءة القرآنية وأثره في المعنى»","url":""}]},{"id":"s7-1249","number":1249,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿وأشهدهم على أنفسهم﴾؟","answer":"جعلهم شاهدين على حقيقة مستقرة في فطرهم، فلا يستطيع المرء أن يدفع إقرار نفسه بربوبية خالقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص118–119، تحت عنوان «مرجع الضمير في قوله وأشهدهم على أنفسهم»","url":""}]},{"id":"s7-1250","number":1250,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"لماذا جاء التقرير باستفهام: ﴿ألست بربكم﴾؟","answer":"الاستفهام تقريري يلزمهم بالإجابة التي لا يسع الفطرة إنكارها، فيتحول العلم بالربوبية إلى شهادة صريحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص120، تحت «إيثار الاستفهام التقريري على التقرير المباشر»","url":""}]},{"id":"s7-1251","number":1251,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"لم قررت الآية الربوبية في ﴿ألست بربكم﴾؟","answer":"تذكر الربوبية المخاطبين بخلق الله لهم وتربيته وإحسانه وتدبيره، فتقوم هذه النعم دليلًا على استحقاقه الإقرار والطاعة. فالمقرر به وصف يجمع الحجة والتذكير بالإحسان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص121، تحت «بلاغة التعبير بالربوبية في تعيين المقرر به بربكم»","url":""}]},{"id":"s7-1252","number":1252,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"ما دلالة جوابهم: ﴿بلى شهدنا﴾ وجمعه بين الإقرار والشهادة؟","answer":"﴿بلى﴾ تبطل النفي وتثبت الربوبية، و﴿شهدنا﴾ يوثق الإقرار ويحمّلهم تبعته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص122، تحت عنوان «سر اصطفاء الجواب بلى»","url":""}]},{"id":"s7-1253","number":1253,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"لماذا حُذف متعلق ﴿شهدنا﴾ أو المشهود به؟","answer":"حذف لدلالة السؤال عليه؛ أي شهدنا أنك ربنا، فالإيجاز يثبت الجواب من غير إعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص123، تحت «بلاغة كمال الاتصال أو الاستئناف بين حكاية قول البشر أو الملائكة»","url":""}]},{"id":"s7-1254","number":1254,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"ما سرّ التعبير في قوله تعالى: ﴿أن تقولوا يوم القيامة إنا كنا عن هذا غافلين﴾؟","answer":"بيّن غاية الإشهاد: قطع عذر الغفلة يوم القيامة، فلا يقولوا إن أصل معرفة الرب لم يقم في فطرتهم ولم تبلغهم دلائله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص125، تحت عنوان «بلاغة القيد بالظرف يوم القيامة»","url":""}]},{"id":"s7-1255","number":1255,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"إلى ماذا يشير ﴿هذا﴾؟","answer":"يشير إلى التوحيد والإقرار بربوبية الله، أو إلى الميثاق والإشهاد المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص126، تحت «سر التعبير باسم الإشارة هذا في عن هذا غافلين»","url":""}]},{"id":"s7-1256","number":1256,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"لماذا قيل في ميثاق النبيين: ﴿وإذ أخذ الله ميثاق النبيين﴾، وفي ميثاق ذرية آدم: ﴿وإذ أخذ ربك من بني آدم﴾؟","answer":"أُسند ميثاق النبيين إلى الاسم الأعظم ﴿الله﴾ لما فيه من المهابة والجلال، ولأن الميثاق تكليف عام للأنبياء. وأُسند ميثاق الذرية إلى ﴿ربك﴾ لمناسبة معنى الربوبية والإنعام والتربية، مع ما في الإضافة إلى ضمير النبي ﷺ من تشريف.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص368، تحت «توجيه المتشابه اللفظي بين قوله: ﴿وإذ أخذ الله﴾ وقوله: ﴿وإذ أخذ ربك﴾»","url":""}]},{"id":"s7-1628","number":1628,"surah":7,"verses":[172],"references":[{"surah":7,"verses":[172]}],"verseLabel":"الأعراف: 172","question":"ما سرّ التعبير بضمير العظمة في قوله تعالى: ﴿وإذ أخذنا ميثاقكم﴾؟","answer":"إضافة فعل الأخذ إلى ضمير العظمة ﴿نا﴾ تُشعر بقوة الآخذ وعظمة الميثاق، وتؤكد وجوب الوفاء به؛ فالذي تولّى أخذَه هو الله تعالى، وقد أخذه بقوة على بني إسرائيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج1، ص549، تحت «بلاغة التعبير بمادة (أخذ) المضافة إلى ضمير العظمة (نا)»","url":""}]},{"id":"s7-1257","number":1257,"surah":7,"verses":[173],"references":[{"surah":7,"verses":[173]}],"verseLabel":"الأعراف: 173","question":"لماذا عطف العذر الثاني بـ﴿أو تقولوا﴾؟","answer":"العطف يعرض عذرًا آخر مغايرًا للأول: بعد دعوى الغفلة تأتي دعوى تقليد الآباء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص131–132، تحت «دلالة أو في أو تقولوا»","url":""}]},{"id":"s7-1258","number":1258,"surah":7,"verses":[173],"references":[{"surah":7,"verses":[173]}],"verseLabel":"الأعراف: 173","question":"لماذا جاء القصر: ﴿إنما أشرك آباؤنا من قبل﴾؟","answer":"القصر يجعلون أصل الشرك محصورًا في الآباء السابقين، محاولين نفي المسؤولية عن أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص132–133، تحت عنوان «سر التعبير بأسلوب القصر في إنما أشرك آباؤنا»","url":""}]},{"id":"s7-1259","number":1259,"surah":7,"verses":[173],"references":[{"surah":7,"verses":[173]}],"verseLabel":"الأعراف: 173","question":"ما دلالة قولهم: ﴿من قبل﴾ مع وضوح سبق الآباء؟","answer":"زادوه لتأكيد سبق الآباء وبعد العهد، وبناء حجتهم على أنهم لم يكونوا مبتدئي الشرك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص133، تحت «دلالة التعبير بالظرف»","url":""}]},{"id":"s7-1260","number":1260,"surah":7,"verses":[173],"references":[{"surah":7,"verses":[173]}],"verseLabel":"الأعراف: 173","question":"لماذا وصفوا أنفسهم بـ﴿ذرية من بعدهم﴾؟","answer":"صوروا أنفسهم نسلًا تابعًا جاء بعد الآباء، ليجعلوا التقليد قدَرًا ورثوه لا اختيارًا يحاسبون عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص133، تحت عنوان «دلالة الإيجاز في قوله وكنا ذرية من بعدهم»","url":""}]},{"id":"s7-1261","number":1261,"surah":7,"verses":[173],"references":[{"surah":7,"verses":[173]}],"verseLabel":"الأعراف: 173","question":"لماذا سألوا: ﴿أفتهلكنا بما فعل المبطلون﴾؟","answer":"الاستفهام استعطاف احتجاجي بلسانهم: أتؤاخذنا بفعل من أبطل قبلنا؟ وقد قطع الميثاق هذا العذر لأن كل نفس مسؤولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص135–136، تحت عنوان «علاقة جملة الاستفهام أفتهلكنا بما قبلها»","url":""}]},{"id":"s7-1262","number":1262,"surah":7,"verses":[173],"references":[{"surah":7,"verses":[173]}],"verseLabel":"الأعراف: 173","question":"لماذا سمى الآباء ﴿المبطلون﴾ لا «المشركون»؟","answer":"الإبطال يشمل الشرك ونقض العهد وإبطال أثر العقول وأقوال الرسل باتباع الباطل. فهو أوسع من وصف الشرك وحده، ويلائم مقام دفع العذر بالتقليد الذي أبطلوا به مقتضى الميثاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص136، تحت «دلالة التعبير بلفظ المبطلون»","url":""}]},{"id":"s7-1263","number":1263,"surah":7,"verses":[174],"references":[{"surah":7,"verses":[174]}],"verseLabel":"الأعراف: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿وكذلك نفصل الآيات﴾؟","answer":"أي مثل هذا التفصيل الواضح لحجة الفطرة وأعذار البشر نفصل سائر الآيات؛ فالكاف تشير إلى البيان السابق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص139–140، تحت عنوان «بلاغة أسلوب التشبيه في قوله وكذلك نفصل الآيات»","url":""}]},{"id":"s7-1264","number":1264,"surah":7,"verses":[174],"references":[{"surah":7,"verses":[174]}],"verseLabel":"الأعراف: 174","question":"ما دلالة إيثار التعبير بالتفصيل بدل البيان؟","answer":"التفصيل يميز المعاني بعضها من بعض ويبين أجزاءها وجهاتها، فيكون البيان أوضح وأبعد عن الاختلاط.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص140، تحت عنوان «إيثار التعبير بالتفصيل بدل البيان»","url":""}]},{"id":"s7-1629","number":1629,"surah":7,"verses":[174],"references":[{"surah":7,"verses":[174]}],"verseLabel":"الأعراف: 174","question":"ما دلالة التفصيل والبيان؟","answer":"كل حجة تعرض بما يكشف مدلولها ويتيح النظر في وجوهها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص143، تحت عنوان «التفصيل والبيان»","url":""}]},{"id":"s7-1265","number":1265,"surah":7,"verses":[174],"references":[{"surah":7,"verses":[174]}],"verseLabel":"الأعراف: 174","question":"لماذا جمع ﴿الآيات﴾؟","answer":"الجمع لتعدد الدلائل المبينة للتوحيد والمسؤولية وبطلان الأعذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص139–140، تحت عنوان «بلاغة أسلوب التشبيه في قوله وكذلك نفصل الآيات»","url":""}]},{"id":"s7-1266","number":1266,"surah":7,"verses":[174],"references":[{"surah":7,"verses":[174]}],"verseLabel":"الأعراف: 174","question":"ما سرّ التعبير في قوله تعالى: ﴿ولعلهم يرجعون﴾ لا «لعلهم يؤمنون»؟","answer":"الرجوع أنسب لأن معرفة الرب مركوزة في الفطرة؛ فالمطلوب عودتهم إلى أصل أقروا به، لا إيمان مبتدأ لا سابقة له.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص141–142، تحت «بلاغة المجاز بالاستعارة في التعبير بالفعل يرجعون»","url":""}]},{"id":"s7-1267","number":1267,"surah":7,"verses":[174],"references":[{"surah":7,"verses":[174]}],"verseLabel":"الأعراف: 174","question":"لماذا عطف غاية الرجوع بالواو؟","answer":"الواو تجمع غايتين للتفصيل: إقامة الحجة وفتح طريق الرجوع، أو تعطف الرجاء على محذوف مفهوم كالتدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص141، تحت «دلالة عطف الإنشاء على الخبر»","url":""}]},{"id":"s7-1268","number":1268,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"لماذا أمر النبي ﷺ: ﴿واتل عليهم نبأ الذي آتيناه آياتنا﴾؟","answer":"أمره أن يتلو القصة للعبرة والتحذير من عالم عرف الآيات ثم تركها؛ فهي مثال حي لمن لا ينتفع بالعلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص146، تحت عنوان «سر التعبير بالفعل واتل»","url":""}]},{"id":"s7-1269","number":1269,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]},{"surah":9,"verses":[70]}],"verseLabel":"الأعراف: 175؛ التوبة: 70","question":"لماذا عبّر القرآن بـ﴿نبأ﴾ في قوله: ﴿واتل عليهم نبأ الذي آتيناه آياتنا﴾، ولم يقل: خبره؟","answer":"لأن النبأ خبر عظيم ظاهر ذو أهمية يلتفت إليه أولو الألباب، وهذه القصة جسيمة العبرة والعاقبة؛ أما الخبر فقد يطلق على ما لا يبلغ هذا القدر من الشأن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص147، تحت «إيثار التعبير بالنبأ دون الخبر»","url":""}]},{"id":"s7-1270","number":1270,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"لماذا لم يسمِّ الرجل فقال: ﴿الذي آتيناه آياتنا﴾؟","answer":"عبر عنه بالموصول ليبرز الوصف الذي تقوم عليه العبرة: إيتاؤه الآيات ثم انسلاخه منها. فالمقصود عرض حاله وفعله، وتكفي الصلة للتعريف به من غير التصريح باسمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص148–149، تحت «سر التعبير بالاسم الموصول الخاص الذي»","url":""}]},{"id":"s7-1271","number":1271,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿آتيناه آياتنا﴾ لا «علمناه»؟","answer":"الإيتاء تمليك وتمكين من الآيات والحجج، وهو أبلغ من مجرد تعليمه معلومة؛ فقد صارت في حوزته ثم نبذها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص149–150، تحت عنوان «بلاغة إسناد الفعل إلى نون العظمة في قوله آتيناه»","url":""}]},{"id":"s7-1272","number":1272,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"لماذا أضاف الآيات إلى الله؟","answer":"لتشريفها وتعظيم جرم الانسلاخ منها؛ فهي آيات الله لا معارف بشرية عادية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص149، تحت «بلاغة إسناد الفعل إلى نون العظمة في قوله آتيناه»","url":""}]},{"id":"s7-1273","number":1273,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما دلالة الاستعارة في قوله فانسلخ منها؟","answer":"صوّر الآيات كأنها كانت محيطة به ثم نزع نفسه منها نزعًا كاملًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص149، تحت عنوان «بلاغة الاستعارة في قوله فانسلخ منها»","url":""}]},{"id":"s7-1630","number":1630,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما دلالة إيثار التعبير بالانسلاخ على الانقطاع؟","answer":"الانسلاخ خروج الشيء من جلده الملتصق به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص151، تحت عنوان «إيثار التعبير بالانسلاخ على الانقطاع»","url":""}]},{"id":"s7-1274","number":1274,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"لماذا عُدّي الانسلاخ بـ﴿منها﴾؟","answer":"﴿منها﴾ تبين أنه خرج من داخل محيط الآيات الذي كان متلبسًا به، فاشتد معنى المفارقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص149–150، تحت «بلاغة الاستعارة في قوله فانسلخ منها»","url":""}]},{"id":"s7-1275","number":1275,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"لماذا عطف ﴿فأتبعه الشيطان فكان من الغاوين﴾ بفاءين؟","answer":"الفاء الأولى تبين أن ملاحقة الشيطان ترتبت سريعًا على انسلاخه، والثانية أن دخوله في الغاوين كان نتيجة تلك الملاحقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص151–152، تحت عنوان «ترتيب أفعال الانسلاخ والاتباع والكون من الغاوين بفاء العطف»","url":""}]},{"id":"s7-1276","number":1276,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿فأتبعه الشيطان﴾ لا «فتبعه الشيطان»؟","answer":"﴿أتبعه﴾ بمعنى لحقه وأدركه بعد طلب، فيصور الشيطان مطاردًا له حتى استحوذ عليه؛ وهو أقوى من مجرد المصاحبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص151–152، تحت «بلاغة التعبير بالفعل فأتبعه»","url":""}]},{"id":"s7-1277","number":1277,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما دلالة الشيطان والجن وإبليس؟","answer":"يبين أن مفارقة الآيات مكنت الشيطان منه فأدركه واستولى على أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص155، تحت عنوان «الشيطان والجن وإبليس»","url":""}]},{"id":"s7-1631","number":1631,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما سر التعبير بالفعل فأتبعه؟","answer":"لفظ الشيطان يدل على التمرد والبعد عن الخير، فيناسب ما آل إليه حال المنسلخ من الغواية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص151، تحت عنوان «بلاغة التعبير بالفعل فأتبعه»","url":""}]},{"id":"s7-1278","number":1278,"surah":7,"verses":[175],"references":[{"surah":7,"verses":[175]}],"verseLabel":"الأعراف: 175","question":"ما سرّ التعبير في قوله تعالى: ﴿فكان من الغاوين﴾ لا «فغوى»؟","answer":"﴿كان من الغاوين﴾ تدخله في زمرة استقر فيها الغي وصار وصفًا لها، وهو أبلغ من وقوع غي عابر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص152–153، تحت عنوان «سر التعبير بقوله من الغاوين»","url":""}]},{"id":"s7-1279","number":1279,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو شئنا لرفعناه بها﴾، وعلّق الرفع بالمشيئة؟","answer":"يعلق الرفع بمشيئة الله ليبين أن إيتاء الآيات وحده لا يستلزم الرفعة، بل تكون بالاهتداء والعمل بها بتوفيقه. ثم يذكر إخلاده إلى الأرض واتباعه الهوى سببًا في حرمانه من هذه الرفعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص159، تحت عنوان «دلالة حذف مفعول المشيئة»","url":""}]},{"id":"s7-1280","number":1280,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"لماذا عُدّي الرفع بالباء: ﴿بها﴾؟","answer":"الباء للسببية؛ أي لرفعناه بالعمل بالآيات واتباع الحق الذي تدل عليه. فالرفعة ليست بمجرد حيازة العلم، وإنما بالانتفاع به والعمل بمقتضاه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص161، تحت «دلالة الباء في قوله لرفعناه بها»","url":""}]},{"id":"s7-1281","number":1281,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما دلالة الباء في قوله لرفعناه بها؟","answer":"لأنه اختار الإخلاد إلى الأرض واتباع الهوى.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص161–162، تحت عنوان «دلالة الباء في قوله لرفعناه بها»","url":""}]},{"id":"s7-1632","number":1632,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما دلالة الاستدراك بعد المشيئة في قوله ولكنه أخلد؟","answer":"الآيات لا ترفع من ينخلع منها ويعطل مقتضاها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص161–162، تحت عنوان «دلالة الاستدراك بعد المشيئة في قوله ولكنه أخلد»","url":""}]},{"id":"s7-1282","number":1282,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿ولكنه أخلد إلى الأرض﴾؟","answer":"الإخلاد شدة الميل مع الركون والدوام، والأرض كناية عن الدنيا وشهواتها؛ فصوّر نفسه ملتصقة بالسفول.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص162، تحت عنوان «بلاغة الاستعارة التمثيلية أخلد إلى الأرض»","url":""}]},{"id":"s7-1283","number":1283,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"لماذا عُدّي ﴿أخلد﴾ بـ﴿إلى﴾؟","answer":"﴿إلى﴾ تصور اتجاه ميله وقصده نحو الأرض حتى ركن إليها واستقر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص162، تحت عنوان «بلاغة الاستعارة التمثيلية أخلد إلى الأرض»","url":""}]},{"id":"s7-1284","number":1284,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما وجه البلاغة في الاستعارة التمثيلية أخلد إلى الأرض؟","answer":"قوبل العلو الذي تمنحه الآيات بالسقوط إلى الأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص161–162، تحت عنوان «بلاغة الاستعارة التمثيلية أخلد إلى الأرض»","url":""}]},{"id":"s7-1633","number":1633,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما دلالة الاستعارة في جواب الشرط لرفعناه بها؟","answer":"المقابلة تجسد التفاوت بين طريق الوحي وطريق الشهوة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص161–162، تحت عنوان «بلاغة الاستعارة في جواب الشرط لرفعناه بها»","url":""}]},{"id":"s7-1285","number":1285,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿واتبع هواه﴾ بعد ﴿أخلد إلى الأرض﴾؟","answer":"الإخلاد يصف تعلقه بالدنيا، واتباع الهوى يبين القائد الداخلي لهذا التعلق؛ فاختار رغباته على الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص163–164، تحت عنوان «بلاغة الاستعارة في واتبع هواه»","url":""}]},{"id":"s7-1286","number":1286,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"لماذا شُبّه بالكلب تحديدًا؟","answer":"لأن الكلب يلهث في حالتي الطرد والترك، فضرب به مثل من استولى عليه الطمع والهوى فلا يهدأ بالموعظة ولا بتركها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص166، تحت عنوان «سر التعبير عن وصف سفالة المكذب بتشبيهه بالكلب»","url":""}]},{"id":"s7-1287","number":1287,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿إن تحمل عليه يلهث أو تتركه يلهث﴾؟","answer":"المعنى أن حاله واحدة: إن تزجره أو تعظه يظل تابعًا لهواه، وإن تتركه يظل كذلك؛ كدوام لهث الكلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص167، تحت عنوان «تقييد حال الكلب بجملة شرطية إن تحمل ودلالة الحمل عليه»","url":""}]},{"id":"s7-1288","number":1288,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما سرّ تقديم الحمل عليه على تركه؟","answer":"قدم الحمل لأنه صورة أشد تكشف لهث الكلب أولًا، ثم جاء الترك ليثبت أن اللهث طبع ملازم لا أثر تعب عارض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص167، تحت «دلالة تقديم الحمل على الترك»","url":""}]},{"id":"s7-1289","number":1289,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"لماذا كرر ﴿يلهث﴾؟","answer":"كرر الفعل لإثبات تساوي الحالتين واستقلال كل شرط بنتيجته؛ فهو يلهث في الشدة والراحة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص166–167، تحت عنوان «تقييد حال الكلب بجملة شرطية إن تحمل ودلالة الحمل عليه»","url":""}]},{"id":"s7-1290","number":1290,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك مثل القوم الذين كذبوا بآياتنا﴾ بعد مثل الفرد؟","answer":"نقل المثل من الرجل الواحد إلى كل قوم يكذبون بالآيات؛ فحاله نموذج متكرر لا حادثة فردية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص167–168، تحت عنوان «دلالة التعبير باسم الإشارة ذلك»","url":""}]},{"id":"s7-1291","number":1291,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"لماذا أمر: ﴿فاقصص القصص لعلهم يتفكرون﴾؟","answer":"أمره بعرض القصص وضرب الأمثال لتقريب العبرة وتحريك التفكر في أسباب الانحراف وعواقبه. فالتمثيل بصورة محسوسة يعين السامع على فهم الحال والاتعاظ بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص169، تحت عنوان «دلالة قوله فاقصص القصص»","url":""}]},{"id":"s7-1292","number":1292,"surah":7,"verses":[176],"references":[{"surah":7,"verses":[176]}],"verseLabel":"الأعراف: 176","question":"لماذا خُتمت بـ﴿لعلهم يتفكرون﴾ لا «يتذكرون»؟","answer":"التفكر هو النظر في تركيب المثل وأسبابه ومآله واستخراج العبرة، وهو أنسب من مجرد تذكر معلومة سابقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص171، تحت عنوان «يتفكرون ويتذكرون»","url":""}]},{"id":"s7-1293","number":1293,"surah":7,"verses":[177],"references":[{"surah":7,"verses":[177]}],"verseLabel":"الأعراف: 177","question":"لماذا افتتحت بـ﴿ساء مثلًا﴾؟","answer":"بدأ بفعل الذم ليواجه السامع فورًا بقبح هذا المثل قبل إعادة وصف أصحابه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص174–175، تحت عنوان «بلاغة الجملة الاستئنافية»","url":""}]},{"id":"s7-1294","number":1294,"surah":7,"verses":[177],"references":[{"surah":7,"verses":[177]}],"verseLabel":"الأعراف: 177","question":"ما سرّ تقديم ﴿مثلًا﴾ على ﴿القوم﴾؟","answer":"﴿مثلًا﴾ تمييز يفسر الضمير المبهم في فعل الذم، وبه يتوجه السوء إلى المثل والحال قبل تعيين أصحابه. والتقدير في أحد الأوجه: ساء مثلًا مثل القوم، فحذف المضاف وأقيم القوم مقامه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص175–176، تحت «سر الحذف والتقديم في قوله مثلًا القوم»","url":""}]},{"id":"s7-1295","number":1295,"surah":7,"verses":[177],"references":[{"surah":7,"verses":[177]}],"verseLabel":"الأعراف: 177","question":"لماذا أظهر ﴿القوم الذين كذبوا بآياتنا﴾ بدل الضمير؟","answer":"أظهر الموصول بدل الضمير لتكرير سبب الذم في السمع: تكذيبهم بآيات الله هو الذي جعل مثلهم سيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص176، تحت «فائدة ذكر لفظة القوم موصوفًا بالموصول»","url":""}]},{"id":"s7-1298","number":1298,"surah":7,"verses":[177],"references":[{"surah":7,"verses":[177]}],"verseLabel":"الأعراف: 177","question":"ما دلالة الجمع بين ﴿كانوا﴾ و﴿يظلمون﴾؟","answer":"تدل ﴿كانوا﴾ مع المضارع على أن ظلمهم كان شأنًا ثابتًا يتجدد منهم، لا حادثة عابرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص178، تحت عنوان «بلاغة التعبير بالماضي في كانوا»","url":""}]},{"id":"s7-1299","number":1299,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما سرّ الإفراد في ﴿فهو المهتدي﴾ والجمع في ﴿فأولئك هم الخاسرون﴾؟","answer":"في ﴿فهو المهتدي﴾ روعي لفظ من المفرد، وفي ﴿فأولئك هم الخاسرون﴾ روعي معناها العام. ويذكر المصدر مناسبة أخرى: طريق المهتدين واحد في مقابل تعدد طرق الضلال، مع تشريف الفرد المهتدي وإدراج الضالين في زمرة الخاسرين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص186، تحت «بلاغة التعبير بالجمع مقابل المفرد المهتدي والخاسرون»","url":""}]},{"id":"s7-1300","number":1300,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما سرّ إظهار اسم الله في ﴿من يهد الله﴾؟","answer":"أُظهر الاسم الجليل لتشريف الهداية والتنويه بأن مصدرها الله وحده، مع زيادة التقرير والوضوح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص183، تحت «بلاغة إسناد الفعل إلى اسم الجلالة الله»","url":""}]},{"id":"s7-1301","number":1301,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما دلالة اسم الفاعل المعرّف في ﴿فهو المهتدي﴾؟","answer":"يفيد أن من هداه الله هو المتحقق بالهداية الكاملة الثابتة، وأنه المختص بحقيقتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص183، تحت «بلاغة التعبير بأسلوب القصر»","url":""}]},{"id":"s7-1302","number":1302,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما سرّ عدم إعادة اسم الله في قوله تعالى: ﴿ومن يضلل﴾؟","answer":"اكتفى بالضمير المستتر في ﴿يضلل﴾ لظهور مرجعه من ﴿من يهد الله﴾، وربطت الواو بين الحالتين المتقابلتين. فالمعنى متصل واضح من غير حاجة إلى إعادة الاسم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص183–184، تحت «دلالة العطف بحرف الواو في قوله ومن يضلل»","url":""}]},{"id":"s7-1303","number":1303,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما سرّ الانتقال إلى الجمع في جواب الشرط: ﴿فأولئك﴾؟","answer":"انتقل إلى الجمع مراعاةً لمعنى ﴿من﴾؛ فهي وإن أفرد لفظها تشمل كل من وقع في الضلال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص186، تحت «بلاغة التعبير بالجمع مقابل المفرد المهتدي والخاسرون»","url":""}]},{"id":"s7-1304","number":1304,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما دلالة ضمير الفصل ﴿هم﴾ في ﴿أولئك هم الخاسرون﴾؟","answer":"يفيد تقوية الحكم وقصر جنس الخسران الكامل عليهم؛ إذ خسروا أنفسهم والهداية والمآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص184–185، تحت عنوان «ورود ضمير الفصل هم ودلالته على التأكيد»","url":""}]},{"id":"s7-1305","number":1305,"surah":7,"verses":[178],"references":[{"surah":7,"verses":[178]}],"verseLabel":"الأعراف: 178","question":"ما مناسبة مقابلة الهداية بالخسران بدل الضلال؟","answer":"لأن الضلال سبب، وعاقبته الجامعة هي الخسران؛ فالمقابلة انتقلت من الطريق الصحيح إلى نتيجة فقده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص185، تحت «بلاغة حذف التقابل في المغايرة بين فعل الشرط وجوابه»","url":""}]},{"id":"s7-1306","number":1306,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما دلالة الواو في قوله ولقد ذرأنا؟","answer":"ي الواو فتصل هذا البيان بما قبله، وليست بذاتها أداة التوكيد هنا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص191–192، تحت عنوان «دلالة الواو في قوله ولقد ذرأنا»","url":""}]},{"id":"s7-1634","number":1634,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما وجه البلاغة في استخدام الإنشاء غير الطلبي في القسم المسوق؟","answer":"أكد الخبر بالقسم المقدر واللام وقد لغرابة مضمونه وشدة أثره: أن كثيرًا ممن أوتوا المدارك لم ينتفعوا بها فصاروا إلى هذا المصير.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص191–192، تحت عنوان «بلاغة استخدام الإنشاء غير الطلبي في القسم المسوق»","url":""}]},{"id":"s7-1307","number":1307,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما سرّ التعبير بـ﴿ذرأنا﴾ بدل «خلقنا»؟","answer":"الذرء هو الخلق مع معنى الإيجاد والبث والتكثير، فناسب ذكر الكثير من الجن والإنس.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص188، تحت عنوان «شرح المفردات: ذرأنا»","url":""}]},{"id":"s7-1308","number":1308,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما دلالة اللام في قوله لجهنم؟","answer":"يذكر المصدر وجهين: لام الصيرورة والعاقبة، أو التعليل باعتبار الأفعال التي تفضي إلى جهنم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص193، تحت عنوان «دلالة اللام في قوله لجهنم»","url":""}]},{"id":"s7-1635","number":1635,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما وجه البلاغة في استخدام المجاز المرسل في قوله لجهنم؟","answer":"في الوجه الثاني يراد السبب المؤدي إليها، ويؤكد السياق إصرارهم على الباطل وعدم انتفاعهم بآلات الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص193، تحت عنوان «بلاغة استخدام المجاز المرسل في قوله لجهنم»","url":""}]},{"id":"s7-1309","number":1309,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما سرّ تقديم الجن على الإنس؟","answer":"قُدموا لتقدم خلقهم، ولأن المقام يستوعب الصنفين المكلفين مبتدئًا بالأسبق وجودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص195–196، تحت «بلاغة تقديم الجن على الإنس»","url":""}]},{"id":"s7-1310","number":1310,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما دلالة إسناد الفقه إلى القلوب في ﴿لهم قلوب لا يفقهون بها﴾؟","answer":"القلب في الاستعمال القرآني موضع الإدراك والتدبر والاعتبار؛ فنفي الفقه عنه نفي للانتفاع العقلي بالحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص189، تحت عنوان «شرح المفردات: قلوب»","url":""}]},{"id":"s7-1311","number":1311,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما سرّ تكرار ﴿لهم﴾ في ذكر القلوب والأعين والآذان؟","answer":"التكرار يفصل كل نعمة ويقرر قيام الحجة بها مستقلة؛ فقد عطلوا القلب والبصر والسمع جميعًا عن غاياتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص198، تحت «نكتة الإطناب بإعادة الخبر لهم مع القلوب والأعين والآذان»","url":""}]},{"id":"s7-1312","number":1312,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"كيف يُفهم نفي الفقه والإبصار والسماع مع سلامة الجوارح؟","answer":"المنفي هو الانتفاع بهذه الجوارح في إدراك آيات الحق وقبولها، لا أصل وظائفها الحسية؛ فهي موجودة ولكنها معطلة عن غايتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص197، تحت عنوان «وجه حذف المفعول به في مقام الفقه والبصر والسمع»","url":""}]},{"id":"s7-1313","number":1313,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما سرّ ترتيب القلوب ثم الأعين ثم الآذان؟","answer":"بدأ بالقلب لأنه محل الفقه والحكم، ثم ذكر العين والأذن لأنهما طريقا وصول المشاهدات والمسموعات إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص196–197، تحت عنوان «سر تقديم الأعين على الآذان»","url":""}]},{"id":"s7-1314","number":1314,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما وجه تشبيههم بالأنعام في ﴿أولئك كالأنعام﴾؟","answer":"لأنهم حصروا مداركهم في المحسوس والشهوة ولم يستعملوها في معرفة الحق، فشابهوا الأنعام في الاقتصار على مطالب الجسد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص201–202، تحت «براعة التشبيه المجمل في قوله أولئك كالأنعام»","url":""}]},{"id":"s7-1315","number":1315,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما دلالة الترقي من ﴿كالأنعام﴾ إلى ﴿بل هم أضل﴾؟","answer":"هم أضل لأن الأنعام لم تُعطَ وسائل التكليف والتمييز ثم تعطلها، أما هؤلاء فأوتوا المدارك والحجة وأعرضوا عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص202–203، تحت «معنى بل في قوله بل هم أضل»","url":""}]},{"id":"s7-1316","number":1316,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما سرّ تكرار اسم الإشارة ﴿أولئك﴾؟","answer":"أعيد للتنبيه عليهم بعد تمام وصفهم، ولتثبيت حكم جديد مستقل: أنهم الغافلون حقًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص201، تحت عنوان «دقيقة التعبير باسم الإشارة الدال على البعد»","url":""}]},{"id":"s7-1317","number":1317,"surah":7,"verses":[179],"references":[{"surah":7,"verses":[179]}],"verseLabel":"الأعراف: 179","question":"ما مناسبة ختم الآية بـ﴿أولئك هم الغافلون﴾؟","answer":"الغفلة هي الجامع الذي نشأ عنه تعطيل القلب والعين والأذن، فجاء الختام كاشفًا أصل ضلالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص204–205، تحت عنوان «سر التعبير بلفظ الغافلون دون الضالون»","url":""}]},{"id":"s7-1318","number":1318,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما دلالة تقديم ﴿ولله﴾ في ﴿ولله الأسماء الحسنى﴾؟","answer":"التقديم يفيد الاختصاص: الأسماء البالغة غاية الحسن مختصة بالله على وجه الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص211–212، تحت «فائدة القصر بتقديم ما حقه التأخير في مفتتح الآية»","url":""}]},{"id":"s7-1319","number":1319,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما دلالة جمع ﴿الأسماء﴾؟","answer":"الجمع يدل على تعدد الأسماء الدالة على صفات الكمال، مع وحدة المسمى سبحانه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص213، تحت عنوان «معنى أل الاستغراقية في الأسماء»","url":""}]},{"id":"s7-1320","number":1320,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما سرّ وصف الأسماء بـ﴿الحسنى﴾ بدل «الحسنة»؟","answer":"﴿الحسنى﴾ مؤنث الأحسن، فتدل على بلوغ أسماء الله الغاية العليا في الحسن والكمال، لا مجرد اتصافها بالحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص213–214، تحت «سر اختيار كلمة الحسنى»","url":""}]},{"id":"s7-1321","number":1321,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما مناسبة تفريع ﴿فادعوه بها﴾ على قوله تعالى: ﴿ولله الأسماء الحسنى﴾؟","answer":"لما ثبت اختصاصه بالأسماء الحسنى ترتب عليه أن يُدعى ويُثنى عليه بها، باختيار الاسم المناسب للمطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص214، تحت عنوان «معنى الفاء في قوله فادعوه بها»","url":""}]},{"id":"s7-1322","number":1322,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما معنى الفاء في قوله فادعوه بها؟","answer":"الدعاء بها يجمع الطلب وتعظيم الله بما له من الكمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص214، تحت عنوان «معنى الفاء في قوله فادعوه بها»","url":""}]},{"id":"s7-1636","number":1636,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما معنى فادعوه في السياق؟","answer":"يدعى الله ويثنى عليه بأسمائه الحسنى، فيذكر الداعي منها ما يناسب مطلوبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص210، تحت عنوان «شرح المفردات: فادعوه»","url":""}]},{"id":"s7-1323","number":1323,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما سرّ الأمر بـ﴿وذروا الذين يلحدون في أسمائه﴾؟","answer":"المعنى: دعوا من يصرون على الإلحاد بعد قيام الحجة، ولا تتبعوا طريقتهم؛ فقد تولى الوعيد بيان جزائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص217، تحت عنوان «علة الإظهار في قوله في أسمائه»","url":""}]},{"id":"s7-1324","number":1324,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما دلالة الاستعارة في قوله يلحدون؟","answer":"تصور انحرافهم واقعًا في شأن الأسماء نفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص215، تحت عنوان «بلاغة الاستعارة في قوله يلحدون»","url":""}]},{"id":"s7-1637","number":1637,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما وجه البلاغة في استعمال حرف الظرفية في؟","answer":"بتغييرها أو تحريف معانيها أو إطلاق ما لا يليق بالله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص217، تحت عنوان «بلاغة استعمال حرف الظرفية في»","url":""}]},{"id":"s7-1325","number":1325,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما سر التعبير بـ﴿سيُجزون ما كانوا يعملون﴾ بدل التصريح بالعذاب؟","answer":"حذفت الباء من معنى المجازاة بما كانوا يعملون، فصور الجزاء كأنه العمل نفسه لشدة موافقته له. وفي الإبهام وعيد وتهويل، مع بيان أن الجزاء عدل مطابق لأعمالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص218–219، تحت عنوان «سر التعبير بقوله ما كانوا يعملون»","url":""}]},{"id":"s7-1326","number":1326,"surah":7,"verses":[180],"references":[{"surah":7,"verses":[180]}],"verseLabel":"الأعراف: 180","question":"ما دلالة السين في ﴿سيجزون ما كانوا يعملون﴾؟","answer":"تفيد السين تأكيد وقوع الجزاء في المستقبل، وفي السياق وعيد للمُلحدين في أسماء الله يردعهم عن إلحادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص218، تحت «علة التعبير بحرف السين»","url":""}]},{"id":"s7-1327","number":1327,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما مناسبة قوله تعالى: ﴿وممن خلقنا أمة﴾ بعد ذكر من ذُرئوا لجهنم؟","answer":"جاءت مقابلةً للفريق الغافل؛ فكما وُجد الكثير المعرض، وُجدت جماعة مهتدية تقيم الحق والعدل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص225، تحت «عطف المقابلة بجملته وزبدته، بين الآية وما قبلها»","url":""}]},{"id":"s7-1328","number":1328,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما دلالة إسناد الخلق إلى ضمير العظمة في ﴿وممن خلقنا أمة﴾؟","answer":"يبرز عظمة الربوبية، ويؤكد أن وجود أمة مهتدية داعية إلى الحق نعمة من الله وتأييد منه، فلا يخلو خلقه من هداة مهديين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص226–227، تحت عنوان «بلاغة إسناد الفعل إلى ضمير العظمة: خلقنا»","url":""}]},{"id":"s7-1329","number":1329,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما سر اختيار ﴿أمة﴾ في وصف الجماعة التي تهدي بالحق وتعدل به؟","answer":"يلائم لفظ الأمة جماعة تجتمع على الدين والحق وتقوم بهما في الناس، وفيه معنى الخيرية والكمال. أما الطائفة فتدل على قطعة من الجماعة، وقد تطلق على العدد القليل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص229–230، تحت «أمة وطائفة»","url":""}]},{"id":"s7-1330","number":1330,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما سر عدم التصريح باسم الأمة الخاتمة في قوله: ﴿وممن خلقنا أمة يهدون بالحق﴾؟","answer":"أُبهمت الأمة تفخيمًا لها وإعلاءً لشأنها؛ وأكثر المفسرين على أنها أمة محمد ﷺ، ولم تُعيّن باسمها ليبقى الوصف بالهداية والعدل هو العلامة البارزة عليها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص227، تحت «سر عدم التصريح بأن المراد بالأمة، الأمة الخاتمة»","url":""}]},{"id":"s7-1638","number":1638,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما دلالة التعبير بـ﴿قوم موسى﴾ دون «بني إسرائيل» أو «أهل الكتاب»؟","answer":"للدلالة على أنهم أتباع موسى المتمسكون بدينه قبل بعثة محمد ﷺ؛ فالإضافة إلى موسى تشعر باتباع رسالته والاقتداء به، لا بمجرد النسب إلى بني إسرائيل أو الانتساب العام إلى أهل الكتاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج14، ص723، تحت «دلالة التعبير بـ﴿قوم موسى﴾ دون (بني إسرائيل)، أو (أهل الكتاب)»","url":""}]},{"id":"s7-1331","number":1331,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما وجه البلاغة في معنى الباء في قوله بالحق وبه؟","answer":"الباء تفيد ملابسة الحق والاستعانة به، فالحق مصاحب لهدايتهم وعدلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص227–228، تحت عنوان «بلاغة معنى الباء في قوله بالحق وبه»","url":""}]},{"id":"s7-1639","number":1639,"surah":7,"verses":[181],"references":[{"surah":7,"verses":[181]}],"verseLabel":"الأعراف: 181","question":"ما دلالة وجه التعبير بالضمير موضع الظاهر؟","answer":"يعود الضمير في ﴿به﴾ إلى الحق نفسه، فيربط الحكم بالهداية إلى أصل واحد لا يتعدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص227–228، تحت عنوان «وجه التعبير بالضمير موضع الظاهر»","url":""}]},{"id":"s7-1332","number":1332,"surah":7,"verses":[182],"references":[{"surah":7,"verses":[182]}],"verseLabel":"الأعراف: 182","question":"ما مناسبة استئناف الوعيد بقوله تعالى: ﴿والذين كذبوا بآياتنا سنستدرجهم﴾؟","answer":"بعد ذكر الأمة القائمة بالحق عاد السياق إلى المكذبين ليبين أن إمهالهم ليس نجاة، بل استدراج يعقبه الجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص231–232، تحت عنوان «دلالة العطف في الآية الكريمة»","url":""}]},{"id":"s7-1333","number":1333,"surah":7,"verses":[182],"references":[{"surah":7,"verses":[182]}],"verseLabel":"الأعراف: 182","question":"ما الصورة التي يرسمها فعل ﴿سنستدرجهم﴾؟","answer":"يصور نقلهم درجة بعد درجة إلى الهلاك، مع توالي النعم والإمهال حتى يزدادوا اغترارًا وهم لا يشعرون بالمآل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص233–234، تحت عنوان «سر التعبير بكلمة سنستدرجهم»","url":""}]},{"id":"s7-1334","number":1334,"surah":7,"verses":[182],"references":[{"surah":7,"verses":[182]}],"verseLabel":"الأعراف: 182","question":"ما دلالة صيغة الاستفعال في ﴿سنستدرجهم﴾؟","answer":"تفيد المعالجة والتدرج؛ أي أخذهم شيئًا فشيئًا ودرجة بعد درجة، لا بالعقوبة الفجائية أول الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص233–234، تحت «سر التعبير بكلمة سنستدرجهم»","url":""}]},{"id":"s7-1335","number":1335,"surah":7,"verses":[182],"references":[{"surah":7,"verses":[182]}],"verseLabel":"الأعراف: 182","question":"ما دلالة السين في ﴿سنستدرجهم﴾؟","answer":"تدل السين على الاستقبال؛ ويدخل الإملاء المعطوف على الاستدراج في هذا الحكم على وجه العطف الذي يذكره المصدر. وفي السياق وعيد للمكذبين بما يستقبلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص237–238، تحت «معنى الواو في الآية»","url":""}]},{"id":"s7-1336","number":1336,"surah":7,"verses":[182],"references":[{"surah":7,"verses":[182]}],"verseLabel":"الأعراف: 182","question":"ما سرّ التعبير بـ﴿من حيث لا يعلمون﴾؟","answer":"يأتيهم الاستدراج من جهة لا يدركونها؛ إذ يحسبون النعم والإمهال إكرامًا، وهي طريق خفي إلى أخذهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص234، تحت «بلاغة الاستعارة التمثيلية»","url":""}]},{"id":"s7-1337","number":1337,"surah":7,"verses":[182],"references":[{"surah":7,"verses":[182]}],"verseLabel":"الأعراف: 182","question":"ما دلالة نفي العلم في ﴿لا يعلمون﴾؟","answer":"نفي العلم أعمق من نفي الإحساس العابر؛ فهم لا يفهمون حقيقة ما يجري ولا عاقبته، وإن شاهدوا ظاهره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص234–235، تحت «يعلمون ويشعرون»","url":""}]},{"id":"s7-1338","number":1338,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما سر اختيار ﴿وأملي لهم﴾ في سياق الوعيد؟","answer":"الإملاء يدل على إطالة المدة، أما الإمهال فقد يكون طويلًا أو قصيرًا وفيه معنى الإبطاء برفق. فاختير الإملاء لتهديد من طال تماديهم في المعاصي واغتروا بتأخير العقوبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص239–240، تحت «الإملاء والإمهال»","url":""}]},{"id":"s7-1339","number":1339,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما وجه عطف ﴿وأملي لهم﴾ على ﴿سنستدرجهم﴾؟","answer":"يذكر المصدر وجهين: أن يكون الإملاء معطوفًا داخلًا في الاستقبال الذي تدل عليه السين، أو معطوفًا خارجًا عن حكمها؛ لأن الإملاء إمهال وإطالة، بخلاف الاستدراج الذي يتتابع شيئًا فشيئًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص237–238، تحت «معنى الواو في الآية»","url":""}]},{"id":"s7-1340","number":1340,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما سرّ الانتقال من ﴿سنستدرجهم﴾ إلى ﴿وأملي﴾ بالإفراد؟","answer":"في الانتقال تنويع للخطاب وإيقاظ للسامع مع بقاء معنى التعظيم المفهوم من ﴿سنستدرجهم﴾. ويذكر المصدر أن الاستدراج قد يقع بواسطة وغيرها، أما تأخير الآجال وطول الإمهال فمن الله تعالى.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص238–239، تحت «بلاغة الالتفات من ضمير التكلم بالجمع إلى ضمير التكلم بالمفرد»","url":""}]},{"id":"s7-1341","number":1341,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما دلالة التوكيد في ﴿إن كيدي متين﴾؟","answer":"يؤكد أن الإمهال ليس عجزًا ولا إفلاتًا، وأن التدبير الذي ينتهي بأخذهم ثابت لا يتخلف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص239، تحت «بلاغة التذييل التعليلي التأكيدي في ختام الآية»","url":""}]},{"id":"s7-1342","number":1342,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما معنى كيدي في السياق؟","answer":"لأن ظاهر الإمهال وتوالي النعم إحسان، وعاقبته للمكذب المصر خذلان وأخذ من حيث لا يحتسب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص236، تحت عنوان «شرح المفردات: كيدي»","url":""}]},{"id":"s7-1640","number":1640,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما وجه البلاغة في التذييل التعليلي التأكيدي في ختام الآية؟","answer":"سمى هذا التدبير كيدًا، ووصفه بالمتانة لشدة إحكامه وعدم الإفلات منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص239، تحت عنوان «بلاغة التذييل التعليلي التأكيدي في ختام الآية»","url":""}]},{"id":"s7-1343","number":1343,"surah":7,"verses":[183],"references":[{"surah":7,"verses":[183]}],"verseLabel":"الأعراف: 183","question":"ما دلالة وصف الكيد بـ﴿متين﴾؟","answer":"﴿متين﴾ أي شديد قوي محكم لا يُدفع ولا يُنقض؛ فناسب حتمية الأخذ بعد الإمهال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص237، تحت عنوان «شرح المفردات: متين»","url":""}]},{"id":"s7-1344","number":1344,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما دلالة التوبيخ في ﴿أولم يتفكروا﴾؟","answer":"ينكر عليهم ترك التفكر الذي يكشف بطلان دعوى الجنون، مع وضوح سيرة النبي بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص243، تحت «بلاغة الاستفهام في قوله أولم يتفكروا»","url":""}]},{"id":"s7-1345","number":1345,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما سرّ اختيار ﴿يتفكروا﴾ بدل «يعلموا»؟","answer":"المطلوب أن يعملوا النظر في سيرته ودعوته حتى يصلوا بأنفسهم إلى انتفاء الجنون، لا أن يتلقوا مجرد خبر بذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص243–244، تحت عنوان «سر تعليق الفعل يتفكروا ودلالته في السياق»","url":""}]},{"id":"s7-1346","number":1346,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما دلالة وصف النبي ﷺ بأنه ﴿صاحبهم﴾؟","answer":"يذكرهم بطول صحبته ومخالطته لهم، فقد عرفوا عقله وصدقه قبل الرسالة؛ وذلك أقطع لدعوى الجنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص246، تحت «سر التعبير بالصحبة في قوله صاحبهم»","url":""}]},{"id":"s7-1347","number":1347,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما دلالة ﴿من﴾ في ﴿ما بصاحبهم من جنة﴾؟","answer":"زيدت بعد النفي لاستغراق الجنس؛ أي ليس به أدنى شيء من الجنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص246–247، تحت «دلالة التأكيد بمن الداخلة على نكرة منفية»","url":""}]},{"id":"s7-1348","number":1348,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما دلالة التنكير في لفظ جنة؟","answer":"جاءت ﴿جنة﴾ نكرة في سياق النفي المؤكد بـ﴿من﴾، لنفي أي نوع أو قدر من الجنون عنه ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص247، تحت عنوان «دلالة التنكير في لفظ جنة»","url":""}]},{"id":"s7-1641","number":1641,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما معنى جنة في السياق؟","answer":"أصل مادة الجن الستر، والجنون ستر للعقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص242، تحت عنوان «شرح المفردات: جنة»","url":""}]},{"id":"s7-1349","number":1349,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما دلالة القصر في ﴿إن هو إلا نذير مبين﴾؟","answer":"يقصر شأنه في هذا المقام على الرسالة والإنذار الواضح، وينفي عنه ما افتروه من الجنون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص247، تحت «بلاغة الختم بجملة القصر»","url":""}]},{"id":"s7-1350","number":1350,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما مناسبة وصفه ﷺ هنا بـ﴿نذير﴾؟","answer":"لأن المقام مواجهة المكذبين وتحديد مهمة الرسول في الإنذار والبلاغ، وفي لفظ النذير تنويه بشدة إنذاره ووضوحه وإظهار كمال رأفته بهم إذ ينذرهم بالعاقبة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص247–248، تحت عنوان «دلالة التنكير في وصف النبي المرسل بأنه نذير»","url":""}]},{"id":"s7-1351","number":1351,"surah":7,"verses":[184],"references":[{"surah":7,"verses":[184]}],"verseLabel":"الأعراف: 184","question":"ما دلالة وصف النذير بـ﴿مبين﴾؟","answer":"هو بيّن الرسالة، مظهر لما ينذر به بعبارة واضحة تقوم بها الحجة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص248، تحت «دلالة الصفة في لفظ مبين»","url":""}]},{"id":"s7-1352","number":1352,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما مناسبة الانتقال من ﴿أولم يتفكروا﴾ إلى ﴿أولم ينظروا﴾؟","answer":"دعاهم أولًا إلى التفكر في الرسول الذي يعرفونه، ثم وسع مجال النظر إلى ملكوت السماوات والأرض وسائر المخلوقات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص252، تحت «دلالة الجملة على الترقي في الإنكار والتعجيب من حالهم»","url":""}]},{"id":"s7-1353","number":1353,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة ﴿ملكوت﴾ بدل «ملك»؟","answer":"صيغة ﴿ملكوت﴾ تفيد عظمة الملك وسعته وإحكام السلطان، فتدعو إلى تدبر دلائل القدرة في الكون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص253–254، تحت «إيثار استخدام الملكوت على الملك»","url":""}]},{"id":"s7-1354","number":1354,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة ﴿في﴾ في ﴿ينظروا في ملكوت السماوات والأرض﴾؟","answer":"تجعل الملكوت مجالًا يتعمق فيه النظر والتدبر، لا مجرد شيء يمر عليه البصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص253، تحت «دلالة التعبير بالفعل المضارع وتعديته بحرف الجر في»","url":""}]},{"id":"s7-1355","number":1355,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما سرّ الجمع بين ﴿ملكوت السماوات والأرض﴾ و﴿ما خلق الله من شيء﴾؟","answer":"جمع بين النظر في النظام الكوني العظيم والنظر في كل مخلوق مفرد؛ لتعم دلائل القدرة الكليات والجزئيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص254، تحت عنوان «معنى العطف بالواو في قوله وما خلق»","url":""}]},{"id":"s7-1356","number":1356,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة الاسم الموصول ما؟","answer":"تؤكد ﴿من﴾ شمول النظر لكل ما يصدق عليه اسم الشيء من خلق الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص255–256، تحت عنوان «دلالة الاسم الموصول ما»","url":""}]},{"id":"s7-1642","number":1642,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة التأكيد بمن الداخلة على النكرة؟","answer":"لا تختص الدلالة بعظائم السماوات والأرض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص255–256، تحت عنوان «دلالة التأكيد بمن الداخلة على النكرة»","url":""}]},{"id":"s7-1357","number":1357,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما مناسبة عطف ﴿وأن عسى أن يكون قد اقترب أجلهم﴾؟","answer":"أضاف إلى حجة الكون باعثًا شخصيًا عاجلًا: قد يدنو موتهم فلا تبقى لهم مهلة للإيمان والتدبر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص256–257، تحت «معنى العطف في قوله وأن عسى»","url":""}]},{"id":"s7-1358","number":1358,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة استخدام قد ودخولها على الماضي ومعناها بما بعدها؟","answer":"جاءت ﴿قد﴾ مع الماضي لإفادة التحقيق في مضمون هذا التوقع، حتى يستحضروا قرب الموت أمرًا جديًا يحملهم على المبادرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص257–258، تحت عنوان «دلالة استخدام قد ودخولها على الماضي ومعناها بما بعدها»","url":""}]},{"id":"s7-1643","number":1643,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة حذف اسم أن ودلالته؟","answer":"يدعو السياق إلى توقع قرب الأجل والاستعداد له.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص257–258، تحت عنوان «حذف اسم أن ودلالته»","url":""}]},{"id":"s7-1359","number":1359,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما دلالة الاستفهام في ﴿فبأي حديث بعده يؤمنون﴾؟","answer":"استفهام إنكاري يقرر أنه إذا لم يحملهم القرآن على الإيمان، فلا حديث بعده أحق أن يؤمنوا به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص259–260، تحت «دلالة الاستفهام بالأداة أي»","url":""}]},{"id":"s7-1360","number":1360,"surah":7,"verses":[185],"references":[{"surah":7,"verses":[185]}],"verseLabel":"الأعراف: 185","question":"ما مرجع الضمير في ﴿بعده﴾؟","answer":"من وجوه عود الضمير القرآن، أي أي حديث أحق منه بالإيمان؟ ويذكر المصدر أيضًا عوده إلى الرسول بتقدير بعد خبره وقصته، أو إلى الأجل؛ فليس العود إلى القرآن الوجه الوحيد المذكور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص260–261، تحت «مرجع الضمير في بعده ودلالته»","url":""}]},{"id":"s7-1361","number":1361,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما مناسبة قوله تعالى: ﴿من يضلل الله فلا هادي له﴾ بعد الدعوة إلى النظر؟","answer":"يبين أن من أعرض عن دلائل الهداية حتى خُذل لا تنفعه كثرة الآيات، ولا يستطيع أحد أن يهديه من دون الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص264–265، تحت عنوان «موقع الجملة مما قبلها ودلالته في السياق»","url":""}]},{"id":"s7-1362","number":1362,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما دلالة ﴿لا﴾ النافية للجنس في ﴿فلا هادي له﴾؟","answer":"تنفي وجود أي هادٍ له نفيًا شاملًا، فتقرر انفراد الله بالهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص266–267، تحت «دلالة استخدام لا النافية للجنس في جواب الشرط»","url":""}]},{"id":"s7-1363","number":1363,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما دلالة إفراد ﴿هادي﴾؟","answer":"جاء نكرة في سياق النفي فيعم كل فرد من جنس الهداة؛ فلا يوجد له هادٍ واحد أيًا كان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص266–267، تحت عنوان «معنى اللام في له من الآية الكريمة»","url":""}]},{"id":"s7-1364","number":1364,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما سرّ التعبير بـ﴿ويذرهم﴾ بدل «ويتركهم»؟","answer":"﴿يذرهم﴾ أدل على الإهمال والتخلية بعد الإعراض، وفيها وعيد بأنهم يُتركون لعاقبة اختيارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص269، تحت «يذرهم ويتركهم»","url":""}]},{"id":"s7-1365","number":1365,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما الصورة في قوله تعالى: ﴿في طغيانهم﴾؟","answer":"صُور الطغيان ظرفًا يحيط بهم ويستغرقهم؛ فهم مغمورون في مجاوزة الحد لا يخرجون منها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص268، تحت «لطيفة الاستعارة في الحرف في»","url":""}]},{"id":"s7-1366","number":1366,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما دلالة إضافة الطغيان إليهم في ﴿طغيانهم﴾؟","answer":"تدل الإضافة على تمكّن الطغيان منهم واستمراره وملازمته لهم، حتى صار وصفًا معروفًا بهم في حياتهم وأحوالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص268، تحت «فائدة الإضافة في طغيانهم»","url":""}]},{"id":"s7-1367","number":1367,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما دلالة يعمهون ويعمون؟","answer":"العمه هو التحير والتردد مع عمى البصيرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص270، تحت عنوان «يعمهون ويعمون»","url":""}]},{"id":"s7-1644","number":1644,"surah":7,"verses":[186],"references":[{"surah":7,"verses":[186]}],"verseLabel":"الأعراف: 186","question":"ما معنى يعمهون في السياق؟","answer":"هو يصور اضطرابهم داخل الطغيان، لا مجرد مفارقة الطريق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص264، تحت عنوان «شرح المفردات: يعمهون»","url":""}]},{"id":"s7-1368","number":1368,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة المضارع في ﴿يسألونك عن الساعة﴾؟","answer":"يصور تجدد سؤالهم وتكراره، سواء كان سؤال اختبار أو استهزاء أو استعلام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص274–275، تحت «دلالة استخدام الفعل المضارع يسألونك»","url":""}]},{"id":"s7-1370","number":1370,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما الصورة في سؤالهم: ﴿أيان مرساها﴾؟","answer":"شُبهت الساعة بسفينة مضطربة لا يعلم الناس متى تستقر وترسو؛ فالسؤال عن وقت ثبوت وقوعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص277، تحت «بلاغة الاستعارة في مرساها»","url":""}]},{"id":"s7-1371","number":1371,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما سر تقديم ﴿أيان﴾ وتأخير ﴿مرساها﴾ في سؤالهم عن الساعة؟","answer":"لأن ﴿أيان﴾ اسم استفهام عن الوقت له الصدارة، فقدم على المبتدأ ﴿مرساها﴾. والسؤال عن وقت وقوع الساعة، فجيء بالاستفهام الذي يحدد جهة سؤالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص277، تحت «علة تأخير المسند إليه مرساها»","url":""}]},{"id":"s7-1372","number":1372,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة القصر في ﴿إنما علمها عند ربي﴾؟","answer":"يقصر علم وقت الساعة على الله وحده، وينفيه عن الرسول وعن كل مخلوق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص278، تحت «فائدة الجواب بأسلوب القصر»","url":""}]},{"id":"s7-1373","number":1373,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة المغايرة في المقصور عليه عند ربي وعند الله؟","answer":"جاء ﴿عند الله﴾ في جواب السؤال المتوهم فيه الإحاطة بحقيقة الساعة وشدتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص286، تحت عنوان «دلالة المغايرة في المقصور عليه عند ربي وعند الله»","url":""}]},{"id":"s7-1645","number":1645,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة لطيفة التعريف باسم الرب مضافًا ربي؟","answer":"جاء ﴿عند ربي﴾ جوابًا عن وقت وقوعها، وفي إضافة الرب إلى الرسول إشارة إلى التربية والإرشاد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص279، تحت عنوان «لطيفة التعريف باسم الرب مضافًا ربي»","url":""}]},{"id":"s7-1374","number":1374,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما الصورة في قوله تعالى: ﴿لا يجليها لوقتها إلا هو﴾؟","answer":"شُبه خفاء الساعة بشيء مستور لا يكشفه ويظهره في موعده إلا الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص280، تحت عنوان «وجه كمال الاتصال بين قوله لا يجليها لوقتها إلا هو وما قبله»","url":""}]},{"id":"s7-1375","number":1375,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة تقديم ﴿لوقتها﴾ في ﴿لا يجليها لوقتها إلا هو﴾؟","answer":"يبرز أن تجليها مرتبط بوقتها المقدر تحديدًا، ثم يقصر كشفها في ذلك الوقت على الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص280، تحت «دلالة تقديم لوقتها على فاعل الفعل يجليها»","url":""}]},{"id":"s7-1376","number":1376,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة قوله تعالى: ﴿ثقلت في السماوات والأرض﴾؟","answer":"عظُم أمرها وخفي علمها على أهل السماوات والأرض، وثقل ما يصاحبها من أهوال وتبدل للنظام الكوني.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص281–282، تحت عنوان «غرض الاستعارة في قوله ثقلت»","url":""}]},{"id":"s7-1377","number":1377,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما سرّ الجمع بين السماوات والأرض في ثقل الساعة؟","answer":"يفيد عموم شأنها لجميع العالم العلوي والسفلي، وأن علم وقتها محجوب عن الخلق كلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص281، تحت «دلالة التعبير بالقيد في السماوات والأرض»","url":""}]},{"id":"s7-1378","number":1378,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة القصر في ﴿لا تأتيكم إلا بغتة﴾؟","answer":"يقصر مجيئها على المباغتة؛ فلا تسبقها معرفة بوقتها تتيح الاستعداد عند حلوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص282، تحت «نكتة التعبير بأسلوب القصر»","url":""}]},{"id":"s7-1379","number":1379,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما سرّ تكرار ﴿يسألونك﴾ في الآية؟","answer":"الأول حكاية لسؤالهم عن وقت الساعة، والثاني يكشف هيئة سؤالهم كأنهم يظنون النبي بالغ الاستقصاء في علمها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص282–283، تحت «كمال الاتصال بين قوله يسألونك كأنك حفي عنها وقوله يسألونك عن الساعة»","url":""}]},{"id":"s7-1380","number":1380,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما معنى ﴿حفي﴾ في ﴿كأنك حفي عنها﴾؟","answer":"من معاني ﴿حفي﴾ المبالغ في السؤال والاستقصاء حتى يصير عالمًا بما يسأل عنه، وكأنهم يتوهمون أنه أحاط بعلم الساعة. ويذكر المصدر وجوهًا أخرى، منها العالم بها والمحب لهم؛ فلا يحصر اللفظ في وجه واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص284–285، تحت «تنوع معنى حفي في هذا السياق وأثره في المعنى»","url":""}]},{"id":"s7-1381","number":1381,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما مناسبة ختم الآية بـ﴿ولكن أكثر الناس لا يعلمون﴾؟","answer":"أكثر الناس لا يعلمون أن وقت الساعة مما استأثر الله بعلمه، ولا يدركون حكمة إخفائه؛ لذلك يكررون السؤال عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص288، تحت «بلاغة الختم بقوله ﴿ولكن اكثر الناس لا يعلمون﴾»","url":""}]},{"id":"s7-1382","number":1382,"surah":7,"verses":[187],"references":[{"surah":7,"verses":[187]}],"verseLabel":"الأعراف: 187","question":"ما دلالة نفي العلم عن أكثر الناس بعد قصر علم الساعة على الله؟","answer":"يقرر أن جهلهم ليس بموعدها وحده، بل بحقيقة اختصاص الله بعلمها وبالحكمة من إخفائها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص287–288، تحت عنوان «بلاغة الختم بقوله ولكن أكثر الناس لا يعلمون»","url":""}]},{"id":"s7-1383","number":1383,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما علة فصل الآية عما قبلها؟","answer":"يرد توهم أن الرسالة تستلزم امتلاك الغيب أو التصرف المستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص293، تحت عنوان «علة فصل الآية عما قبلها»","url":""}]},{"id":"s7-1646","number":1646,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة تخصيص المقول بذكر حال الرسول؟","answer":"الرسول عبد لا يملك لنفسه شيئًا إلا بمشيئة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص295، تحت عنوان «دلالة تخصيص المقول بذكر حال الرسول»","url":""}]},{"id":"s7-1384","number":1384,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما سرّ تقديم ﴿نفعًا﴾ على ﴿ضرًا﴾ في هذا الموضع؟","answer":"ناسب ترتيب السياق؛ فقد تقدم ذكر الهداية قبل الضلال، ثم جاء بعده الاستكثار من الخير قبل مس السوء، فجرى النفع والضر على هذا النسق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص296، تحت عنوان «نكتة تقديم النفع على الضر»","url":""}]},{"id":"s7-1385","number":1385,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة الاستثناء ونوعه في قوله إلا ما شاء الله؟","answer":"ي مباشرة الأسباب فواقعة بما أقدر الله عليه وتحت مشيئته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص301، تحت عنوان «دلالة الاستثناء ونوعه في قوله إلا ما شاء الله»","url":""}]},{"id":"s7-1647","number":1647,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما سر ذكر ملك النفع والضر؟","answer":"المنفي هو الملك المستقل والقدرة الذاتية النافذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص295، تحت عنوان «سر ذكر ملك النفع والضر»","url":""}]},{"id":"s7-1386","number":1386,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة الاستثناء في ﴿إلا ما شاء الله﴾؟","answer":"يثبت أن ما يحصل للنبي من نفع أو دفع ضر إنما يكون بما شاءه الله وأقدره عليه، لا بملك مستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص300–301، تحت «دلالة الاستثناء ونوعه في قوله إلا ما شاء الله»","url":""}]},{"id":"s7-1387","number":1387,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة الشرط في ﴿ولو كنت أعلم الغيب لاستكثرت من الخير﴾؟","answer":"أقام برهانًا عمليًا على انتفاء علم الغيب المستقل: لو علم المستقبل لطلب وجوه الخير كلها قبل فواتها وتجنب السوء قبل وقوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص301–302، تحت «فائدة التعبير بالجملة الشرطية ودلالتها»","url":""}]},{"id":"s7-1388","number":1388,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة ﴿استكثرت﴾ بدل «أخذت كثيرًا»؟","answer":"صيغة الاستفعال تدل على طلب الزيادة وتحصيل أكبر قدر ممكن من الخير، وهو الأليق بفرض العلم بالغيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص291–292، تحت «شرح المفردات: لاستكثرت»","url":""}]},{"id":"s7-1389","number":1389,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة تعريف ﴿الخير﴾؟","answer":"يفيد جنس الخير واستيعاب وجوهه التي يمكن تحصيلها لو عُلم الغيب، لا خيرًا واحدًا محدودًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص303، تحت «معنى أل في الخير ودلالتها»","url":""}]},{"id":"s7-1390","number":1390,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما سرّ التعبير بـ﴿وما مسني السوء﴾ بدل «ولدفعت الضر»؟","answer":"جعل عدم إصابة السوء نتيجة لازمة لعلم الغيب المفترض، وصوّر السلامة تامة حتى إن السوء لا يقع منه أدنى مس.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص304–305، تحت «سر اصطفاء مس السوء بدل دفع المضار»","url":""}]},{"id":"s7-1391","number":1391,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة اختيار ﴿مسني﴾؟","answer":"المس أخف درجات الإصابة، فنفيه أبلغ في نفي كل ما فوقه من حلول السوء والضرر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص309، تحت عنوان «المس والإصابة»","url":""}]},{"id":"s7-1392","number":1392,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة القصر في ﴿إن أنا إلا نذير وبشير﴾؟","answer":"يقصر وظيفته في هذا المقام على تبليغ الإنذار والبشارة، وينفي ما توهموه من علم الغيب أو التصرف المستقل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص305–306، تحت «بلاغة أسلوب القصر بالاستثناء بعد النفي ونوعه»","url":""}]},{"id":"s7-1393","number":1393,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]},{"surah":11,"verses":[2]}],"verseLabel":"الأعراف: 188؛ هود: 2","question":"ما سر تقديم وصف الإنذار على البشارة في قوله: ﴿إن أنا إلا نذير وبشير﴾؟","answer":"لأن المقام خطاب للمكذبين، فالإنذار أعلق بحالهم وأسبق في إيقاظهم من عاقبة التكذيب، ثم جاءت البشارة للمؤمن الذي يثبت على إيمانه؛ كما أن سياق السورة يغلب عليه الإنذار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص307، تحت «فائدة تقديم الإنذار على البشارة»","url":""}]},{"id":"s7-1394","number":1394,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة تقييد الإنذار والبشارة بـ﴿لقوم يؤمنون﴾؟","answer":"الرسالة عامة، لكن المؤمنين هم الذين ينتفعون بالإنذار والبشارة ويصدقون بمقتضاهما؛ فالقيد للانتفاع لا لعموم البلاغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص308–309، تحت «دلالة تخصيص المؤمنين بالبشارة والنذارة على غيرهم»","url":""}]},{"id":"s7-1395","number":1395,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]}],"verseLabel":"الأعراف: 188","question":"ما دلالة المضارع في ﴿قوم يؤمنون﴾؟","answer":"يفيد إمكان تجدد حدوث الإيمان، ترغيبًا للكافرين في إحداثه بدل الإصرار على الكفر. ويحتمل أن يراد به الحال والاستقبال معًا، فالوصف يشمل من آمن ومن يؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص308، تحت «فائدة التعبير بالمضارع في وصف القوم»","url":""}]},{"id":"s7-1396","number":1396,"surah":7,"verses":[188],"references":[{"surah":7,"verses":[188]},{"surah":10,"verses":[49]}],"verseLabel":"الأعراف: 188؛ يونس: 49","question":"ما سرّ تقديم النفع على الضر في الأعراف، وتقديم الضر على النفع في يونس؟","answer":"في الأعراف سبق تقديم الهداية على الضلال، ولحق الآية تقديم الخير على السوء، فناسب ﴿نفعًا ولا ضرًا﴾. وفي يونس سبق تكرار ذكر الضر، فجرى قوله ﴿ضرًا ولا نفعًا﴾ على الأصل وعلى نسق سياق السورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص297–298، تحت «توجيه المتشابه اللفظي في تقديم النفع على الضر وتأخيره»","url":""}]},{"id":"s7-1397","number":1397,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما مناسبة افتتاح الآية بقوله تعالى: ﴿هو الذي خلقكم﴾؟","answer":"لما سبق سؤالهم عن الساعة وإنكار بعضهم البعث، ذُكّروا ببدء خلق الإنسان؛ فمن قدر على الإنشاء أولًا قدر على الإعادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص311، تحت «مناسبة الآيتين لما قبلهما»","url":""}]},{"id":"s7-1398","number":1398,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما سرّ التعبير بـ﴿من نفس واحدة﴾؟","answer":"يقرر وحدة الأصل الإنساني؛ فالناس جميعًا متفرعون من آدم، وفي ذلك إظهار لقدرة الله ووحدة الخالق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص315–316، تحت «معنى من في قوله من نفس واحدة»","url":""}]},{"id":"s7-1399","number":1399,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة تنكير ﴿نفس﴾ ووصفها بـ﴿واحدة﴾؟","answer":"التنكير ثم الوصف يبرزان أن هذا الجنس البشري الكثير نشأ من نفس واحدة لا من أصول متفرقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص316–317، تحت «نكتة تنكير النفس ووصفها بالواحدة بطريق الإدماج»","url":""}]},{"id":"s7-1400","number":1400,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما سرّ التعبير بـ﴿وجعل منها زوجها﴾ بدل «وخلق زوجًا آخر»؟","answer":"﴿منها﴾ تبين اتحاد الأصل والجنس، و﴿جعل﴾ يبرز تهيئتها لتكون زوجًا وسكنًا، لا مجرد إيجاد مخلوق آخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص319، تحت عنوان «معنى من ودلالتها في منها»","url":""}]},{"id":"s7-1401","number":1401,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة إضافة الزوج إلى النفس في ﴿زوجها﴾؟","answer":"تفيد شدة الاختصاص والاقتران؛ فهي الزوج الملائم لهذه النفس، ومن جنسها، والمهيأ لسكونها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص319، تحت «نكتة إضافة الزوج إلى النفس في زوجها»","url":""}]},{"id":"s7-1402","number":1402,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما الفرق بين ﴿ليسكن إليها﴾ و«ليسكن معها»؟","answer":"السكون إليها هو الميل والأنس والطمأنينة والركون، أما السكن معها فلا يتجاوز الدلالة على الاجتماع في مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص320–321، تحت «بلاغة الاستعارة في التعبير بالسكن عن الطمأنينة والأنس»","url":""}]},{"id":"s7-1403","number":1403,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما سرّ إسناد السكون إلى الرجل في ﴿ليسكن إليها﴾؟","answer":"عاد الضمير إلى ﴿نفس واحدة﴾ باعتبار المراد بها آدم، وذكر علة جعل الزوج؛ ولا ينفي ذلك سكون كل من الزوجين إلى الآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص321–322، تحت «علة استخدام التذكير في الضمير المستكن في قوله ليسكن»","url":""}]},{"id":"s7-1404","number":1404,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما بلاغة الكناية في قوله تعالى: ﴿فلما تغشاها﴾؟","answer":"كنى عن اتصال الزوج بزوجته بلفظ الغشيان، وهو الستر والتغطية؛ صونًا للعبارة وتصويرًا لشدة القرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص322–323، تحت «بلاغة الكناية بصيغة التفعل في قوله تغشاها»","url":""}]},{"id":"s7-1405","number":1405,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة ﴿لما﴾ في ﴿فلما تغشاها حملت حملًا خفيفًا﴾؟","answer":"هي ظرفية بمعنى حين متضمنة معنى الشرط، فتربط الحمل بالتغشي وتبين ترتيب طور الحمل على اتصال الزوجين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص322، تحت «معنى الفاء ودلالتها في فلما»","url":""}]},{"id":"s7-1406","number":1406,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة الجمع بين الفعل والمصدر في ﴿حملت حملًا﴾؟","answer":"يذكر المصدر وجهين: أن يكون ﴿حملًا﴾ مصدرًا، فيلاحظ فيه تصوير فعل الحمل وما يناسبه من الخفة، أو مفعولًا به بمعنى المحمول من النطفة والجنين قبل أن يكبر ويثقل. فلا يجزم بنفي المصدرية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص323–324، تحت «نكتة التعبير بحملًا بعد حملت»","url":""}]},{"id":"s7-1407","number":1407,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة وصف الحمل أولًا بـ﴿خفيفًا﴾؟","answer":"يصور أول الحمل حين لا تجد المرأة ثقله ولا يشق عليها، تمهيدًا للمقابلة مع قوله: ﴿فلما أثقلت﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص324، تحت «غرض وصف الحمل بالخفة»","url":""}]},{"id":"s7-1408","number":1408,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة المرور في قوله تعالى: ﴿فمرت به﴾؟","answer":"أي استمرت بالحمل في شؤونها، تقوم وتقعد من غير أن يثقلها؛ فالمرور يصور مضي هذا الطور بسهولة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص324–325، تحت «بلاغة الاستعارة في قوله فمرت به»","url":""}]},{"id":"s7-1409","number":1409,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما نكتة الكناية في أثقلت؟","answer":"﴿أثقلت﴾ كناية عن كبر الجنين وثقل الحمل، والهمزة للصيرورة أو الدخول في زمان الفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص326، تحت عنوان «نكتة الكناية في أثقلت»","url":""}]},{"id":"s7-1648","number":1648,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة الهمزة في أثقلت؟","answer":"أي صارت ذات حمل ثقيل أو دخلت طور ثقله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص326، تحت عنوان «دلالة الهمزة في أثقلت»","url":""}]},{"id":"s7-1410","number":1410,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما سرّ الانتقال إلى التثنية في ﴿دعوا الله ربهما﴾؟","answer":"لأن ثقل الحمل وسلامة الولد يعنيان الأبوين معًا، فاشتركا في الخوف والدعاء بعد أن كان وصف الحمل خاصًا بالأم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص327، تحت «دلالة لفظ دعوا وعود الضمير فيها»","url":""}]},{"id":"s7-1411","number":1411,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة الجمع بين اسم الجلالة ووصف الربوبية في ﴿دعوا الله ربهما﴾؟","answer":"يستحضر اسم الله كمال قدرته على ما يسألانه، ويستحضر وصف الربوبية تربيته ورزقه وإحسانه إليهما؛ ففي الجمع إظهار الافتقار إليه في إتمام الحمل وصلاح المولود.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص327–328، تحت «فائدة الجمع بين وصف الألوهية والربوبية في دعوا الله ربهما»","url":""}]},{"id":"s7-1412","number":1412,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة تنكير ﴿صالحًا﴾ في ﴿لئن آتيتنا صالحًا﴾؟","answer":"حُذف الموصوف، أي ولدًا صالحًا، والتنكير يعم وجوه الصلاح: سلامة الخلق والعقل والفطرة والدين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص329–330، تحت «غرض تنكير صالحًا وحذف الموصوف»","url":""}]},{"id":"s7-1413","number":1413,"surah":7,"verses":[189],"references":[{"surah":7,"verses":[189]}],"verseLabel":"الأعراف: 189","question":"ما دلالة توكيد ﴿لنكونن من الشاكرين﴾؟","answer":"لام جواب القسم ونون التوكيد الثقيلة تدلان على شدة الرغبة في إجابة الدعاء وقوة التزامهما بالشكر إن رُزقا الولد الصالح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص330، تحت «دلالة تتابع المؤكدات في ﴿لنكونن﴾»","url":""}]},{"id":"s7-1414","number":1414,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما سرّ إعادة ﴿صالحًا﴾ في قوله تعالى: ﴿فلما آتاهما صالحًا﴾؟","answer":"يثبت تمام إجابة الدعاء بعين المطلوب الذي سألاه؛ فقد آتاهما ولدًا مستوفيًا وصف الصلاح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص331، تحت عنوان «معنى لما ودلالتها في قوله فلما آتاهما»","url":""}]},{"id":"s7-1415","number":1415,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"من المراد بقوله تعالى: ﴿جعلا له شركاء فيما آتاهما﴾؟","answer":"الآية تضرب مثلًا للوالدين من ذرية آدم اللذين يشركان بعد أن يسألا الله الولد؛ فلا يصح نسبة الشرك إلى آدم وحواء، وهو ما يؤيده انتقال السياق إلى جمع ﴿يشركون﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص334، تحت عنوان «غرض تقديم شبه الجملة جعلا له شركاء»","url":""}]},{"id":"s7-1416","number":1416,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما سر تنكير شركاء وجمعها؟","answer":"الجمع يلائم عموم شرك المشركين وتنوعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص334–335، تحت عنوان «سر تنكير شركاء وجمعها»","url":""}]},{"id":"s7-1649","number":1649,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما دلالة توجيه القراءات المتواترة في شركاء ودلالاتها؟","answer":"كإشراكهم غير الله في التسمية أو العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص334–335، تحت عنوان «توجيه القراءات المتواترة في شركاء ودلالاتها»","url":""}]},{"id":"s7-1417","number":1417,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما دلالة قوله تعالى: ﴿فيما آتاهما﴾ بعد سبق ذكر العطاء؟","answer":"يعيد ربط الشرك بالنعمة نفسها؛ فموضع التوبيخ أنهم جعلوا لله شركاء في الولد الذي علموا أنه عطاء منه وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص335–336، تحت «دلالة التعبير بالاسم الموصول ما دون من»","url":""}]},{"id":"s7-1418","number":1418,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما سرّ الانتقال من التثنية إلى الجمع في ﴿عما يشركون﴾؟","answer":"انتقل من مثال الأبوين إلى عموم المشركين الموجودين؛ فالجملة نتيجة تعم أصناف شركهم، وتدل على أن المراد ليس آدم وحواء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص337–338، تحت «دلالة عود ضمير الجمع في يشركون»","url":""}]},{"id":"s7-1419","number":1419,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما دلالة الفاء في ﴿فتعالى الله﴾؟","answer":"تفيد أن تنزيه الله مترتب على ما فُصل من انفراده بالخلق والعطاء، وهي دلائل تبطل الشرك وتوجب التوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص336–337، تحت «معنى الفاء في قوله فتعالى»","url":""}]},{"id":"s7-1420","number":1420,"surah":7,"verses":[190],"references":[{"surah":7,"verses":[190]}],"verseLabel":"الأعراف: 190","question":"ما دلالة اختيار ﴿تعالى﴾ في تنزيه الله عن شركهم؟","answer":"يدل على علو الله وتنزهه وتقدسه عن أن يكون له شريك؛ وهو أبلغ من مجرد إعلان البراءة من فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص337، تحت «دلالة قوله فتعالى»","url":""}]},{"id":"s7-1421","number":1421,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما دلالة الاستفهام في ﴿أيشركون ما لا يخلق شيئًا﴾؟","answer":"استفهام إنكاري للتوبيخ والتعجيب من تسويتهم المخلوق العاجز بالخالق القادر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص344، تحت «بلاغة الاستفهام ودلالته في أيشركون»","url":""}]},{"id":"s7-1422","number":1422,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما سرّ التعبير عن الأصنام بـ﴿ما﴾؟","answer":"استُعملت ﴿ما﴾ لأنها لغير العاقل، وفي ذلك كشف لحقيقة الأصنام الجمادية وإبطال لما رفعها إليه عابدوها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص345، تحت «معنى ما في ما لا يخلق»","url":""}]},{"id":"s7-1423","number":1423,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما دلالة ﴿شيئًا﴾ في ﴿لا يخلق شيئًا﴾؟","answer":"جاءت نكرة في سياق النفي فعمّت؛ أي لا تخلق شيئًا مهما صغر، فانتفى عنها أصل القدرة على الخلق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص346–347، تحت «نكتة تنكير شيئًا»","url":""}]},{"id":"s7-1424","number":1424,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما سرّ جمع ضمير الأصنام في ﴿وهم يُخلقون﴾ بعد التعبير عنها بـ﴿ما﴾؟","answer":"روعي في ﴿ما﴾ حقيقتها غير العاقلة، ثم روعي في ضمير الجمع ما نزله المشركون منزلة العقلاء حين عبدوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص348، تحت «دلالة الإشارة إلى الأصنام بضمير العقلاء في وهم يخلقون»","url":""}]},{"id":"s7-1425","number":1425,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما دلالة بناء ﴿يُخلقون﴾ للمجهول؟","answer":"لأن المصنوع لا يكون صانعًا؛ فالمقام لإبراز كونها مخلوقة عاجزة، مع الاستغناء عن ذكر الفاعل لتعينه والعلم به. فالاهتمام منصب على وصفها الذي يبطل عبادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص347، تحت «نكتة بناء يخلقون لما لم يسم فاعله»","url":""}]},{"id":"s7-1426","number":1426,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما معنى الواو ودلالتها في وهم يخلقون؟","answer":"تقيم مقابلة قاطعة بين العجز عن خلق أي شيء والافتقار إلى من يخلقهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص347، تحت عنوان «معنى الواو ودلالتها في وهم يخلقون»","url":""}]},{"id":"s7-1650","number":1650,"surah":7,"verses":[191],"references":[{"surah":7,"verses":[191]}],"verseLabel":"الأعراف: 191","question":"ما وجه البلاغة في البديع من خلال المقابلات في الآيات؟","answer":"من كان مخلوقًا عاجزًا لا يستحق العبادة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص360، تحت عنوان «بلاغة البديع من خلال المقابلات في الآيات»","url":""}]},{"id":"s7-1427","number":1427,"surah":7,"verses":[192],"references":[{"surah":7,"verses":[192]}],"verseLabel":"الأعراف: 192","question":"ما الفرق بين ﴿ولا يستطيعون لهم نصرًا﴾ و«ولا ينصرونهم»؟","answer":"نفي الاستطاعة ينفي أصل القدرة على النصر قبل وقوعه، فهو أبلغ من نفي فعل النصر وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص352، تحت «فائدة المجاز المرسل في التعبير عن العجز والاحتياج بنفي الاستطاعة»","url":""}]},{"id":"s7-1428","number":1428,"surah":7,"verses":[192],"references":[{"surah":7,"verses":[192]}],"verseLabel":"الأعراف: 192","question":"ما دلالة تقديم ﴿لهم﴾ على ﴿نصرًا﴾؟","answer":"يقدم العابدين موضع العناية؛ فالأصنام لا تملك لهم خصوصًا أدنى نصر، مع أنهم اتخذوها طلبًا لذلك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص350، تحت «غرض تقديم شبه الجملة لهم»","url":""}]},{"id":"s7-1429","number":1429,"surah":7,"verses":[192],"references":[{"surah":7,"verses":[192]}],"verseLabel":"الأعراف: 192","question":"ما دلالة تنكير ﴿نصرًا﴾؟","answer":"التنكير في سياق النفي يعم كل نوع وكل قدر من النصر؛ فلا يستطيعون نصرًا قليلًا ولا كثيرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص350–351، تحت «نكتة تنكير نصرًا»","url":""}]},{"id":"s7-1430","number":1430,"surah":7,"verses":[192],"references":[{"surah":7,"verses":[192]}],"verseLabel":"الأعراف: 192","question":"ما دلالة الانتقال إلى ﴿ولا أنفسهم ينصرون﴾؟","answer":"ترقٍ في بيان العجز: من لا يستطيع حماية نفسه من الكسر والإهانة أعجز عن حماية عابديه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص351، تحت «دلالة الواو في ولا أنفسهم ينصرون»","url":""}]},{"id":"s7-1431","number":1431,"surah":7,"verses":[192,197],"references":[{"surah":7,"verses":[192,197]}],"verseLabel":"الأعراف: 192؛ الأعراف: 197","question":"ما دلالة تقديم ﴿أنفسهم﴾ في ﴿ولا أنفسهم ينصرون﴾؟","answer":"في الأعراف: 192: للتخصيص والعناية بأشد مواضع العجز: لا يملكون النصر حتى لأنفسهم، فضلًا عن غيرهم.\n\nفي الأعراف: 197: يبرز موضع العجز الأشد: لا يقدرون على دفع الأذى عن ذواتهم التي هي أولى بالنصر، فغيرهم أعجز.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص351–352، تحت عنوان «نكتة تقديم المفعول به على الفعل»","url":""}]},{"id":"s7-1432","number":1432,"surah":7,"verses":[193],"references":[{"surah":7,"verses":[193]}],"verseLabel":"الأعراف: 193","question":"ما دلالة الشرط في ﴿وإن تدعوهم إلى الهدى لا يتبعوكم﴾؟","answer":"يقرر عجز الأصنام في كل حال؛ فحتى لو دعاها عابدوها إلى طريق تهتدي إليه لم تسمع ولم تتبع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص354، تحت «نكتة التعبير بالجملة الشرطية مع أن دعوتهم محققة»","url":""}]},{"id":"s7-1433","number":1433,"surah":7,"verses":[193],"references":[{"surah":7,"verses":[193]}],"verseLabel":"الأعراف: 193","question":"ما دلالة الاستعارة في يتبعوكم؟","answer":"شبهت الطاعة بالاتباع الذي يتضمن الملازمة وعدم المفارقة، فنفي الاتباع نفي لاستجابتها وطاعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص355–356، تحت عنوان «بلاغة الاستعارة في يتبعوكم»","url":""}]},{"id":"s7-1651","number":1651,"surah":7,"verses":[193],"references":[{"surah":7,"verses":[193]}],"verseLabel":"الأعراف: 193","question":"ما وجه البلاغة في توجيه القراءات المتواترة في يتبعوكم؟","answer":"يذكر المصدر في القراءة المخففة معنى اقتفاء الأثر، وفي المشددة معنى اتباع الهدى المدعوة إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص355–356، تحت عنوان «بلاغة توجيه القراءات المتواترة في يتبعوكم»","url":""}]},{"id":"s7-1434","number":1434,"surah":7,"verses":[193],"references":[{"surah":7,"verses":[193]}],"verseLabel":"الأعراف: 193","question":"ما دلالة ﴿سواء عليكم أدعوتموهم أم أنتم صامتون﴾؟","answer":"يستوي دعاؤهم الأصنام وسكوتهم عنها؛ لأنها لا تسمع ولا تستجيب في الحالين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص356–357، تحت عنوان «الموقع البياني لجملة سواء عليكم»","url":""}]},{"id":"s7-1435","number":1435,"surah":7,"verses":[193],"references":[{"surah":7,"verses":[193]}],"verseLabel":"الأعراف: 193","question":"ما سرّ مجيء الطرف الأول فعلًا ﴿أدعوتموهم﴾ والثاني اسمًا ﴿أنتم صامتون﴾؟","answer":"الدعاء فعل متجدد قد يقع وقد يترك، أما الصمت فصُور حالة ثابتة؛ ومع اختلاف الصورتين فالنتيجة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص357، تحت عنوان «بلاغة العدول من الفعلية إلى الاسمية»","url":""}]},{"id":"s7-1436","number":1436,"surah":7,"verses":[193],"references":[{"surah":7,"verses":[193]}],"verseLabel":"الأعراف: 193","question":"ما الفرق بين الصمت والسكوت، وما ملاءمة ﴿أم أنتم صامتون﴾؟","answer":"السكوت ترك الكلام مع القدرة عليه، أما الصمت فيطلق على الإمساك عن النطق مطلقًا وقد يكون مع عدم القدرة. فالصمت أعم، وتساوي الدعاء والصمت هنا يؤكد أن الأصنام لا تستجيب في أي حال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص360، تحت «الصمت والسكوت»","url":""}]},{"id":"s7-1437","number":1437,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما دلالة تسمية ما يُدعى من دون الله ﴿عبادًا أمثالكم﴾؟","answer":"كل ما سوى الله مملوك مربوب خاضع له، فسماهم عبادًا لإسقاط دعوى ألوهيتهم، سواء كانوا أصنامًا أو من عُبد من العقلاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص367، تحت عنوان «نكتة النكرة بقوله عباد أمثالكم»","url":""}]},{"id":"s7-1438","number":1438,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما المقصود بقوله تعالى: ﴿أمثالكم﴾؟","answer":"المماثلة في العبودية لله والافتقار إليه، لا في جميع الصفات؛ بل أنتم أكمل من الأصنام بما أوتيتم من حياة وإدراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص366–367، تحت «نكتة النكرة بقوله عباد أمثالكم»","url":""}]},{"id":"s7-1439","number":1439,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما دلالة الأمر في فادعوهم؟","answer":"الأول يتحدى العابدين أن يدعوا معبوداتهم، والثاني يعجز المعبودات عن الاستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص368، تحت عنوان «دلالة الأمر في فادعوهم»","url":""}]},{"id":"s7-1652","number":1652,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما دلالة الأمر في فليستجيبوا؟","answer":"الدعاء منهم ممكن، وإنما يظهر عجزها عن تحقيق مطلوبهم واستحالة استجابتها على النحو الذي يزعمونه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص370، تحت عنوان «دلالة الأمر في فليستجيبوا»","url":""}]},{"id":"s7-1440","number":1440,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما دلالة لام الأمر في ﴿فليستجيبوا﴾؟","answer":"هي للأمر التعجيزي التهكمي؛ إذ طُلب منها ما لا قدرة لها عليه ليظهر بطلان عبادتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص369–370، تحت «معنى اللام في فليستجيبوا»","url":""}]},{"id":"s7-1441","number":1441,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما دلالة توجيه الأمر بصيغة الغائب في ﴿فليستجيبوا لكم﴾؟","answer":"أمر الغائب يدل على توجيه الطلب بواسطة مبلّغ، وفيه هنا تهكم بالأصنام وعابديها؛ فهي عاجزة عن الإجابة، بل عن تلقي الأمر وفهمه أيضًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص369، تحت «دلالة الأمر في فليستجيبوا»","url":""}]},{"id":"s7-1442","number":1442,"surah":7,"verses":[194],"references":[{"surah":7,"verses":[194]}],"verseLabel":"الأعراف: 194","question":"ما دلالة الشرط في ﴿إن كنتم صادقين﴾؟","answer":"يعلق صدق دعواهم ألوهية المعبودات على استجابتها، وهي عاجزة عنها؛ فيثبت كذب الدعوى بطريق التحدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص370، تحت «معنى إن ودلالة التعبير بالشرطية والغرض منها»","url":""}]},{"id":"s7-1443","number":1443,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما مناسبة تفصيل الجوارح بعد التحدي العام؟","answer":"فصّل وجوه عجز الأصنام في الحركة والعمل والإبصار والسماع؛ لتقوم الحجة المحسوسة على أنها دون عابديها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص373، تحت عنوان «نكتة فصل الآية عن سابقتها»","url":""}]},{"id":"s7-1444","number":1444,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة تكرار الاستفهام في تعداد الجوارح؟","answer":"يجعل كل جارحة موضع إنكار مستقل، ويقرر العجز وجهًا بعد وجه حتى لا يبقى لمعبوداتهم وصف كمال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص374–375، تحت «فائدة توجيه الإنكار إلى كل واحدة من هذه الجوارح الأربعة»","url":""}]},{"id":"s7-1445","number":1445,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة ﴿أم﴾ بين أسئلة الجوارح؟","answer":"يذكر المصدر احتمال كونها منقطعة بمعنى بل والهمزة، فيتجدد الإنكار مع كل جارحة. ويحتمل اتصالها بعد همزة الاستفهام؛ فلا يصح حصرها في وجه الانقطاع وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص375، تحت «معنى أم في المواضع الثلاثة»","url":""}]},{"id":"s7-1446","number":1446,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما سرّ تقديم الأرجل على الأيدي؟","answer":"بدأ بآلة الانتقال التي توصل إلى المقصود، ثم آلة البطش والعمل به؛ فجرى الترتيب على تسلسل الحركة والفعل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص376–377، تحت «بلاغة ترتيب الجوارح الأربعة»","url":""}]},{"id":"s7-1447","number":1447,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة قوله تعالى: ﴿أرجل يمشون بها﴾ مع أن للأصنام صور أرجل؟","answer":"العبرة بوظيفة الجارحة لا بصورتها؛ فلها أرجل مصورة لا تمشي بها، فظهرت مفارقة الاسم للحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص374–375، تحت عنوان «نكتة تنكير الأرجل والأيدي والأعين والآذان»","url":""}]},{"id":"s7-1448","number":1448,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة اختيار ﴿يبطشون﴾ للأيدي؟","answer":"البطش هو الأخذ والعمل بقوة، وهو أنسب بمقام التحدي والتهديد من مطلق العمل؛ فإذا عجزت عنه بطلت رهبتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص371، تحت عنوان «شرح المفردات: يبطشون»","url":""}]},{"id":"s7-1449","number":1449,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما سرّ تأخير الأعين والآذان عن الأرجل والأيدي؟","answer":"رتبت الجوارح بحسب غرض النصرة والنجدة: الأرجل للسعي، ثم الأيدي للبطش، ثم الأعين والآذان بوصفهما وسيلتين لذلك. فالتأخير يوافق دور الإدراك في تحصيل الفعل المطلوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص376–377، تحت «بلاغة ترتيب الجوارح الأربعة»","url":""}]},{"id":"s7-1450","number":1450,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما مناسبة تقديم الأعين على الآذان في هذا الموضع؟","answer":"جاء الترتيب بطريق الترقي في أسباب الضرر المخوف: المشي، ثم البطش، ثم البصر الذي قد يترتب عليه الضرر من بعيد، ثم السمع الذي يدرك به ما لم يصل إليه البصر. فهذا من وجوه الترتيب التي يذكرها المصدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص376–377، تحت «بلاغة ترتيب الجوارح الأربعة»","url":""}]},{"id":"s7-1451","number":1451,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما سرّ استعمال ضمائر العقلاء في ﴿يمشون... يبطشون... يبصرون... يسمعون﴾؟","answer":"جرى الخطاب على زعم المشركين الذين نزّلوا الأصنام منزلة العقلاء، وفي ذلك تهكم؛ لأنها لا تؤدي شيئًا من أفعالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص376، تحت «سر وصف معبوداتهم بأوصاف العقلاء»","url":""}]},{"id":"s7-1452","number":1452,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما فائدة وصف الجوارح بأفعالها في ﴿يمشون بها﴾ و﴿يبطشون بها﴾ و﴿يبصرون بها﴾ و﴿يسمعون بها﴾؟","answer":"يسجل الوصف عجز الأصنام عما يحتاج إليه عابدوها؛ فصور الأرجل والأيدي والأعين والآذان لا تنفع ما دامت وظائفها منتفية. فالحجة تتعلق بالعمل الذي يراد من الجارحة، لا بمجرد شكلها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص375، تحت «دلالات وصف الجوارح الأربعة»","url":""}]},{"id":"s7-1453","number":1453,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة الأمر في ﴿قل ادعوا شركاءكم﴾ بعد ثبوت عجزهم؟","answer":"أمر تعجيزي يبالغ في إظهار الثقة بالله: استنصروا بكل من تزعمونهم شركاء وحاولوا الكيد مجتمعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص377–378، تحت «دلالة توالي الأمرين في قل ادعوا»","url":""}]},{"id":"s7-1454","number":1454,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة إضافة الشركاء إليهم في ﴿شركاءكم﴾؟","answer":"نسبتهم إليهم تكشف أنهم شركاء في زعم المشركين وحدهم، لا شركاء لله في الحقيقة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص378–379، تحت «نكتة إضافة الشركاء إلى ضميرهم»","url":""}]},{"id":"s7-1455","number":1455,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة ﴿ثم﴾ في ﴿ثم كيدون﴾؟","answer":"تفيد التراخي الرتبي: بعد دعوة الشركاء والاستمداد بهم انتقلوا إلى ما هو أشد في زعمهم، وهو اجتماعهم على الكيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص379، تحت «دلالة العطف بثم»","url":""}]},{"id":"s7-1456","number":1456,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما سرّ حذف ياء المتكلم في ﴿كيدون﴾؟","answer":"حذف الياء في قراءة من يحذفها يوافق تشابه الفواصل، مع دلالة الكسرة عليها. ويذكر المصدر قراءة إثبات الياء أيضًا؛ فالحذف وجه قراءة، وليس الوجه الوحيد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص379–380، تحت «التوجيه البلاغي للقراءات المتواترة في كيدون وتنظرون»","url":""}]},{"id":"s7-1457","number":1457,"surah":7,"verses":[195],"references":[{"surah":7,"verses":[195]}],"verseLabel":"الأعراف: 195","question":"ما دلالة قوله تعالى: ﴿فلا تنظرون﴾؟","answer":"أي لا تمهلوني لحظة، وهو غاية في التحدي وعدم المبالاة بهم وبشركائهم؛ لليقين بعجزهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص379، تحت «دلالة النهي في فلا تنظرون»","url":""}]},{"id":"s7-1458","number":1458,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما مناسبة تعليل التحدي بقوله تعالى: ﴿إن وليي الله﴾؟","answer":"لا يبالي بكيدهم لأن ناصره وحافظه هو الله؛ فمن كان في ولايته لم يضره تألب المعبودات العاجزة وعابديها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص383، تحت «علة فصل قوله إن وليي الله»","url":""}]},{"id":"s7-1459","number":1459,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما دلالة قوله تعالى: ﴿إن وليي الله﴾ بإضافة الولي وإظهار اسم الجلالة؟","answer":"إضافة ﴿ولي﴾ إلى ياء المتكلم تشرف النبي بخصوص الولاية، وإظهار اسم الله يصرح بمنفرد الولاية والنصر ويزيد الثقة به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص386، تحت عنوان «بلاغة قصر الولاية الحقيقي على الله»","url":""}]},{"id":"s7-1460","number":1460,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما مناسبة وصف الله بـ﴿الولي﴾ بعد تحدي الشركاء؟","answer":"قابل أولياءهم المزعومين العاجزين بالولي الحق الذي يتولى الحفظ والنصر والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص391، تحت عنوان «الولي والنصير»","url":""}]},{"id":"s7-1461","number":1461,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما مناسبة وصف الله بقوله: ﴿الذي نزل الكتاب﴾ في مقام الحماية؟","answer":"من أنزل على رسوله الكتاب واصطفاه لتبليغه لا يتركه لكيد أعدائه، والكتاب نفسه ناطق بولايته ونصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص389، تحت عنوان «إيثار اسم الكتاب على القرآن»","url":""}]},{"id":"s7-1462","number":1462,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما دلالة التشديد في ﴿نزّل الكتاب﴾؟","answer":"من وجوه الصيغة الدلالة على التكثير والتدرج في التنزيل بما يواكب الأحوال، وفيه توكيد وبناء للعناية على امتداد الزمن. ويذكر المصدر أيضًا احتمال التقوية والتعظيم؛ فلا يحصر التشديد في التنجيم وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص387–388، تحت «دلالة صيغة فعل في قوله نزل الكتاب»","url":""}]},{"id":"s7-1463","number":1463,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما دلالة تعريف ﴿الكتاب﴾؟","answer":"للعهد؛ أي القرآن المعروف المنزل على النبي، وفي التعريف تعظيم له بوصفه الكتاب الكامل الحاضر في مقام الاحتجاج.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص388، تحت «دلالة أل في لفظ الكتاب»","url":""}]},{"id":"s7-1464","number":1464,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما سرّ الانتقال من ﴿وليي﴾ إلى ﴿وهو يتولى الصالحين﴾؟","answer":"عمم بعد الخصوص؛ فولاية الله ليست للنبي وحده، بل سنته أن ينصر عباده الصالحين ويحفظهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص390، تحت «بلاغة التذييل في الآية»","url":""}]},{"id":"s7-1465","number":1465,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما دلالة المضارع في ﴿يتولى الصالحين﴾؟","answer":"يدل على تجدد ولايته واستمرارها؛ فهو يعين الصالحين وينصرهم في شؤونهم كلما تجددت حاجتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص389–390، تحت «نكتة مجيء المسند جملة فعلية فعلها مضارع»","url":""}]},{"id":"s7-1466","number":1466,"surah":7,"verses":[196],"references":[{"surah":7,"verses":[196]}],"verseLabel":"الأعراف: 196","question":"ما دلالة وصف أولياء الله بـ﴿الصالحين﴾؟","answer":"الصلاح سلامة الباطن بالإخلاص وظهور أثره في العمل النافع؛ وهو الوصف الذي يؤهل صاحبه للولاية والنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص382، تحت عنوان «شرح المفردات: الصالحين»","url":""}]},{"id":"s7-1467","number":1467,"surah":7,"verses":[197],"references":[{"surah":7,"verses":[197]}],"verseLabel":"الأعراف: 197","question":"ما فائدة إعادة عجز المعبودات عن النصر بعد ذكره في الآية 192؟","answer":"أعيد بعد تقرير ولاية الله لتكتمل المقابلة: الله يتولى الصالحين، أما ما يدعونه فلا ينصر عابديه ولا نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص395، تحت عنوان «دلالة الواو في قوله والذين تدعون»","url":""}]},{"id":"s7-1468","number":1468,"surah":7,"verses":[197],"references":[{"surah":7,"verses":[197]}],"verseLabel":"الأعراف: 197","question":"ما سرّ التعبير هنا بـ﴿من دونه﴾ وقبلها بـ﴿من دون الله﴾؟","answer":"يرجع الضمير إلى اسم الله المتقدم في تقرير ولايته ونصره للصالحين؛ فتأتي الإحالة إليه لتقابل نصرته بعجز ما يدعونه من دونه، وتنهي دعوى الولاية لتلك المعبودات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص397–398، تحت «فائدة إضافة كلمة دون إلى ضمير اسم الجلالة»","url":""}]},{"id":"s7-1469","number":1469,"surah":7,"verses":[197],"references":[{"surah":7,"verses":[197]}],"verseLabel":"الأعراف: 197","question":"ما نكتة استعمال اسم الموصول الذين؟","answer":"يستحضر الموصول مع صلته المعبودات التي يدعونها ويجعلها موضوعًا للحكم بعجزها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص395–396، تحت عنوان «نكتة استعمال اسم الموصول الذين»","url":""}]},{"id":"s7-1653","number":1653,"surah":7,"verses":[197],"references":[{"surah":7,"verses":[197]}],"verseLabel":"الأعراف: 197","question":"ما دلالة الاسم الموصول؟","answer":"ي اختيار ﴿الذين﴾ مجاراة لاعتقاد المشركين في أصنامهم وإنزالها منزلة العقلاء، تمهيدًا لإظهار بطلان اعتقادهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص395–396، تحت عنوان «دلالة الاسم الموصول»","url":""}]},{"id":"s7-1470","number":1470,"surah":7,"verses":[197],"references":[{"surah":7,"verses":[197]}],"verseLabel":"الأعراف: 197","question":"ما الفرق بين ﴿لا يستطيعون نصركم﴾ و﴿لا يستطيعون لهم نصرًا﴾ في الآية 192؟","answer":"الأولى واجهت العابدين مباشرة بعد تحديهم فناسب ﴿نصركم﴾، أما السابقة فكانت في حكاية حالهم بضمير الغيبة ونكّرت النصر لاستغراق أنواعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص399، تحت عنوان «نكتة إضافة نصر إلى ضمير المخاطبين»","url":""}]},{"id":"s7-1471","number":1471,"surah":7,"verses":[197],"references":[{"surah":7,"verses":[197]}],"verseLabel":"الأعراف: 197","question":"ما سرّ تقديم عجزهم عن نصر العابدين على عجزهم عن نصر أنفسهم؟","answer":"بدأ بإبطال الغرض الذي عبدوهم لأجله، وهو طلب نصرهم، ثم ذكر الدليل الأقوى عليه: عجزهم عن نصر أنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص399، تحت «دلالة عطف جملة ولا أنفسهم ينصرون على ما قبلها»","url":""}]},{"id":"s7-1473","number":1473,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما فائدة إعادة ﴿وإن تدعوهم إلى الهدى﴾ بعد الآية 193؟","answer":"في الموضع الأول بيان لعجزها عن النصرة والإرشاد يبطل عبادتها، وفي هذا الموضع بيان لعجزها حتى عن السماع، يبطل تخويف النبي بها بعد تحديه لهم؛ فتختلف جهة الحجة مع تقارب العبارة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص407، تحت «سر المخالفة بين قوله لا يسمعوا وقوله قبل لا يتبعوكم»","url":""}]},{"id":"s7-1474","number":1474,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما سر المخالفة بين قوله لا يسمعوا وقوله قبل لا يتبعوكم؟","answer":"نفي السماع يثبت فقد أداة تلقي الدعوة، ونفي الاتباع يثبت فقد الاستجابة لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص406–407، تحت عنوان «سر المخالفة بين قوله لا يسمعوا وقوله قبل لا يتبعوكم»","url":""}]},{"id":"s7-1654","number":1654,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما سر العدول عن عبارة لا يهتدوا؟","answer":"الثاني نتيجة ممتنعة لأن الأول غير موجود أصلًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص406–407، تحت عنوان «سر العدول عن عبارة لا يهتدوا»","url":""}]},{"id":"s7-1475","number":1475,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما الصورة في قوله تعالى: ﴿وتراهم ينظرون إليك وهم لا يبصرون﴾؟","answer":"تبدو الأصنام بعيونها المصورة كأنها تنظر إلى الناظر، ثم تكشف الحال أنها لا تبصر شيئًا؛ فالمشهد يهدم خداع الصورة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص411، تحت عنوان «دلالة الواو في قوله وهم لا يبصرون وأثرها في المعنى»","url":""}]},{"id":"s7-1476","number":1476,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما وجه إسناد النظر إلى الأصنام؟","answer":"أُسند إليها بحسب هيئة أعينها المقابلة للناظر، لا على الحقيقة؛ ولذلك أتبع بنفي الإبصار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص408، تحت عنوان «دلالة التشبيه البليغ في الآية»","url":""}]},{"id":"s7-1477","number":1477,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما دلالة تعدية النظر بـ﴿إلى﴾؟","answer":"تفيد توجيه العين نحو المرئي، وهو القدر الظاهري الذي توهمه هيئة الأصنام، من غير تحقق الرؤية والإدراك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص410–411، تحت «فائدة الجار والمجرور إليك ودلالته الإعرابية»","url":""}]},{"id":"s7-1478","number":1478,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما سرّ نفي الإبصار بعد إثبات النظر؟","answer":"النظر توجيه العين وقد يوجد بلا رؤية، أما الإبصار فهو حصول الإدراك؛ فأثبت هيئة النظر ونفى غايته وحقيقته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص412، تحت عنوان «النظر والبصر»","url":""}]},{"id":"s7-1479","number":1479,"surah":7,"verses":[198],"references":[{"surah":7,"verses":[198]}],"verseLabel":"الأعراف: 198","question":"ما دلالة مجيء ﴿وهم لا يبصرون﴾ جملة حالية؟","answer":"تكشف حالهم في اللحظة التي يوهم ظاهرها النظر: تراهم متجهين إليك، والحقيقة المقارنة لذلك أنهم لا يبصرون.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص411، تحت «دلالة الواو في قوله وهم لا يبصرون وأثرها في المعنى»","url":""}]},{"id":"s7-1480","number":1480,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما مناسبة افتتاح الوصايا الجامعة بـ﴿خذ العفو﴾؟","answer":"بدأ بإصلاح معاملة الداعي للناس: يقبل ما سهل من أخلاقهم ولا يستقصي حقوقه، فيتهيأ بعد ذلك للأمر بالخير واحتمال الجاهلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص418–419، تحت «الترقي في المعاني وبيان بعضها بعضًا من خلال الآية»","url":""}]},{"id":"s7-1481","number":1481,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما المراد بـ﴿العفو﴾ في قوله تعالى: ﴿خذ العفو﴾؟","answer":"هو ما سهل وتيسر من أخلاق الناس وأعمالهم من غير استقصاء، ويتضمن المسامحة وترك المؤاخذة؛ وهذه المعاني متقاربة وليست متعارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص415، تحت عنوان «شرح المفردات: العفو»","url":""}]},{"id":"s7-1482","number":1482,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما دلالة إيثار الفعل خذ على ما يرادفه؟","answer":"استعير الأخذ للقبول والرضا بما سهل من أخلاق الناس وأعمالهم، من غير تكليفهم ما يشق عليهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص419، تحت عنوان «إيثار الفعل خذ على ما يرادفه»","url":""}]},{"id":"s7-1655","number":1655,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما دلالة جمال الاستعارة المكنية في قوله خذ العفو؟","answer":"ي التعبير تصوير للعفو كأنه شيء محسوس يؤخذ ويجعل حظًا من معاملة الناس.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص421، تحت عنوان «جمال الاستعارة المكنية في قوله خذ العفو»","url":""}]},{"id":"s7-1483","number":1483,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما دلالة التعبير بـ﴿العرف﴾ بدل «المعروف»؟","answer":"يذكر المصدر أن ﴿العرف﴾ أخف لفظًا وأنسب بمقام الدعوة قبل الهجرة، حين كان المؤمنون في ضعف؛ ويشمل ما تتقبله النفوس من الخير ولا ترده الشريعة. أما «المعروف» فكثيرًا ما يرد مقترنًا بالنهي عن المنكر في مقام بيان التشريع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص424–425، تحت «إيثار لفظ العرف دون المعروف»","url":""}]},{"id":"s7-1484","number":1484,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما دلالة تعريف ﴿العرف﴾؟","answer":"يستغرق جنس الخير المعروف الموافق للشرع والفطرة السليمة، لا خصلة واحدة بعينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص425، تحت «دلالة أل في لفظ العرف»","url":""}]},{"id":"s7-1485","number":1485,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما سرّ ترتيب العفو ثم الأمر بالعرف ثم الإعراض عن الجاهلين؟","answer":"بدأ بتهذيب معاملة النفس، ثم انتقل إلى إصلاح الناس بالأمر بالخير، ثم بيّن ما يحفظ الداعي من سفه من لا يستجيب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص418–419، تحت «الترقي في المعاني وبيان بعضها بعضًا من خلال الآية»","url":""}]},{"id":"s7-1486","number":1486,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما دلالة الأمر بـ﴿وأعرض عن الجاهلين﴾ بدل مقابلتهم بالعقوبة؟","answer":"المطلوب ترك مجاراتهم في السفه وعدم الاشتغال بانتقام النفس، لا ترك بيان الحق ولا تعطيل العقوبة المشروعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص426، تحت «إيثار الفعل وأعرض دون غيره»","url":""}]},{"id":"s7-1487","number":1487,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما دلالة وصف المؤذين بـ﴿الجاهلين﴾؟","answer":"سماهم بما يكشف منشأ سفههم؛ فالجهل هنا سوء التصرف ومجاوزة الحلم، ووصفهم به يهيئ للإعراض عنهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص416، تحت عنوان «شرح المفردات: الجاهلين»","url":""}]},{"id":"s7-1488","number":1488,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما سر اختيار جمع المذكر السالم ﴿الجاهلين﴾ دون «الجهلاء»؟","answer":"يربط المصدر الاختيار بمناسبة مقام الحلم والعفو والقلة في هذا السياق، وبانسجام اللفظ مع الفاصلة. فليس المقصود الحث على استقصاء مقابلة أهل الجهل أو تكثيرها، بل تجاوز سفههم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص427، تحت «سر العدول عن جمع التكسير إلى جمع المذكر السالم»","url":""}]},{"id":"s7-1489","number":1489,"surah":7,"verses":[199],"references":[{"surah":7,"verses":[199]}],"verseLabel":"الأعراف: 199","question":"ما وجه جمع الآية مكارم الأخلاق في ألفاظ قليلة؟","answer":"جمعت بذل السماحة في ﴿خذ العفو﴾، وإيصال الخير في ﴿وأمر بالعرف﴾، وكف الشر في ﴿وأعرض عن الجاهلين﴾؛ فاستوعبت حسن الخلق فعلًا وتركًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص417–418، تحت عنوان «بلاغة الإيجاز بالقصر»","url":""}]},{"id":"s7-1490","number":1490,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما مناسبة قوله تعالى: ﴿وإما ينزغنك من الشيطان نزغ﴾ بعد الأمر بالإعراض عن الجاهلين؟","answer":"لما كان أذى الجاهلين قد يحرك الغضب ويدعو إلى مقابلتهم، نبه إلى أن هذا النزغ من الشيطان، وبيّن علاجه بالاستعاذة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص431–432، تحت عنوان «دلالة الواو في قوله وإما ينزغنك وأثرها في المعنى»","url":""}]},{"id":"s7-1491","number":1491,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما دلالة دخول ﴿ما﴾ على ﴿إن﴾ في ﴿وإما﴾؟","answer":"﴿ما﴾ زائدة للتوكيد، ودخولها هيأ ﴿إن﴾ الشرطية لاتصال نون التوكيد بالفعل ﴿ينزغنك﴾، فقوّى التنبيه إلى احتمال النزغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص434، تحت عنوان «نكتة تأكيد الفعل بنون التوكيد في قوله وإما ينزغنك»","url":""}]},{"id":"s7-1492","number":1492,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما دلالة النزغ والمس والوسوسة؟","answer":"النزغ أدنى حركة من الشيطان وإثارة إلى الشر، وأكثر ما يكون عند الغضب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص441، تحت عنوان «النزغ والمس والوسوسة»","url":""}]},{"id":"s7-1656","number":1656,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما وجه البلاغة في استعمال النزغ دون المس؟","answer":"هو من درجات الوسوسة التي قد تهيج النفس.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص433، تحت عنوان «بلاغة استعمال النزغ دون المس»","url":""}]},{"id":"s7-1493","number":1493,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما وجه البلاغة في إسناد النزغ إلى المصدر نزغ؟","answer":"المصدر فاعل للفعل، أي إن يصبك من الشيطان نزغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص435–436، تحت عنوان «بلاغة إسناد النزغ إلى المصدر نزغ»","url":""}]},{"id":"s7-1657","number":1657,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما دلالة لطيفة جناس الاشتقاق في قوله ينزغنك ونزغ؟","answer":"ي اشتقاق الفعل والفاعل من مادة واحدة تجنيس يركز معنى الحركة المفسدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص435–436، تحت عنوان «لطيفة جناس الاشتقاق في قوله ينزغنك ونزغ»","url":""}]},{"id":"s7-1494","number":1494,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما دلالة تقديم ﴿من الشيطان﴾ على ﴿نزغ﴾؟","answer":"يبادر بتعيين مصدر النزغ قبل تسميته، تنفيرًا منه وتنبيهًا إلى أن هذه الحركة المفسدة من الشيطان خاصة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص435–436، تحت «فائدة قوله من الشيطان وتقديمه على الفاعل نزغ»","url":""}]},{"id":"s7-1495","number":1495,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما مناسبة جواب الشرط: ﴿فاستعذ بالله﴾؟","answer":"لأن الشيطان عدو خفي لا يدفع نزغه إلا الالتجاء إلى الله القادر عليه؛ فكانت الاستعاذة العلاج المباشر عند وقوع سببه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص436–437، تحت عنوان «فائدة الاستعاذة عند نزغ الشيطان»","url":""}]},{"id":"s7-1496","number":1496,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما سر اختيار ﴿فاستعذ﴾ بدل «فاستعن»؟","answer":"الاستعاذة أصرح في الالتجاء والاحتماء بالله، وفيها إظهار ضعف المستعيذ وافتقاره وانكساره وتعظيم ربه، والتبرؤ من الحول والقوة والالتجاء إلى غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص436–437، تحت «العدول عن فاستعن وإيثار الفعل فاستعذ»","url":""}]},{"id":"s7-1497","number":1497,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما سرّ إظهار اسم الله في ﴿فاستعذ بالله﴾؟","answer":"دفع الإضمار لبس عود الضمير إلى الشيطان، واستحضر اسم الجلالة الجامع لمعاني الكمال والمهابة في مقام الاحتماء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص437–438، تحت «دلالة الباء في قوله بالله وفائدة التصريح باسم الجلالة»","url":""}]},{"id":"s7-1498","number":1498,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما مناسبة ختم الآية بـ﴿إنه سميع عليم﴾؟","answer":"تعليل للأمر بالاستعاذة: الله يسمع التجاء المستعيذ ويعلم نزغ الشيطان وحال من احتمى به، فيكفيه ويحميه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص438، تحت «بلاغة فصل جملة ﴿انه سميع عليم﴾ عما قبلها»","url":""}]},{"id":"s7-1499","number":1499,"surah":7,"verses":[200],"references":[{"surah":7,"verses":[200]}],"verseLabel":"الأعراف: 200","question":"ما سرّ تقديم ﴿سميع﴾ على ﴿عليم﴾؟","answer":"لأن المقام مقام استعاذة ودعاء ملفوظ، فناسب تقديم سماع القول، ثم عمم بالعلم المحيط بالسر والحال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص438–439، تحت عنوان «علاقة الفاصلة بسياق الآية»","url":""}]},{"id":"s7-1500","number":1500,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما مناسبة قوله تعالى: ﴿إن الذين اتقوا﴾ بعد أمر النبي ﷺ بالاستعاذة؟","answer":"عمم العلاج بعد توجيهه إلى النبي؛ فشأن المتقين جميعًا أنهم إذا مسهم الشيطان رجعوا إلى الله، والتقوى وقاية من تمكنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص444–445، تحت «علة أسلوب الفصل في قوله إن الذين اتقوا»","url":""}]},{"id":"s7-1501","number":1501,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة ﴿مسهم﴾ بدل «أصابهم»؟","answer":"المس أخف الإصابة، فيدل على أن وسوسة الشيطان لا تتمكن من المتقين، بل تلامسهم عارضة ثم تزول بالتذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص447–448، تحت عنوان «الاستعارة في الفعل مسهم»","url":""}]},{"id":"s7-1502","number":1502,"surah":7,"verses":[200,201],"references":[{"surah":7,"verses":[200,201]}],"verseLabel":"الأعراف: 200–201","question":"ما الفرق بين ﴿نزغ من الشيطان﴾ و﴿طائف من الشيطان﴾؟","answer":"النزغ حركة مفسدة تهيج إلى الشر، والطائف خاطر أو وسوسة تطوف بالقلب ولا تستقر؛ فالأول يصور الدفع، والثاني سرعة المرور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص449، تحت عنوان «إيثار استعمال لفظ طائف دون غيره»","url":""}]},{"id":"s7-1503","number":1503,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة تنكير ﴿طائف﴾؟","answer":"للتحقير والتقليل؛ فأدنى خاطر من الشيطان ينبه المتقين إلى التذكر، ولا يتمكن منهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص448–449، تحت «إيثار استعمال لفظ طائف دون غيره»","url":""}]},{"id":"s7-1504","number":1504,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة التعبير عن تعرض المتقين للوسوسة بـ﴿مسهم طائف من الشيطان﴾؟","answer":"يصور المس إصابة غير متمكنة؛ فقد يعرض لهم خاطر من الشيطان، لكنهم لا يتركونه يستقر ويتحول إلى عمل. وإسناده إلى الطائف يصور مبادرته وسرعة مروره ومحاولته الإحاطة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص447، تحت عنوان «سر استعمال الفعل مسهم دون غيره»","url":""}]},{"id":"s7-1505","number":1505,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما مناسبة جواب مس الشيطان بقوله تعالى: ﴿تذكروا﴾؟","answer":"لأن الغفلة منفذ الشيطان، فإذا تذكروا أمر الله ونهيه وثوابه وعقابه انكشف الخاطر وانقطع أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص451–452، تحت «إيثار مجيء جواب الشرط تذكروا دون غيره»","url":""}]},{"id":"s7-1506","number":1506,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة حذف مفعول ﴿تذكروا﴾؟","answer":"لإفادة العموم؛ تذكروا ما يردعهم من أمر الله ومراقبته ووعده ووعيده، فلا يحصر التذكر في شيء واحد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص452–453، تحت «بلاغة الإيجاز في حذف المفعول»","url":""}]},{"id":"s7-1507","number":1507,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة الفاء وأثرها في المعنى؟","answer":"تصور سرعة انكشاف وسوسة الشيطان عقب التذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص453، تحت عنوان «دلالة الفاء وأثرها في المعنى»","url":""}]},{"id":"s7-1658","number":1658,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما نكتة استعمال إذا ومعناها؟","answer":"ما إن يتذكروا حتى تعود بصيرتهم فورًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص453، تحت عنوان «نكتة استعمال إذا ومعناها»","url":""}]},{"id":"s7-1508","number":1508,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة ﴿مبصرون﴾ بدل «يعلمون»؟","answer":"يصور الحق بعد التذكر كأنه مشهد واضح تراه البصيرة، لا مجرد معلومة ذهنية؛ فيميزون طريق الرشد من الغي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص454–455، تحت عنوان «دقة استعمال مبصرون دون غيره»","url":""}]},{"id":"s7-1509","number":1509,"surah":7,"verses":[201],"references":[{"surah":7,"verses":[201]}],"verseLabel":"الأعراف: 201","question":"ما دلالة الجملة الاسمية في ﴿هم مبصرون﴾؟","answer":"تفيد تحقق الإبصار وثباته فيهم عقب التذكر، وجاء الضمير لزيادة تقرير حالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص453–454، تحت عنوان «سر التعبير بالجملة الاسمية»","url":""}]},{"id":"s7-1510","number":1510,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما دلالة بيان عائد الضمير المتصل في قوله وإخوانهم؟","answer":"يعرض المصدر أوجهًا أخرى في عود الضمير، فلا ينحصر في هذا الوجه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص464، تحت عنوان «بيان عائد الضمير المتصل في قوله وإخوانهم»","url":""}]},{"id":"s7-1511","number":1511,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما نكتة ذكر لفظ إخوان دون إخوة؟","answer":"الأخوة هنا أخوة الموالاة والموافقة في الغي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص460–461، تحت عنوان «نكتة ذكر لفظ إخوان دون إخوة»","url":""}]},{"id":"s7-1659","number":1659,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما فائدة إضافة إخوان إلى ضمير الغائبين؟","answer":"هي تصور قوة الصلة بين الشياطين ومن يستجيبون لإغوائهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص460–461، تحت عنوان «فائدة إضافة إخوان إلى ضمير الغائبين»","url":""}]},{"id":"s7-1512","number":1512,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما سر إيثار يمدونهم والعدول عن يغوونهم؟","answer":"المد يدل على الإطالة والزيادة والاستمرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص461–462، تحت عنوان «سر إيثار يمدونهم والعدول عن يغوونهم»","url":""}]},{"id":"s7-1660","number":1660,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما دلالة إيثار الفعل يمدونهم دون مرادفاته؟","answer":"الشياطين لا تبدأ الغي فحسب، بل تزيد أولياءها فيه وتمده لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص461–462، تحت عنوان «إيثار الفعل يمدونهم دون مرادفاته»","url":""}]},{"id":"s7-1513","number":1513,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما الصورة في قوله تعالى: ﴿يمدونهم في الغي﴾؟","answer":"صُور الغي مكانًا عميقًا يتغلغلون فيه، والشياطين تطيل لهم حبل الضلال حتى يزدادوا بعدًا ولا يفلتوا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص464–465، تحت «فائدة الجار والمجرور في الغي»","url":""}]},{"id":"s7-1514","number":1514,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما دلالة ﴿ثم﴾ في ﴿ثم لا يقصرون﴾؟","answer":"تفيد التراخي الرتبي؛ فبعد إمدادهم في الغي يبلغ الأمر رتبة أشد، وهي استمرارهم فيه من غير كف ولا فتور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص465، تحت «دلالة الحرف ثم في الآية»","url":""}]},{"id":"s7-1515","number":1515,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"إلى من يعود فاعل ﴿لا يقصرون﴾؟","answer":"يعود في المعنى الأول إلى الشياطين؛ فلا يكفون عن إمداد إخوانهم في الغي، ويحتمل الغاوين أيضًا؛ فلا يكفون عن قبول الإغواء والتمادي فيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص466–467، تحت عنوان «سر استعمال الفعل لا يقصرون دون غيره»","url":""}]},{"id":"s7-1516","number":1516,"surah":7,"verses":[202],"references":[{"surah":7,"verses":[202]}],"verseLabel":"الأعراف: 202","question":"ما دلالة المضارع المنفي في ﴿لا يقصرون﴾؟","answer":"يدل على تجدد عدم الكف واستمراره؛ فالإمداد بالغي والتمادي فيه ديدن متواصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص466، تحت «دلالة استعمال صيغة المضارع»","url":""}]},{"id":"s7-1517","number":1517,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة إيثار لفظ آية في قوله وإذا لم تأتهم بآية؟","answer":"المراد آية يقترحونها أو وحي جديد يوافق أهواءهم، لا انتفاء آيات القرآن الموجودة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص474، تحت عنوان «إيثار لفظ آية في قوله وإذا لم تأتهم بآية»","url":""}]},{"id":"s7-1661","number":1661,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما وجه البلاغة في جملة الشرط وإذا لم تأتهم والمراد منها؟","answer":"قد كانوا يطلبون من الرسول اختراع الآيات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص472، تحت عنوان «بلاغة جملة الشرط وإذا لم تأتهم والمراد منها»","url":""}]},{"id":"s7-1518","number":1518,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة استعمال ﴿إذا﴾ في ﴿وإذا لم تأتهم بآية﴾؟","answer":"لأن عدم مجيء الرسول بكل آية يقترحونها أمر متحقق متكرر، فناسبته ﴿إذا﴾ الدالة على تحقق الوقوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص472، تحت «إيثار التعبير بإذا دون إن»","url":""}]},{"id":"s7-1519","number":1519,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة لولا وأثرها في المعنى؟","answer":"أي هلا اخترعتها أو اخترتها وجمعتها من عند نفسك.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص474–475، تحت عنوان «دلالة لولا وأثرها في المعنى»","url":""}]},{"id":"s7-1662","number":1662,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة إيثار الفعل اجتبيتها ودلالته؟","answer":"هو قول يكشف توهمهم أن الرسول يملك إنشاء الوحي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص474–475، تحت عنوان «إيثار الفعل اجتبيتها ودلالته»","url":""}]},{"id":"s7-1520","number":1520,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة اختيار ﴿اجتبيتها﴾ بدل «أتيت بها»؟","answer":"الاجتباء يتضمن الاختيار والجمع والاصطفاء، فيصور باطل ظنهم أن النبي ينتقي الآية من عنده، لا أنه مجرد يأتي بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص474، تحت عنوان «إيثار الفعل اجتبيتها ودلالته»","url":""}]},{"id":"s7-1521","number":1521,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة القصر في ﴿إنما أتبع ما يوحى إلي﴾؟","answer":"يقصر شأن الرسول على اتباع الوحي، وينفي أن يخترع آية أو يغيرها استجابة لاقتراحهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص476، تحت «بلاغة القصر بـ﴿انما﴾»","url":""}]},{"id":"s7-1522","number":1522,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة المضارع في ﴿أتبع﴾ و﴿يوحى﴾؟","answer":"يدل على تجدد نزول الوحي وتجدد اتباع الرسول له؛ فكلما أوحي إليه شيء بلغه واتّبعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص476، تحت عنوان «سر التعبير بصيغة المضارع أتبع»","url":""}]},{"id":"s7-1523","number":1523,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"كيف يبين السياق مصدر الوحي بعد ﴿يوحى إلي﴾؟","answer":"جاء الفعل مبنيًا للمفعول، ثم صرح ﴿من ربي﴾ بأن الوحي من الله، فدفع توهم أن الرسول ينشئه من عند نفسه، وأكد أنه متلقٍ تابع لما ينزل إليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص477–478، تحت عنوان «فائدة قوله من ربي ومتعلقه»","url":""}]},{"id":"s7-1524","number":1524,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة قوله تعالى: ﴿إلي من ربي﴾؟","answer":"﴿إلي﴾ تثبت أن الرسول متلقٍ لا منشئ، و﴿من ربي﴾ تعين مصدر الوحي وتستحضر التربية والرعاية بالتنزيل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص478، تحت عنوان «فائدة قوله من ربي ومتعلقه»","url":""}]},{"id":"s7-1525","number":1525,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة الإشارة إلى القرآن في ﴿هذا بصائر﴾؟","answer":"تشير إلى القرآن الحاضر المتلو، وتواجه اقتراحهم بآية أخرى بأن بين أيديهم آيات واضحة تكفي من طلب الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص479–480، تحت عنوان «دلالة الإشارة في قوله هذا بصائر»","url":""}]},{"id":"s7-1526","number":1526,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما سرّ جمع ﴿بصائر﴾ مع الإشارة إلى القرآن المفرد؟","answer":"القرآن واحد، لكن آياته ودلائله المتعددة كل واحدة منها بصيرة تكشف وجهًا من الحق؛ فجمع آثار أجزائه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص480–481، تحت «سر جمع لفظ بصائر وإفراد لفظي هدى ورحمة»","url":""}]},{"id":"s7-1527","number":1527,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة تسمية القرآن ﴿بصائر﴾ بدل «أبصارًا»؟","answer":"البصائر نور القلب الذي يدرك به الحق، أما الأبصار فحاسة العين؛ والقرآن يكشف المعاني والهداية للبصائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص480، تحت «إيثار التعبير بلفظ بصائر ودلالته»","url":""}]},{"id":"s7-1528","number":1528,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما سرّ الانتقال من ﴿من ربي﴾ إلى ﴿من ربكم﴾؟","answer":"الأول يبين مصدر ما يتلقاه الرسول، والثاني يواجه المخاطبين بأن القرآن عناية من ربهم هم، أقام بها حجتهم وهدايتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص481، تحت «نكتة تلوين الخطاب في قوله ربكم بعد قوله ربي»","url":""}]},{"id":"s7-1529","number":1529,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة الجمع بين ﴿بصائر وهدى ورحمة﴾؟","answer":"البصائر تكشف الحق، والهدى يقود إلى طريقه، والرحمة ثمرة اتباعه؛ فجمعت الآية البيان والدلالة والجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص481، تحت عنوان «دلالة عطف قوله وهدى ورحمة على قوله بصائر»","url":""}]},{"id":"s7-1530","number":1530,"surah":7,"verses":[203],"references":[{"surah":7,"verses":[203]}],"verseLabel":"الأعراف: 203","question":"ما دلالة تقييد الهدى والرحمة بـ﴿لقوم يؤمنون﴾؟","answer":"القرآن بصائر للناس، لكن المؤمنين هم الذين يقبلون دلالته فيتحقق لهم الهدى والرحمة؛ فالقيد للانتفاع لا لعموم الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص482، تحت عنوان «سر اختصاص المؤمنين بالذكر في قوله لقوم يؤمنون»","url":""}]},{"id":"s7-1531","number":1531,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما دلالة بناء ﴿قُرئ القرآن﴾ للمجهول؟","answer":"يوجه البناء للمفعول الانتباه إلى القراءة نفسها وما يجب لها من الاستماع، من غير انشغال بشخص القارئ. فالمقام لتعظيم القرآن وتوجيه السامعين إلى تلقيه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص490، تحت «سر مجيء الفعل الماضي المبني للمفعول»","url":""}]},{"id":"s7-1532","number":1532,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما سر التصريح بلفظ ﴿القرآن﴾ في ﴿وإذا قرئ القرآن﴾ بعد الحديث عنه؟","answer":"هو إظهار في مقام الإضمار ينوه بشأن القرآن، ويجعل الأمر بالاستماع إليه دالًا بنفسه لا يتوقف على استحضار مرجع ضمير؛ فيزداد الاهتمام بالكلام وبحق القرآن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص490–491، تحت «نكتة وضع المظهر موضع المضمر في ذكر لفظ القرآن»","url":""}]},{"id":"s7-1533","number":1533,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما الفرق بين ﴿فاستمعوا له﴾ و﴿أنصتوا﴾؟","answer":"الاستماع قصد السمع وإقبال القلب على المقروء، والإنصات ترك الكلام والشاغل؛ فجمع بين فعل التلقي وإزالة ما يمنعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص495، تحت عنوان «الاستماع والإنصات»","url":""}]},{"id":"s7-1534","number":1534,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما سرّ تقديم الاستماع على الإنصات؟","answer":"يراعي الترتيب مراتب تلقي القرآن: يبدأ المستمع بإلقاء السمع إلى ما يتلى، ثم يكمل ذلك بالإنصات والتفرغ للنظر والفهم والاهتداء. فالإنصات أعلى مراتب التلقي في هذا البيان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص492–493، تحت «سر تقديم الاستماع على الإنصات في قوله فاستمعوا له وأنصتوا»","url":""}]},{"id":"s7-1535","number":1535,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما سر الأمر بـ﴿فاستمعوا﴾ بدل الاكتفاء بطلب السماع؟","answer":"الاستماع إقبال مقصود وعقد للقلب على تلقي المقروء، أما السماع فقد يحصل من غير قصد. فالمطلوب الإصغاء الواعي الذي يقود إلى فهم القرآن والعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص491–492، تحت «إيثار صيغة الأمر بالاستماع لا بالسماع»","url":""}]},{"id":"s7-1536","number":1536,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"كيف يؤكد الأمر بـ﴿وأنصتوا﴾ حسن تلقي القرآن؟","answer":"الإنصات استماع مع ترك الكلام، فيؤكد الإقبال على القرآن وترك ما يشغل عنه. ويذكر المصدر احتمال حمل الاستماع على الامتثال أيضًا، فيجمع الأمر بين حسن التلقي والاستجابة للهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص492، تحت «دلالة عطف قوله وأنصتوا على الجملة التي قبله»","url":""}]},{"id":"s7-1537","number":1537,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما دلالة عطف الإنصات بالواو؟","answer":"يدل على أن الاستماع والإنصات مطلوبان مجتمعين، من غير جعل أحدهما نتيجة زمنية لازمة للآخر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص492، تحت «دلالة عطف قوله وأنصتوا على الجملة التي قبله»","url":""}]},{"id":"s7-1538","number":1538,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما فائدة قوله لعلكم ترحمون؟","answer":"جعل الرحمة ثمرة مرجوة للاستماع والإنصات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص493–494، تحت عنوان «فائدة قوله لعلكم ترحمون»","url":""}]},{"id":"s7-1663","number":1663,"surah":7,"verses":[204],"references":[{"surah":7,"verses":[204]}],"verseLabel":"الأعراف: 204","question":"ما دلالة إيثار ذكر الرحمة دون الفلاح أو غيره؟","answer":"لأنهما طريق فهم القرآن وقبول هدايته والعمل به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص493–494، تحت عنوان «إيثار ذكر الرحمة دون الفلاح أو غيره»","url":""}]},{"id":"s7-1539","number":1539,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما سر الأمر بالذكر دون غيره؟","answer":"بعد تلقي كلام الله أمر باستدامة الصلة به بالذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص498، تحت عنوان «سر الأمر بالذكر دون غيره»","url":""}]},{"id":"s7-1664","number":1664,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما دلالة الواو وتوجيه الخطاب في قوله واذكر ربك؟","answer":"الاستماع غذاء من الوحي، والذكر استجابة قلبية تحفظ أثره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496، تحت عنوان «دلالة الواو وتوجيه الخطاب في قوله واذكر ربك»","url":""}]},{"id":"s7-1540","number":1540,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما دلالة اختيار ﴿ربك﴾ في ﴿واذكر ربك﴾؟","answer":"يستحضر التربية والرعاية والإنعام، ويضيف الرب إلى النبي تشريفًا وتقريبًا يحفزه على دوام الذكر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص498–499، تحت عنوان «فائدة إضافة رب إلى ضمير المخاطب في قوله واذكر ربك»","url":""}]},{"id":"s7-1541","number":1541,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما دلالة قوله تعالى: ﴿في نفسك﴾؟","answer":"يدل على الذكر الخفي الحاضر في القلب، البعيد عن الرياء، مع استبطان عظمة المذكور ومراقبته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص499، تحت «علة اختيار في الظرفية في قوله: ﴿في نفسك﴾»","url":""}]},{"id":"s7-1542","number":1542,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما نكتة عطف قوله وخيفة على قوله تضرعًا؟","answer":"التضرع إظهار الذل والافتقار، والخيفة خوف القلب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص501، تحت عنوان «نكتة عطف قوله وخيفة على قوله تضرعًا»","url":""}]},{"id":"s7-1665","number":1665,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما معنى تضرعًا وخيفة في السياق؟","answer":"جمع بين هيئة العبودية الظاهرة وحالها الباطنة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص496، تحت عنوان «شرح المفردات: تضرعًا وخيفة»","url":""}]},{"id":"s7-1543","number":1543,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما دلالة ﴿خيفة﴾ في وصف الذكر؟","answer":"الخيفة حالة خوف تستحضر القلب وتناسب الخشوع في الذكر؛ ويبين المصدر أن هذا الانفعال قد يصاحبه خفض الصوت. فهي حال للذاكر، لا مجرد أداء ألفاظ الذكر بلا حضور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص501–502، تحت عنوان «نكتة عطف قوله وخيفة على قوله تضرعًا»","url":""}]},{"id":"s7-1544","number":1544,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما الفرق بين ﴿ودون الجهر من القول﴾ و«سرًا»؟","answer":"﴿دون الجهر﴾ يثبت قولًا مسموعًا منخفضًا بين الجهر والإسرار التام، فيجمع حضور اللسان وخشوع الصوت.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص502، تحت عنوان «فائدة قوله ودون الجهر»","url":""}]},{"id":"s7-1545","number":1545,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما دلالة تقييد الذكر بـ﴿بالغدو والآصال﴾؟","answer":"خُص أول النهار وآخره لأنهما طرفاه وأوقات تجدد الأحوال، وذكر الطرفين كناية عن ملازمة الذكر في اليوم كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص503، تحت عنوان «المراد بقوله بالغدو والآصال»","url":""}]},{"id":"s7-1546","number":1546,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"كيف يعبر ﴿بالغدو والآصال﴾ عن ملازمة الذكر؟","answer":"الغدو وقت أول النهار، والآصال أوقات العشي، وهي جمع أصيل. وذكر الطرفين يحث على استدامة الذكر وتجديد الصلة بالله في أحوال اليوم، لا على حصره في هذين الوقتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص503، تحت عنوان «المراد بقوله بالغدو والآصال»","url":""}]},{"id":"s7-1547","number":1547,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما مناسبة النهي في ﴿ولا تكن من الغافلين﴾؟","answer":"لما أمر بدوام الذكر نهى عن ضده، وهو الغفلة التي تقطع الصلة بالله وتفتح مدخل الشيطان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص504، تحت عنوان «دلالة الواو في قوله ولا تكن من الغافلين»","url":""}]},{"id":"s7-1548","number":1548,"surah":7,"verses":[205],"references":[{"surah":7,"verses":[205]}],"verseLabel":"الأعراف: 205","question":"ما الفرق بين ﴿ولا تكن من الغافلين﴾ و«ولا تكن غافلًا»؟","answer":"النهي عن الكون من الغافلين أبلغ من مجرد النهي عن الغفلة؛ إذ يحذر من اكتساب وصفهم والتخلق بطريقتهم، حتى لا يصير الذكر أمرًا عارضًا والغفلة حالًا ملازمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص505، تحت «فائدة دخول لا على تكن»","url":""}]},{"id":"s7-1549","number":1549,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما مناسبة ختم السورة بذكر ﴿الذين عند ربك﴾؟","answer":"جعل الملائكة المقربين قدوة في دوام العبادة بعد الأمر بالذكر والنهي عن الغفلة، وفيه حث على التشبه بأهل الطاعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص509–510، تحت «علة فصل قوله إن الذين عند ربك عما قبله»","url":""}]},{"id":"s7-1550","number":1550,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"من المراد بـ﴿الذين عند ربك﴾، وما دلالة العندية؟","answer":"المشهور أنهم الملائكة المقربون، والعندية عندية منزلة وزلفى ورحمة، لا قرب مكان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص510–511، تحت عنوان «دلالة الظرفية في قوله عند ربك»","url":""}]},{"id":"s7-1551","number":1551,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة اختيار ﴿ربك﴾ في وصف قرب الملائكة؟","answer":"يستحضر رعاية الله للنبي ويشرفه بالإضافة، ويحثه على الالتحاق في الذكر بمن قربتهم طاعتهم من رحمة ربه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص511، تحت «فائدة إضافة الظرف إلى الرب وتخصيصه»","url":""}]},{"id":"s7-1552","number":1552,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما مناسبة قوله تعالى: ﴿لا يستكبرون عن عبادته﴾ بعد النهي عن الغفلة؟","answer":"يعلل الحث على الذكر بحال الملائكة: علو منزلتهم لم يحملهم على ترك العبادة، فالبشر أولى باجتناب الغفلة والاستكبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص512، تحت عنوان «بلاغة التعبير بصيغة المضارع في قوله لا يستكبرون»","url":""}]},{"id":"s7-1553","number":1553,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة تعدية الاستكبار بـ﴿عن﴾؟","answer":"تصور الاستكبار انصرافًا ومجاوزةً للعبادة؛ فنفت عن الملائكة أن يحملهم علوهم على البعد عنها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص512–513، تحت «دلالة المجاوزة بحرف الجر عن»","url":""}]},{"id":"s7-1554","number":1554,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة إضافة العبادة إلى ضميره في ﴿عبادته﴾؟","answer":"تخص العبادة بالله الذي ذُكر بوصف الرب، وتبرز شرفها لأنها عبادة له وحده لا لغيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص513–514، تحت «فائدة إضافة العبادة إلى ضمير اسم الجلالة»","url":""}]},{"id":"s7-1555","number":1555,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة العطف في ﴿ويسبحونه وله يسجدون﴾؟","answer":"فصّل عبادتهم بعد نفي الاستكبار: ينزهونه بأقوالهم واعتقادهم، ويخضعون له بالسجود؛ فجمع التنزيه والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص514–515، تحت عنوان «أثر الواو في قوله وله يسجدون في المعنى»","url":""}]},{"id":"s7-1556","number":1556,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة تقديم ﴿له﴾ على ﴿يسجدون﴾؟","answer":"يفيد الاختصاص: لله وحده يسجدون، لا يشركون به في غاية الخضوع أحدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص515–516، تحت «سر تقديم الجار والمجرور وله على الفعل يسجدون»","url":""}]},{"id":"s7-1557","number":1557,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما سرّ تقديم التسبيح على السجود؟","answer":"ذكر التسبيح يبين تنزيههم لله عن النقائص والشريك، ثم أفرد السجود بالذكر لمزيد شرفه وكونه غاية الخضوع. فالانتقال يجمع التنزيه وكمال العبادة، ويختم بأعظم صور الخضوع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص516، تحت عنوان «إيثار استعمال السجود دون غيره من ألوان العبادة»","url":""}]},{"id":"s7-1558","number":1558,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة المضارع في ﴿يستكبرون... يسبحونه... يسجدون﴾؟","answer":"يدل على تجدد هذه الأحوال واستمرارها؛ فلا يقع منهم استكبار، ويتكرر تسبيحهم وسجودهم بلا فتور.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص511، تحت عنوان «بلاغة التعبير بصيغة المضارع في قوله لا يستكبرون»","url":""}]},{"id":"s7-1559","number":1559,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة علاقة ختام السورة بأولها في خطاب النبي الأكرم وتوجيهه وتثبيته؟","answer":"افتتحت السورة باتباع الوحي، وختمت بأثر الاتباع وغايته: تنزيه الله والخضوع له وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص516–517، تحت عنوان «علاقة ختام السورة بأولها في خطاب النبي الأكرم وتوجيهه وتثبيته»","url":""}]},{"id":"s7-1666","number":1666,"surah":7,"verses":[206],"references":[{"surah":7,"verses":[206]}],"verseLabel":"الأعراف: 206","question":"ما دلالة إيثار استعمال السجود دون غيره من ألوان العبادة؟","answer":"جمع طرفاها بين تلقي الأمر وتحقيق العبودية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص516–517، تحت عنوان «إيثار استعمال السجود دون غيره من ألوان العبادة»","url":""}]},{"id":"s8-1","number":1,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما مناسبة افتتاح السورة بقوله: ﴿يسألونك عن الأنفال﴾ قبل أن تذكر غزوة بدر وأحداثها؟","answer":"افتتحت بالسؤال عن الأنفال لأنها قضية حاضرة في أذهان السائلين، ومثار جدال ونزاع بعد بدر؛ فدل تقديمها على شدة اهتمامهم بها، ثم جاء الجواب ليرد حكمها إلى الله ورسوله ويهيئهم للتسليم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص536–537، تحت «دلالة براعة الاستهلال، باستعراض الجواب على السؤال»","url":""}]},{"id":"s8-2","number":2,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿يسألونك﴾، دون أن يقال: «يستفتونك» عن الأنفال؟","answer":"اختير السؤال لما فيه من استعجال المطلوب والتشوف إلى معرفته، بخلاف الاستفتاء الذي يغلب فيه طلب كشف أمر غامض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص537، تحت «نكتة استعمال الفعل ﴿يسألونك﴾ دون غيره»","url":""}]},{"id":"s8-3","number":3,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا عُدّي السؤال بـ﴿عن﴾: ﴿يسألونك عن الأنفال﴾، ولم يقل: «يسألونك الأنفال»؟","answer":"عُدّي الفعل بـ﴿عن﴾ لأن سؤالهم كان عن حكم الأنفال ومآلها وقسمتها، لا سؤال طلبٍ للأنفال أنفسها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص538–539، تحت «سر التعبير بحرف الجر ﴿عن﴾ وفائدة وروده في السياق»","url":""}]},{"id":"s8-4","number":4,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا أُسند السؤال إلى النبي ﷺ بكاف الخطاب: ﴿يسألونك﴾، مع أن الحكم سيأتي من الله؟","answer":"وُجّه السؤال إلى الرسول ﷺ لأنه المبلّغ عن الله والمنفذ لحكمه في الأنفال، ثم جاء الجواب وحيًا من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص538، تحت «علة اتصال الفعل بكاف الخطاب في ﴿يسألونك﴾»","url":""}]},{"id":"s8-5","number":5,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا جاء الجواب بالأمر: ﴿قل﴾، ولم يأت الجواب مباشرة: «الأنفال لله والرسول»؟","answer":"افتتح الجواب بـ﴿قل﴾ لتوثيق الحكم وإظهار أنه وحي من الله، وأن الرسول ﷺ مبلغه بأمانة؛ فلم يكن الجواب رأيًا من عنده، بل حكمًا إلهيًا يفصل فيما سألوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص539، تحت «نكتة استهلال الجواب بفعل الأمر ﴿قل﴾»","url":""}]},{"id":"s8-6","number":6,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿قل﴾ وحذف المخاطبين، فلم يقل: «قل لهم»؟","answer":"لم يقيد القول بقوله «لهم» لأن حكم الأنفال لا يختص بالسائلين يوم بدر؛ بل يجري عليهم وعلى من يأتي بعدهم من المسلمين، فناسب عموم الحكم إطلاق الخطاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص539–540، تحت «إطلاق القول وعدم تقييده بالمخاطبين»","url":""}]},{"id":"s8-7","number":7,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا أعاد لفظ ﴿الأنفال﴾ في الجواب، ولم يقل: «قل هي لله والرسول»؟","answer":"أعيد لفظ ﴿الأنفال﴾ للانتقال من الأنفال المعهودة التي سألوا عنها إلى حكم جنس الأنفال كله؛ فالجواب أعم من السؤال، وليس مقصورًا على غنائم بدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص540، تحت «لطيفة وضع المظهر موضع المضمر»","url":""}]},{"id":"s8-8","number":8,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا كانت ﴿الأنفال﴾ في السؤال للعهد بما غنموه، ثم جاء اللفظ نفسه في الجواب عامًا يشمل جنس الأنفال؟","answer":"الأنفال الأولى هي المعهودة التي سألوا عنها يوم بدر، والثانية في مقام بيان الحكم؛ فجاء اللفظ متناولًا لجنس الأنفال، وحكمُه لله والرسول.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص540، تحت «لطيفة وضع المظهر موضع المضمر»","url":""}]},{"id":"s8-9","number":9,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿الأنفال لله والرسول﴾، ولم يجعل أمرها للغانمين الذين حصلوها؟","answer":"إضافة حكم الأنفال إلى الله والرسول تنزعها من أهواء الغانمين؛ فقسمتها مردها إلى أمر الله وتنفيذ رسوله، لا إلى مجرد إحراز المقاتلين لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص540–541، تحت «بلاغة الجواب»","url":""}]},{"id":"s8-10","number":10,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا اختير اسم الجلالة في ﴿لله﴾، ولم يقل: «للرب»؟","answer":"اختير اسم الجلالة لأنه مقام تشريع وحكم وطاعة، وفيه استحضار الألوهية المستوجبة للامتثال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص541، تحت «فائدة ذكر اللام، وإيثار لفظ الجلالة (الله)»","url":""}]},{"id":"s8-11","number":11,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا قال: ﴿الأنفال لله والرسول﴾، فاختار وصف الرسول دون النبي؟","answer":"اختير ﴿الرسول﴾ لأن المقام مقام تبليغ حكم الله وتنفيذه، وهذه جهة الرسالة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص542، تحت «نكتة إيثار لفظ ﴿الرسول﴾، والعدول عن لفظ (النبي)»","url":""}]},{"id":"s8-12","number":12,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا انتقل من خطاب النبي ﷺ في ﴿يسألونك﴾ إلى وصفه بالغائب في ﴿الأنفال لله والرسول﴾؟","answer":"عُدل من ضمير الخطاب إلى وصف ﴿الرسول﴾ لإبراز علة اختصاصه بالحكم: أنه رسول الله المنفذ لأمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص541–542، تحت «نكتة الالتفات من الخطاب إلى الغيبة»","url":""}]},{"id":"s8-13","number":13,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا فرّع على حكم الأنفال قوله: ﴿فاتقوا الله﴾؟","answer":"فُرّع الأمر بالتقوى على رد الأنفال إلى الله والرسول؛ ليحذروا الطمع والنزاع ومخالفة الحكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص543، تحت «دلالة الفاء في قوله: ﴿فاتقوا الله﴾»","url":""}]},{"id":"s8-14","number":14,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا ربط التقوى باسم الله: ﴿فاتقوا الله﴾، ولم يقل: «فاتقوا ربكم»؟","answer":"ذكر اسم الله يلائم ما سبق من قوله ﴿الأنفال لله﴾، ويستحضر حق الألوهية في الطاعة وترك التنازع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص543، تحت «دلالة ربط التقوى باسم الجلالة دون الربوبية»","url":""}]},{"id":"s8-15","number":15,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا جمع عقب سؤال الغنائم بين ﴿فاتقوا الله﴾ و﴿أصلحوا ذات بينكم﴾؟","answer":"الأمر بإصلاح ذات البين يؤكد مقتضى التقوى؛ فاتقاء مخالفة الله يستلزم ترك النزاع والخصومة في الأنفال والتسليم لقسمتها. وجمعهما يربط صلاح علاقتهم بالله بصلاح ما بينهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص543–544، تحت «دلالة الجمع بين التقوى والإصلاح»","url":""}]},{"id":"s8-16","number":16,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما سرّ التعبير في قوله تعالى: ﴿أصلحوا ذات بينكم﴾، دون أن يقال ببساطة: «أصلحوا بينكم»؟","answer":"﴿ذات بينكم﴾ هي حقيقة الحال والرابطة القائمة بينكم؛ فالأمر يتناول إصلاح الصلة نفسها وحفظ المودة والوحدة، وهو أبلغ من مجرد تسكين خصومة عارضة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص544–545، تحت «بلاغة تركيب ﴿ذات بينكم﴾»","url":""}]},{"id":"s8-17","number":17,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما مناسبة مجيء الأمر بالطاعة بعد التقوى والإصلاح: ﴿وأطيعوا الله ورسوله﴾؟","answer":"جاء الأمر بالطاعة جامعًا لما تقدمه: قبول حكم الأنفال، والتقوى، وإصلاح ذات البين؛ فكلها امتثال لله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص545، تحت «دلالة الواو في قوله: ﴿وأطيعوا الله ورسوله﴾»","url":""}]},{"id":"s8-18","number":18,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا قال أولًا: ﴿الأنفال لله والرسول﴾، ثم قال: ﴿وأطيعوا الله ورسوله﴾ بإضافة الرسول إلى ضمير الله؟","answer":"جاء ﴿الرسول﴾ في حكم الأنفال لإبراز ما فوضه الله إليه من تصريفها بحكم رسالته. وفي الأمر بالطاعة أضيف الرسول إلى ضمير الله؛ ليبين أنه يبلغ عن الله، وأن طاعته جزء من طاعة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص546، تحت «نكتة تعريف لفظ (الرسول) وإضافته في الجملتين»","url":""}]},{"id":"s8-19","number":19,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"لماذا انتقل من ﴿يسألونك﴾ إلى مخاطبة الجماعة بالأوامر: ﴿فاتقوا الله وأصلحوا ذات بينكم وأطيعوا الله ورسوله﴾؟","answer":"لأن هذه الأوامر تختبر إيمان السائلين وتبين مقتضاه العملي؛ فالإيمان يجمع اتقاء المخالفة، وإصلاح العلاقة بالناس، وطاعة الله ورسوله. فانتقل من نقل سؤالهم إلى تكليفهم بما يحقق كمال إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص545، تحت «نكتة توجيه الخطاب إلى الجماعة»","url":""}]},{"id":"s8-20","number":20,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"ما دلالة جواب الشرط ودلالته في قوله: ﴿إن كنتم مؤمنين﴾؟","answer":"التعليق بـ﴿إن كنتم مؤمنين﴾ حث على تحقيق مقتضى الإيمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص548، تحت عنوان «جواب الشرط ودلالته، في قوله: ﴿إن كنتم مؤمنين﴾»","url":""}]},{"id":"s8-266","number":266,"surah":8,"verses":[1],"references":[{"surah":8,"verses":[1]}],"verseLabel":"الأنفال: 1","question":"كيف يفيد التحريض المدلول عليه بحرف (إن)، والعدول عن (إذا)؟","answer":"الإيمان الصادق يحمل على الطاعة وترك التنازع، وليس المقصود نفي أصل إيمانهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص546، تحت عنوان «التحريض المدلول عليه بحرف (إن)، والعدول عن (إذا)»","url":""}]},{"id":"s8-21","number":21,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"ما وجه البلاغة في الحصر بـ﴿إنما﴾ في مستهل الآية الكريمة؟","answer":"القصر يبين أن أصحاب هذه الصفات هم المؤمنون الكاملون في هذا المقام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص553–554، تحت عنوان «بلاغة الحصر بـ﴿إنما﴾ في مستهل الآية الكريمة»","url":""}]},{"id":"s8-267","number":267,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"ما وجه البلاغة في أسلوب القصر ودلالته؟","answer":"الآيات تذكر أصولًا جامعة وآثارًا ظاهرة للإيمان، لا جميع شعبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص553–554، تحت عنوان «بلاغة أسلوب القصر ودلالته»","url":""}]},{"id":"s8-22","number":22,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿إذا ذكر الله وجلت قلوبهم﴾، فجعل الوجل في القلوب لا في النفوس؟","answer":"أُسند الوجل إلى القلوب لأنها محل الشعور الباطن، فدل على خوف عميق نابع من أصل النفس لا مجرد أثر ظاهر في الجوارح.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص557–558، تحت «سر إسناد الوجل إلى القلوب ﴿وجلت﴾»","url":""}]},{"id":"s8-23","number":23,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"لماذا اختير ﴿وجلت﴾ لا «خافت»؟","answer":"اختير الوجل لأنه خوف باطني مصحوب باضطراب وتحرك في القلب، فهو أدق من مطلق الخوف في تصوير تأثر المؤمن بذكر الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص557، تحت «إيثار الفعل ﴿وجلت﴾، والعدول عن مرادفه»","url":""}]},{"id":"s8-24","number":24,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"ما سرّ التعبير في قوله تعالى: ﴿وإذا تليت عليهم آياته زادتهم إيمانًا﴾، فنسب الزيادة إلى الآيات؟","answer":"أُسندت الزيادة إلى الآيات لأنها سببها المباشر عند التلاوة؛ بما تكشفه من معان ودلائل تجدد التصديق واليقين والعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص560، تحت «إسناد الزيادة إلى الآيات وعدم إسنادها إلى المؤمنين»","url":""}]},{"id":"s8-25","number":25,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"ما وجه زيادة الإيمان بسماع الآيات، مع أن المؤمن كان مؤمنًا قبل تلاوتها؟","answer":"الإيمان يقبل الزيادة من جهة قوة التصديق والطمأنينة وكثرة آثاره العملية؛ فكلما تجددت دلالات الآيات ازداد المؤمن يقينًا واستجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص559–560، تحت «سر إيثار استعمال الفعل (زادت) دون غيره»","url":""}]},{"id":"s8-26","number":26,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"لماذا قدّم الجار والمجرور: ﴿وعلى ربهم يتوكلون﴾، ولم يقل: «ويتوكلون على ربهم»؟","answer":"قُدّم ﴿على ربهم﴾ للاختصاص؛ أي يعتمدون على ربهم وحده، لا على الأسباب استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص560–561، تحت «فائدة تقديم الجار والمجرور»","url":""}]},{"id":"s8-27","number":27,"surah":8,"verses":[2],"references":[{"surah":8,"verses":[2]}],"verseLabel":"الأنفال: 2","question":"لماذا اختير اسم الرب في ﴿على ربهم يتوكلون﴾ بعد ذكر اسم الله في الوجل؟","answer":"اختير ﴿ربهم﴾ لاستحضار رعايته وتدبيره وتربيته لهم، وهي معان تبعث على تفويض الأمر إليه والتوكل عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص561، تحت «إيثار استعمال اسم (الرب) دون اسم الجلالة (الله)»","url":""}]},{"id":"s8-28","number":28,"surah":8,"verses":[3],"references":[{"surah":8,"verses":[3]}],"verseLabel":"الأنفال: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿يقيمون الصلاة﴾، دون أن يقال: «يصلون»؟","answer":"إقامة الصلاة أداؤها مستقيمة تامة بأركانها وشروطها وخشوعها ودوامها، فهي أبلغ من مجرد وقوع الصلاة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص569، تحت عنوان «دلالة الفعل ﴿يقيمون﴾، دون الفعل (يصلون)»","url":""}]},{"id":"s8-29","number":29,"surah":8,"verses":[3],"references":[{"surah":8,"verses":[3]}],"verseLabel":"الأنفال: 3","question":"لماذا قدّم ﴿مما رزقناهم﴾ على ﴿ينفقون﴾؟","answer":"قُدّم ﴿مما رزقناهم﴾ لإبراز أن المنفَق بعض عطاء الله لهم، وفيه تذكير بالمنعم قبل ذكر فعل الإنفاق.","sources":[{"label":"في تفسير النظير اللفظي ﴿ومما رزقناهم ينفقون﴾ [البقرة:3]: موسوعة التفسير البلاغي، ج1، ص122–123، تحت «فائدة تقديم الجار والمجرور»","url":""}]},{"id":"s8-30","number":30,"surah":8,"verses":[3],"references":[{"surah":8,"verses":[3]}],"verseLabel":"الأنفال: 3","question":"ما سرّ التعبير في قوله تعالى: ﴿مما رزقناهم﴾ بـ«من» التبعيضية، ولم يأمرهم بإنفاق كل الرزق؟","answer":"دلّت ﴿من﴾ على التبعيض؛ رحمة بالمكلف وإبقاء لما تقوم به مصالحه، فالإنفاق المشروع ليس استغراق المال كله.","sources":[{"label":"في تفسير النظير اللفظي ﴿ومما رزقناهم ينفقون﴾ [البقرة:3]: موسوعة التفسير البلاغي، ج1، ص122–123، تحت «فائدة تقديم الجار والمجرور»","url":""}]},{"id":"s8-31","number":31,"surah":8,"verses":[3],"references":[{"surah":8,"verses":[3]}],"verseLabel":"الأنفال: 3","question":"لماذا وصف المال المنفق بأنه رزق: ﴿ومما رزقناهم ينفقون﴾، ولم يقل: ومما كسبوا؟","answer":"الرزق يبرز جهة العطاء من الله، أما الكسب فيبرز سعي الإنسان وجهده، وقد يأتي الرزق من غير كسب. فالتعبير يذكرهم بأن ما ينفقونه من عطاء الله لهم، وإن حصل بعضه بسعيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص569–570، تحت «الرزق والكسب»","url":""}]},{"id":"s8-32","number":32,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"لماذا أعاد الإشارة إليهم بقوله: ﴿أولئك هم المؤمنون حقًا﴾ بعد قوله: ﴿إنما المؤمنون﴾؟","answer":"الإشارة بـ﴿أولئك﴾ تجمع أصحاب الصفات السابقة وتميزهم، ثم تقرر لهم حقيقة الإيمان وكماله جزاءً على اجتماعها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص573–574، تحت «دلالة اسم الإشارة ﴿أولئك﴾ وموقعها الإعرابي»","url":""}]},{"id":"s8-33","number":33,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"لماذا توسط ضمير الفصل ﴿هم﴾ في ﴿أولئك هم المؤمنون﴾؟","answer":"ضمير الفصل ﴿هم﴾ يقوي الحكم ويفيد قصر كمال الإيمان عليهم في هذا المقام، وينفيه عمن تخلفت عنه تلك الصفات.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص574–575، تحت «أثر الضمير المنفصل، وفائدته في السياق»","url":""}]},{"id":"s8-34","number":34,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"ما سرّ التعبير في قوله تعالى: ﴿حقًا﴾ بعد هذا التوكيد كله؟","answer":"﴿حقًا﴾ تؤكد أن إيمانهم ثابت متحقق، لا دعوى باللسان ولا وصفًا مجازيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص576، تحت «فائدة قوله: ﴿حقًا﴾ وتوجيه الوقف عليها»","url":""}]},{"id":"s8-35","number":35,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"لماذا جاءت ﴿درجات﴾ جمعًا، بينما الإيمان الموصوف واحد؟","answer":"تتفاوت مراتب الجزاء بحسب تفاوت أحوال القلوب ودرجات الإيمان والتوكل؛ فناسب ذلك جمع الدرجات. وتنكيرها يزيد تعظيمها في ذاتها وفي تفاوت ما بينها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص577–578، تحت عنوان «علة تنكير لفظ ﴿درجات﴾»","url":""}]},{"id":"s8-36","number":36,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"ما وجه البلاغة في ختم الآية بقوله: ﴿ورزق كريم﴾؟","answer":"من وجوه الترتيب أن الدرجات تقابل أعمال القلوب، والمغفرة تقابل الصلاة، والرزق الكريم يقابل الإنفاق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص580، تحت عنوان «بلاغة ختم الآية بقوله: ﴿ورزق كريم﴾»","url":""}]},{"id":"s8-268","number":268,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"ما نكتة عطف المغفرة على الدرجات؟","answer":"ي ختمه بالرزق الكريم أيضًا دفع لتوهم أن تفاوت الدرجات يعني نقص نعيم من كان دون غيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص577، تحت عنوان «نكتة عطف المغفرة على الدرجات»","url":""}]},{"id":"s8-37","number":37,"surah":8,"verses":[4],"references":[{"surah":8,"verses":[4]}],"verseLabel":"الأنفال: 4","question":"لماذا وصف الرزق نفسه بأنه ﴿كريم﴾؟","answer":"الكرم يدل هنا على كمال الرزق ونفاسته وخلوه من النقص والتكدير؛ فهو حاصل على وجه الإكرام والتعظيم. ويحتمل الوصف أيضًا إظهار كرم رازقه سبحانه، بإسناد الوصف إلى الرزق الذي تجلى فيه هذا الإنعام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص579، تحت «بلاغة المجاز العقلي بإسناد الفعل والوصف إلى غير صاحبه»","url":""}]},{"id":"s8-38","number":38,"surah":8,"verses":[5],"references":[{"surah":8,"verses":[5]}],"verseLabel":"الأنفال: 5","question":"ما دلالة بيان التشبيه التمثيلي، في قوله: ﴿كما أخرجك ربك﴾؟","answer":"التشبيه يربط كراهة بعضهم حكم الأنفال بكراهتهم الخروج للقتال أول الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص583–584، تحت عنوان «بيان التشبيه التمثيلي، في قوله: ﴿كما أخرجك ربك﴾»","url":""}]},{"id":"s8-269","number":269,"surah":8,"verses":[5],"references":[{"surah":8,"verses":[5]}],"verseLabel":"الأنفال: 5","question":"ما دلالة اتصال التشبيه بما قبله، في قوله: ﴿كما أخرجك﴾؟","answer":"في الحالين كان أمر الله حقًا وكانت العاقبة خيرًا لهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص583–584، تحت عنوان «دلالة اتصال التشبيه بما قبله، في قوله: ﴿كما أخرجك﴾»","url":""}]},{"id":"s8-39","number":39,"surah":8,"verses":[5],"references":[{"surah":8,"verses":[5]}],"verseLabel":"الأنفال: 5","question":"لماذا أسند الخروج إلى الرب: ﴿أخرجك ربك﴾؟","answer":"إسناد الإخراج إلى ﴿ربك﴾ يشعر بالتدبير والرعاية؛ فالخروج لم يكن مصادفة، بل بتوجيه الرب الذي تولى نصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص584–585، تحت «دلالة التعبير بصيغة ﴿أخرجك﴾»","url":""}]},{"id":"s8-40","number":40,"surah":8,"verses":[5],"references":[{"surah":8,"verses":[5]}],"verseLabel":"الأنفال: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿من بيتك﴾، دون أن يقال: «من المدينة»؟","answer":"يحتمل ﴿بيتك﴾ مسكنه حقيقة، ويحتمل المدينة لأنها دار هجرته وسكناه. والتعبير بالبيت يصور مفارقة موطن الأنس والسكن إلى موطن القتال؛ وفيه تذكير بما تحقق بعد ذلك الخروج من النصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص586، تحت «دلالة قوله: ﴿بيتك﴾، وفائدة إضافته إلى ضمير المخاطب»","url":""}]},{"id":"s8-41","number":41,"surah":8,"verses":[5],"references":[{"surah":8,"verses":[5]}],"verseLabel":"الأنفال: 5","question":"لماذا قُيّد الإخراج بـ﴿بالحق﴾؟","answer":"قُيّد الخروج بـ﴿بالحق﴾ لبيان أنه جرى بأمر الله ولغاية عادلة، وإن كره فريق ما آل إليه أول الأمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص586، تحت «معنى الباء في قوله: ﴿بالحق﴾، وأثره في المعنى»","url":""}]},{"id":"s8-42","number":42,"surah":8,"verses":[5],"references":[{"surah":8,"verses":[5]}],"verseLabel":"الأنفال: 5","question":"ما سرّ التعبير في قوله تعالى: ﴿فريقًا من المؤمنين﴾، ولم يعمم الكراهة على المؤمنين؟","answer":"قيل ﴿فريقًا﴾ إنصافًا؛ فالكراهة لم تعم المؤمنين، وإنما صدرت من طائفة منهم بسبب ضعف الاستعداد للقتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص587–588، تحت عنوان «فائدة التعبير بقوله: ﴿فريقًا﴾»","url":""}]},{"id":"s8-43","number":43,"surah":8,"verses":[6],"references":[{"surah":8,"verses":[6]}],"verseLabel":"الأنفال: 6","question":"لماذا عبّر بالمضارع: ﴿يجادلونك﴾، مع أن الجدال وقع وانتهى؟","answer":"المضارع يحكي الحال الماضية ويستحضرها، فكأن السامع يشاهد جدالهم وقت وقوعه؛ وفي ذلك زيادة تعجيب من الموقف، بخلاف مجرد الإخبار بالفعل الماضي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص595، تحت «نكتة استعمال صيغة المضارع ﴿يجادلونك﴾»","url":""}]},{"id":"s8-44","number":44,"surah":8,"verses":[6],"references":[{"surah":8,"verses":[6]}],"verseLabel":"الأنفال: 6","question":"ما سرّ التعبير في قوله تعالى: ﴿يجادلونك في الحق﴾، وكيف يجادل المؤمن في حق تبين له؟","answer":"الحق هو الخروج للقاء ذي الشوكة بعد أن ظهر لهم وجهه، وكان جدالهم ناشئًا من كراهة القتال وقلة الاستعداد، لا من إنكار الحق بعد معرفته.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص595–596، تحت عنوان «فائدة قوله: ﴿في الحق﴾»","url":""}]},{"id":"s8-45","number":45,"surah":8,"verses":[6],"references":[{"surah":8,"verses":[6]}],"verseLabel":"الأنفال: 6","question":"لماذا شبّههم بمن ﴿يساقون إلى الموت﴾، ولم يقل: كأنهم ذاهبون إليه؟","answer":"اختير ﴿يساقون﴾ لتصوير شدة كراهتهم واضطرارهم إلى ما يخافون، كمن يدفع إلى الموت دفعًا لا يملك معه رجوعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص599، تحت «نكتة التعبير بـ﴿يساقون﴾ دون مرادفاته»","url":""}]},{"id":"s8-46","number":46,"surah":8,"verses":[6],"references":[{"surah":8,"verses":[6]}],"verseLabel":"الأنفال: 6","question":"لماذا بُني ﴿يساقون﴾ للمجهول؟","answer":"بني الفعل للمفعول لأن السائق معلوم لا يحتاج إلى تعيين؛ فالاهتمام بحال من يساق إلى الموت وما يستولي عليه من خوف، حتى تشغله هول وجهته عن الالتفات إلى من يسوقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص599، تحت «دلالة التعبير بصيغة المضارع المبني للمفعول»","url":""}]},{"id":"s8-47","number":47,"surah":8,"verses":[6],"references":[{"surah":8,"verses":[6]}],"verseLabel":"الأنفال: 6","question":"لماذا ختم التشبيه بقوله: ﴿وهم ينظرون﴾، وحذف ما ينظرون إليه؟","answer":"﴿وهم ينظرون﴾ يزيد الصورة رهبة؛ فهم يعاينون أسباب الموت أمامهم، وحُذف المفعول لتذهب النفس في تصور ما يرونه من الهول كل مذهب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص600–601، تحت عنوان «حذف متعلق الفعل ﴿ينظرون﴾»","url":""}]},{"id":"s8-48","number":48,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"ما الذي يحدده التعبير بـ﴿إحدى الطائفتين﴾ في وعد الله لهم؟","answer":"يحدد أن الوعد كان بالظفر بواحدة من الطائفتين: العير أو النفير، لا بهما جميعًا. ولذلك لم يكن تعلق رغبتهم بالعير تحديدًا ملزمًا لما وعدهم الله به.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص606، تحت «معنى ﴿إحدى الطائفتين﴾، وعلة تخصيصها بالإضافة»","url":""}]},{"id":"s8-49","number":49,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"لماذا عبّر عن العير بـ﴿غير ذات الشوكة﴾؟","answer":"عُبر عن العير بـ﴿غير ذات الشوكة﴾؛ لأن الشوكة كناية عن القوة والسلاح، فدل التعبير على سهولة أخذها وقلة منعتها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص608–609، تحت عنوان «سر التعبير بقوله: ﴿غير ذات الشوكة﴾»","url":""}]},{"id":"s8-50","number":50,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"ما سرّ التعبير في قوله تعالى: ﴿تكون لكم﴾، دون أن يقال: «تأخذونها»؟","answer":"﴿تكون لكم﴾ أوسع من «تأخذونها»؛ إذ تفيد صيرورتها خالصة لهم وتمكنهم منها، لا مجرد فعل الأخذ.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص609، تحت عنوان «فائدة الفعل ﴿تكون﴾ في: ﴿تكون لكم﴾»","url":""}]},{"id":"s8-51","number":51,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"لماذا قابل إرادة المؤمنين السهولة بقوله: ﴿ويريد الله أن يحق الحق﴾؟","answer":"قوبلت إرادتهم العاجلة للعير السهلة بإرادة الله إظهار الحق؛ لبيان أن اختياره لهم أعظم عاقبة من اختيارهم لأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص609، تحت «سر العدول عن (ود) إلى (يريد)»","url":""}]},{"id":"s8-52","number":52,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"ما وجه البلاغة في جناس الاشتقاق في: ﴿يحق الحق﴾؟","answer":"إحقاق الحق إظهاره وإثباته وتغليبه في الواقع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص610–611، تحت عنوان «بلاغة جناس الاشتقاق في: ﴿يحق الحق﴾»","url":""}]},{"id":"s8-270","number":270,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"ما دلالة الدلالة الصوتية في كلمتي: ﴿يحق الحق﴾؟","answer":"الحق ثابت في ذاته، لكنه يحتاج إلى إظهار سلطانه وإبطال ما ينازعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص610–611، تحت عنوان «الدلالة الصوتية في كلمتي: ﴿يحق الحق﴾»","url":""}]},{"id":"s8-53","number":53,"surah":8,"verses":[7],"references":[{"surah":8,"verses":[7]}],"verseLabel":"الأنفال: 7","question":"ما الصورة في قوله: ﴿ويقطع دابر الكافرين﴾؟","answer":"قطع الدابر كناية عن الاستئصال؛ إذ يبدأ المستأصل بأول الشيء ويتتبعه حتى يبلغ آخره، فلا يبقي منه شيئًا. فصور التعبير إزالة قوتهم ومكرهم ببلوغ القطع إلى آخرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص612–613، تحت «بلاغة المجاز في: ﴿ويقطع دابر الكافرين﴾»","url":""}]},{"id":"s8-54","number":54,"surah":8,"verses":[8],"references":[{"surah":8,"verses":[8]}],"verseLabel":"الأنفال: 8","question":"لماذا تكرر ﴿ليحق الحق﴾ بعد ذكره في الآية السابقة؟","answer":"الأول متعلق بإرادة الله اختيار المواجهة ذات الشوكة، والثاني تعليل لما جرى من النصر؛ فتكراره يثبت أن الغاية إظهار الحق لا مجرد إحراز الغنيمة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص614–615، تحت «نكتة إيراد قوله: ﴿ليحق الحق﴾ بعد: ﴿أن يحق الحق﴾»","url":""}]},{"id":"s8-55","number":55,"surah":8,"verses":[8],"references":[{"surah":8,"verses":[8]}],"verseLabel":"الأنفال: 8","question":"لماذا قابل ﴿يحق الحق﴾ بـ﴿يبطل الباطل﴾، ولم يقل: يهزم الكافرين؟","answer":"المقابلة بين إحقاق الحق وإبطال الباطل تصرح برفض الله للباطل، وتؤكد إثبات الحق بنفي ضده؛ فليس المقصود مجرد هزيمة قوم، بل إظهار الحق وإزالة ما يناقضه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص616، تحت «دلالة عطف: ﴿ويبطل الباطل﴾ على ما قبلها»","url":""}]},{"id":"s8-56","number":56,"surah":8,"verses":[8],"references":[{"surah":8,"verses":[8]}],"verseLabel":"الأنفال: 8","question":"لماذا وصف المعاندين هنا بـ﴿المجرمون﴾ لا «الكافرون»؟","answer":"وصفهم بالمجرمين يبرز أن عنادهم فعل مكتسب وجناية تستحق الإبطال والعقوبة، لا مجرد وصف اعتقادي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص617، تحت «إيثار استعمال كلمة ﴿المجرمون﴾ دون غيرها»","url":""}]},{"id":"s8-57","number":57,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"ما سرّ التعبير في قوله تعالى: ﴿إذ تستغيثون ربكم﴾، دون أن يقال: «إذ تدعون الله»؟","answer":"الاستغاثة طلب الغوث عند الشدة، فهي تصور اضطرار المؤمنين وخطر الموقف، وذكر ﴿ربكم﴾ يستحضر رعايته ونصره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص623–624، تحت عنوان «نكتة التعبير باسم الربوبية في ﴿إذ تستغيثون ربكم﴾»","url":""}]},{"id":"s8-58","number":58,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"لماذا جاء جواب الاستغاثة سريعًا بالفاء: ﴿فاستجاب لكم﴾؟","answer":"الفاء تفيد سرعة ترتب الاستجابة على الاستغاثة، فتوحي بقرب الإغاثة وعناية الله بالمؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص624–625، تحت «دلالة (الفاء) في ﴿فاستجاب لكم﴾»","url":""}]},{"id":"s8-59","number":59,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"لماذا عبّر بـ﴿ممدكم﴾، لا «مرسل إليكم»؟","answer":"الإمداد إلحاق مدد يقوي الموجود ويتتابع عليه، فهو أنسب بحال جيش يحتاج إلى ما يعززه من مجرد الإرسال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص619–620، تحت «شرح المفردات: ﴿ممدكم﴾»","url":""}]},{"id":"s8-60","number":60,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"ما الذي تضيفه البشارة بعدد معين: ﴿بألف من الملائكة﴾ إلى طمأنينة المؤمنين؟","answer":"تذكرهم هذه البشارة المحددة بقدرة الله على حماية رسوله والمؤمنين، وبعنايته بهم في ذلك الموقف. وتنكير ﴿ألف﴾ للتعظيم يزيد وقع المدد في نفوسهم، فيقوى رجاؤهم ويطمئنون إلى وعده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص626–627، تحت «معاني الحروف وأثر القراءات في قوله: ﴿بألف من الملائكة﴾»","url":""}]},{"id":"s8-61","number":61,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"لماذا وصف الملائكة بـ﴿مردفين﴾؟","answer":"﴿مردفين﴾ تدل على مجيء الملائكة متتابعين يردف بعضهم بعضًا، أو مردَفين بغيرهم، وفي الحالين تصوير لتوالي المدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص627–628، تحت «توجيه القراءات في لفظ: ﴿مردفين﴾»","url":""}]},{"id":"s8-62","number":62,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"لماذا جاء المدد في الأنفال بـ﴿ألف من الملائكة مردفين﴾، وفي آل عمران بثلاثة آلاف ثم خمسة آلاف؟","answer":"تدرجت البشارة بحسب ما بلغ المسلمين من كثرة عدوهم ومدده: بدأ الوعد بألف، ثم بثلاثة آلاف، ثم بخمسة آلاف مع ازدياد التخوف. فاختلاف الأعداد حكاية لبشارات متدرجة تزيد الطمأنينة، ولا تعارض بين الأخبار.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص698، تحت «الحكمة من تدرج ذكر المدد بين سورتي الأنفال وآل عمران»","url":""}]},{"id":"s8-63","number":63,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"ما دلالة القراءات في لفظ ﴿مردفين﴾؟","answer":"تدل القراءات على تتابع الملائكة بعضهم إثر بعض، أو على إردافهم بغيرهم من المدد؛ وفي الحالين تبرز صورة توالي النصر الإلهي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص627–628، تحت «توجيه القراءات في لفظ: ﴿مردفين﴾»","url":""}]},{"id":"s8-271","number":271,"surah":8,"verses":[9],"references":[{"surah":8,"verses":[9]}],"verseLabel":"الأنفال: 9","question":"ما سر الكناية عن الشدة بالتسويم؟","answer":"التسويم إظهار العلامة والتهيؤ للحرب، فكني به عن شدة الملائكة وقوتهم وهيئتهم المهيبة في القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج5، ص698–699، تحت «سر الكناية عن الشدة بالتسويم»","url":""}]},{"id":"s8-64","number":64,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"ما دلالة تعيين مرجع الضمير في قوله: ﴿وما جعله﴾؟","answer":"لذلك عقب بقوله: ﴿وما النصر إلا من عند الله﴾، فالأسباب لا تستقل بالنصر عن مسببها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص633، تحت عنوان «تعيين مرجع الضمير في قوله: ﴿وما جعله﴾»","url":""}]},{"id":"s8-272","number":272,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"ما وجه البلاغة في القصر بالاستثناء بعد النفي؟","answer":"المراد أن خبر الإمداد، أو الإمداد نفسه، جعل بشارة وتثبيتًا لقلوبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص634، تحت عنوان «بلاغة القصر بالاستثناء بعد النفي»","url":""}]},{"id":"s8-273","number":273,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"ما وجه البلاغة في الاحتراس؟","answer":"لا ينسبوا النصر إلى العدد والعدة استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص639، تحت عنوان «بلاغة الاحتراس»","url":""}]},{"id":"s8-65","number":65,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"ما سرّ التعبير في قوله تعالى: ﴿ولتطمئن به قلوبكم﴾، مع أن البشرى موجهة إليهم جميعًا؟","answer":"أُسند الاطمئنان إلى القلوب لأنها محل الخوف والسكينة، فدل على أمن داخلي يعم الجماعة من أصل شعورها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص631، تحت عنوان «شرح المفردات: ﴿ولتطمئن﴾»","url":""}]},{"id":"s8-67","number":67,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"لماذا اعترض بقوله: ﴿وما النصر إلا من عند الله﴾ وسط الحديث عن الملائكة؟","answer":"اعترض بنفي النصر إلا من عند الله لئلا يتعلق القلب بالملائكة أو العدد، فهما بشرى وسبب، أما موجد النصر فهو الله وحده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص638–639، تحت عنوان «بلاغة القصر في الآية»","url":""}]},{"id":"s8-68","number":68,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"لماذا أعيد اسم الله في ﴿وما النصر إلا من عند الله﴾ بعد قوله: ﴿وما جعله الله إلا بشرى﴾؟","answer":"إظهار اسم الله بدل الضمير يعظم شأن النصر ومن يصدر عنه، ويقوي اليقين بأن النصر من عنده وحده؛ فهو سبحانه صاحب صفات الجلال والكمال، فلا يتعلق القلب بالأسباب استقلالًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص638–639، تحت «نكتة الإظهار في محل الإضمار»","url":""}]},{"id":"s8-69","number":69,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"ما مناسبة الختم بـ﴿إن الله عزيز حكيم﴾؟","answer":"﴿عزيز﴾ لا يغلبه غالب وهو القادر على النصر، و﴿حكيم﴾ يضع النصر وأسبابه في مواضعها؛ فالختام جامع للقدرة والتدبير.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص641، تحت «نكتة ختم الآية باسمي الله: (العزيز الحكيم)»","url":""}]},{"id":"s8-70","number":70,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"ما سرّ التعبير في قوله تعالى في آل عمران: ﴿بشرى لكم﴾، وحذف ﴿لكم﴾ في الأنفال فقال: ﴿إلا بشرى﴾؟","answer":"من وجوه الفرق أن ﴿لكم﴾ سبقت في الأنفال في ﴿فاستجاب لكم﴾، فحذف تكرارها لفظًا ومعنى. أما في آل عمران فذكرها يزيد تعيين أصحاب البشرى في مقام يواجهون فيه كثرة عدوهم؛ ويذكر المصدر أيضًا فرق الإيجاز والإطناب بين السياقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص637، تحت «نكتة ترك تقييد البشرى بالجار والمجرور (لكم)»","url":""}]},{"id":"s8-72","number":72,"surah":8,"verses":[10],"references":[{"surah":8,"verses":[10]}],"verseLabel":"الأنفال: 10","question":"لماذا ختم آية الأنفال بـ﴿إن الله عزيز حكيم﴾، وختم نظيرتها في آل عمران بـ﴿العزيز الحكيم﴾؟","answer":"جاء ختام الأنفال جملة مستقلة مؤكدة بـ﴿إن﴾؛ لأن سياقها تقدمته وعود متعددة بالنصر وإحقاق الحق وقطع دابر الكافرين، فناسبه تأكيد أبلغ. وفي آل عمران جاء ﴿العزيز الحكيم﴾ وصفين تابعين لاسم الله، إذ لم تتقدم تلك الوعود المتعددة في السياق نفسه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص640، تحت «توجيه المتشابه اللفظي»","url":""}]},{"id":"s8-73","number":73,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"ما دلالة الاستعارة في الآية؟","answer":"صور إلقاء النعاس عليهم بصورة غشاء يحيط بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص646، تحت عنوان «بلاغة الاستعارة في الآية»","url":""}]},{"id":"s8-274","number":274,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"ما دلالة توجيه القراءات في الآية؟","answer":"شبه النعاس بالغطاء، أو شبه إلقاءه بوضع الغشاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص648، تحت عنوان «توجيه القراءات في الآية»","url":""}]},{"id":"s8-74","number":74,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"لماذا وصف النعاس بأنه ﴿أمنة منه﴾؟","answer":"النعاس ﴿أمنة منه﴾ لأنه علامة زوال الخوف في موطن الحرب، ومنحة من الله سكّن بها نفوسهم وقواهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص643، تحت عنوان «شرح المفردات: ﴿أمنة﴾»","url":""}]},{"id":"s8-75","number":75,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"لماذا قدم ﴿عليكم﴾ في قوله: ﴿وينزل عليكم من السماء ماء﴾؟","answer":"قدم للاهتمام بمن نزل عليهم الماء، وللتشويق إلى النعمة المنزلة عليهم. وتقديمه على ﴿من السماء﴾ يبين أن الامتنان بوصول الماء إليهم في حاجتهم أهم هنا من مجرد بيان جهة نزوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص649–650، تحت «نكتة تقديم الجار والمجرور»","url":""}]},{"id":"s8-76","number":76,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"لماذا جمع للماء أربع وظائف: التطهير، وإذهاب الرجز، وربط القلوب، وتثبيت الأقدام؟","answer":"جمع الماء مصالح الظاهر والباطن: طهارة الأبدان، وإزالة وسوسة الشيطان، وتقوية القلوب، وتماسك الرمل تحت الأقدام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص655، تحت عنوان «بلاغة الكناية في قوله: ﴿ويثبت به الأقدام﴾»","url":""}]},{"id":"s8-77","number":77,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"لماذا عبّر عن وسوسة الشيطان بـ﴿رجز الشيطان﴾؟","answer":"أضيف الرجز إلى الشيطان لأنه وسوسته وتخويفه وتكديره الذي أراد به إضعافهم، فطهرهم الله منه بالماء واليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص651–652، تحت «بلاغة المجاز المرسل»","url":""}]},{"id":"s8-78","number":78,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"ما الصورة في ﴿وليربط على قلوبكم﴾؟","answer":"في ﴿يربط على قلوبكم﴾ استعارة لتثبيت القلوب ومنعها من الاضطراب، كأن عليها رباطًا يشدها فلا تتفلت من الخوف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص653–654، تحت عنوان «دلالة حرف الجر (على) في قوله: ﴿على قلوبكم﴾»","url":""}]},{"id":"s8-79","number":79,"surah":8,"verses":[11],"references":[{"surah":8,"verses":[11]}],"verseLabel":"الأنفال: 11","question":"ما سرّ التعبير في قوله تعالى: ﴿ويثبت به الأقدام﴾، فجعل الماء مثبتًا للأقدام؟","answer":"كان المطر يلبد الرمل فيثبت عليه المشي، فجعل الماء سببًا حسيًا لثبات الأقدام، مع ما أورثه من ثبات معنوي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص654–655، تحت عنوان «بلاغة الكناية في قوله: ﴿ويثبت به الأقدام﴾»","url":""}]},{"id":"s8-80","number":80,"surah":8,"verses":[12],"references":[{"surah":8,"verses":[12]}],"verseLabel":"الأنفال: 12","question":"ما سرّ التعبير في قوله تعالى للملائكة: ﴿أني معكم﴾ قبل أمرهم بتثبيت المؤمنين؟","answer":"بدأ بإعلام الملائكة بمعيته؛ تثبيتًا لهم وبيانًا أن ما يفعلونه مؤيد بعون الله وتدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص662–663، تحت عنوان «دلالة المعية في قوله: ﴿أني معكم﴾»","url":""}]},{"id":"s8-81","number":81,"surah":8,"verses":[12],"references":[{"surah":8,"verses":[12]}],"verseLabel":"الأنفال: 12","question":"لماذا عبّر عن تقوية المؤمنين بقوله للملائكة: ﴿فثبتوا الذين آمنوا﴾؟","answer":"التثبيت يصور إزالة اضطرابهم وخوفهم، وتقوية عزائمهم، كأن قلوبهم ربطت فلا يخالطها رعب. فجاء التعبير مركزًا على الأثر المطلوب في نفوس المؤمنين عند لقاء عدوهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص663، تحت «براعة المجاز في قوله: ﴿فثبتوا الذين آمنوا﴾»","url":""}]},{"id":"s8-82","number":82,"surah":8,"verses":[12],"references":[{"surah":8,"verses":[12]}],"verseLabel":"الأنفال: 12","question":"لماذا قال: ﴿سألقي في قلوب الذين كفروا الرعب﴾ بضمير المفرد، ولم يقل: سنلقي؟","answer":"أفرد الضمير مع أن المقام مقام تعظيم لئلا يتوهم أن الملائكة المخاطبين هم سبب إلقاء الرعب استقلالًا. فإسناده إلى الله وحده يطمئن المؤمنين إلى أن تخذيل عدوهم من عنده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص664–665، تحت «نكتة التعبير بـ﴿سألقي﴾ دون (سنلقي)»","url":""}]},{"id":"s8-83","number":83,"surah":8,"verses":[12],"references":[{"surah":8,"verses":[12]}],"verseLabel":"الأنفال: 12","question":"لماذا اختير ﴿الرعب﴾ في قوله: ﴿سألقي في قلوب الذين كفروا الرعب﴾، دون مطلق الخوف؟","answer":"الرعب خوف شديد يستولي على النفس، فهو أخص من مطلق الخوف. واختياره يصور ما يلقيه الله في قلوب عدوهم من فزع بالغ يخذلهم ويضعف قدرتهم على المواجهة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص668، تحت «الرعب والخوف»","url":""}]},{"id":"s8-84","number":84,"surah":8,"verses":[12],"references":[{"surah":8,"verses":[12]}],"verseLabel":"الأنفال: 12","question":"ما نكتة التنصيص على ما ﴿فوق الأعناق﴾ و﴿بنان﴾؟","answer":"وق الأعناق موضع الإجهاز وقطع الرؤوس، والبنان أطراف الأعضاء التي بها حمل السلاح والدفاع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص666–667، تحت عنوان «نكتة التنصيص على ما ﴿فوق الأعناق﴾ و﴿بنان﴾»","url":""}]},{"id":"s8-275","number":275,"surah":8,"verses":[12],"references":[{"surah":8,"verses":[12]}],"verseLabel":"الأنفال: 12","question":"ما دلالة الفوقية بين الإيجاز والكناية؟","answer":"ضربهما يعطل الحياة أو القدرة على القتال.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص666–667، تحت عنوان «دلالة الفوقية بين الإيجاز والكناية»","url":""}]},{"id":"s8-85","number":85,"surah":8,"verses":[13],"references":[{"surah":8,"verses":[13]}],"verseLabel":"الأنفال: 13","question":"لماذا عُبر عن عداوتهم بـ﴿شاقوا الله ورسوله﴾؟","answer":"المشاقة اتخاذ شق مقابل لشق آخر؛ فصورت مخالفتهم لله ورسوله كوقوفهم في جانب معادٍ منفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص673، تحت «بلاغة الاستعارة في الآية»","url":""}]},{"id":"s8-86","number":86,"surah":8,"verses":[13],"references":[{"surah":8,"verses":[13]}],"verseLabel":"الأنفال: 13","question":"لماذا أعاد الشرط نفسه: ﴿ومن يشاقق الله ورسوله﴾ بعد تقرير فعلهم؟","answer":"أُعيد الشرط لتعميم الحكم بعد وصف الواقعة؛ فما نزل بهم ليس خاصًا بهم، بل سنة في كل من يشاقق الله ورسوله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص675–676، تحت «دلالة (من) في قوله: ﴿ومن يشاقق﴾»","url":""}]},{"id":"s8-87","number":87,"surah":8,"verses":[13],"references":[{"surah":8,"verses":[13]}],"verseLabel":"الأنفال: 13","question":"ما سرّ التعبير في قوله تعالى: ﴿شديد العقاب﴾ لا «شديد العذاب»؟","answer":"العقاب جزاء على الجرم ومؤاخذة به، وهو أنسب لسياق المشاقة والإجرام من لفظ العذاب الأعم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص679، تحت عنوان «سر التعبير بالعقاب في قوله: ﴿فإن الله شديد العقاب﴾»","url":""}]},{"id":"s8-88","number":88,"surah":8,"verses":[13],"references":[{"surah":8,"verses":[13]}],"verseLabel":"الأنفال: 13","question":"ما مناسبة إظهار اسم الله في جواب الشرط؟","answer":"أعيد اسم الله حتى لا يتوهم رجوع الضمير إلى أقرب مذكور، وهو الرسول ﷺ، فشدة العقاب هنا لله. كما أن الإظهار يجعل الجملة مستقلة تجري مجرى المثل، مؤكدة هذا الوعيد العام.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص679، تحت «نكتة الإظهار في محل الإضمار»","url":""}]},{"id":"s8-89","number":89,"surah":8,"verses":[14],"references":[{"surah":8,"verses":[14]}],"verseLabel":"الأنفال: 14","question":"لماذا أُشير إلى العقاب بقوله: ﴿ذلكم فذوقوه﴾؟","answer":"اسم الإشارة يحضر العقاب المشاهد يوم بدر ويعظمه، ثم فرعت عليه صيغة الذوق التي تواجههم بما نزل بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص684، تحت عنوان «نكتة تعريف المسند إليه بالإشارة في قوله: ﴿ذلكم فذوقوه﴾»","url":""}]},{"id":"s8-90","number":90,"surah":8,"verses":[14],"references":[{"surah":8,"verses":[14]}],"verseLabel":"الأنفال: 14","question":"لماذا استعير الذوق للعذاب؟","answer":"عبر بالذوق عن مباشرة العذاب والإحساس به؛ فنقل المعاناة إلى صورة حسية قريبة من الإدراك. وفيه أيضًا أن عذاب الدنيا الذي باشرونه كذوق يسير بالقياس إلى عذاب الآخرة الذي ينتظرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص686، تحت «براعة المجاز في قوله: ﴿ذلكم فذوقوه﴾»","url":""}]},{"id":"s8-91","number":91,"surah":8,"verses":[14],"references":[{"surah":8,"verses":[14]}],"verseLabel":"الأنفال: 14","question":"لماذا انتقل من الخطاب في ﴿فذوقوه﴾ إلى الغيبة في ﴿وأن للكافرين عذاب النار﴾؟","answer":"واجههم أولًا بعذاب الدنيا الواقع: ﴿فذوقوه﴾، ثم عمم الحكم باسم ﴿الكافرين﴾ في عذاب الآخرة؛ فانتقل من الحاضرين إلى جنسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص687، تحت «نكتة الإظهار في محل الإضمار»","url":""}]},{"id":"s8-92","number":92,"surah":8,"verses":[15],"references":[{"surah":8,"verses":[15]}],"verseLabel":"الأنفال: 15","question":"لماذا ناداهم بوصف الإيمان قبل النهي عن الفرار؟","answer":"النداء بوصف الإيمان يستنهض مقتضاه في الثبات والطاعة، ويشعر بأن الفرار لا يليق بمن تحقق بهذا الوصف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص693، تحت «دلالة النداء باسم الإيمان»","url":""}]},{"id":"s8-93","number":93,"surah":8,"verses":[15],"references":[{"surah":8,"verses":[15]}],"verseLabel":"الأنفال: 15","question":"ما سرّ التعبير في قوله تعالى: ﴿إذا لقيتم الذين كفروا زحفًا﴾، فجعل «زحفًا» حالًا؟","answer":"﴿زحفًا﴾ حال تصور الجيشين متقاربين يزحف بعضهما إلى بعض في جماعة، وهو الموطن الذي يحرم فيه التولي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص695–696، تحت عنوان «نكتة التعبير بالمصدر حالًا (زحفًا)»","url":""}]},{"id":"s8-94","number":94,"surah":8,"verses":[15],"references":[{"surah":8,"verses":[15]}],"verseLabel":"الأنفال: 15","question":"ما وجه البلاغة في الكناية في قوله: ﴿فلا تولوهم الأدبار﴾؟","answer":"﴿لا تولوهم الأدبار﴾ كناية مصورة عن الفرار.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص696–697، تحت عنوان «بلاغة الكناية في قوله: ﴿فلا تولوهم الأدبار﴾»","url":""}]},{"id":"s8-276","number":276,"surah":8,"verses":[15],"references":[{"surah":8,"verses":[15]}],"verseLabel":"الأنفال: 15","question":"ما نكتة التعبير بالأدبار دون الظهور؟","answer":"إذ تعرض هيئة المنهزم الذي يجعل ظهره لعدوه، وهي أبلغ في التقبيح من «لا تهربوا».","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص696–697، تحت عنوان «نكتة التعبير بالأدبار دون الظهور»","url":""}]},{"id":"s8-95","number":95,"surah":8,"verses":[16],"references":[{"surah":8,"verses":[16]}],"verseLabel":"الأنفال: 16","question":"ما معنى ﴿متحرفًا﴾ و﴿متحيزًا﴾ في السياق؟","answer":"التحرف خطة داخل القتال، والتحيز انتقال إلى جماعة يستمد بها المقاتل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص690، تحت عنوان «شرح المفردات: ﴿متحرفًا﴾ و﴿متحيزًا﴾»","url":""}]},{"id":"s8-277","number":277,"surah":8,"verses":[16],"references":[{"surah":8,"verses":[16]}],"verseLabel":"الأنفال: 16","question":"ما دلالة اللام في قوله: ﴿إلا متحرفًا لقتال﴾؟","answer":"كلاهما حركة لمصلحة القتال لا فرارًا منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص698، تحت عنوان «دلالة اللام في قوله: ﴿إلا متحرفًا لقتال﴾»","url":""}]},{"id":"s8-96","number":96,"surah":8,"verses":[16],"references":[{"surah":8,"verses":[16]}],"verseLabel":"الأنفال: 16","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد باء بغضب من الله﴾؟","answer":"التبوء يفيد شدة لزوم الغضب له، كأنه اتخذ مكانًا لا يخرج منه. وتزيد الباء معنى الملابسة والمصاحبة؛ فلا يكون جزاء الفرار خوفًا عابرًا، بل غضبًا يلازمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص698–699، تحت عنوان «دلالة الباء في ﴿بغضب﴾»","url":""}]},{"id":"s8-97","number":97,"surah":8,"verses":[16],"references":[{"surah":8,"verses":[16]}],"verseLabel":"الأنفال: 16","question":"كيف سمّى جهنم ﴿مأواه﴾ ثم قال: ﴿وبئس المصير﴾، والمأوى موضع راحة عادة؟","answer":"الأصل أن المأوى مكان يلجأ إليه المرء ليستريح ويستقر، فإطلاقه على جهنم تهكم بمن استحقها؛ إذ صار موضع لجوئه عذابًا. ثم صرح بذم هذه العاقبة في ﴿وبئس المصير﴾.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص699، تحت «بلاغة الاستعارة التهكمية»","url":""}]},{"id":"s8-98","number":98,"surah":8,"verses":[17],"references":[{"surah":8,"verses":[17]}],"verseLabel":"الأنفال: 17","question":"ما دلالة الغرض من أسلوب المجاز في قوله: ﴿ولكن الله قتلهم﴾؟","answer":"المباشرة منهم، والتقدير والتأثير الحاسم من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص707، تحت عنوان «الغرض من أسلوب المجاز في قوله: ﴿ولكن الله قتلهم﴾»","url":""}]},{"id":"s8-278","number":278,"surah":8,"verses":[17],"references":[{"surah":8,"verses":[17]}],"verseLabel":"الأنفال: 17","question":"ما دلالة نفي القتل وعدم كونه واقعًا؟","answer":"نُفي استقلال المؤمنين بالقتل وأثبت لله لأنه هو الذي أقدرهم وأمدهم وألقى الرعب.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص705، تحت عنوان «دلالة نفي القتل وعدم كونه واقعًا»","url":""}]},{"id":"s8-99","number":99,"surah":8,"verses":[17],"references":[{"surah":8,"verses":[17]}],"verseLabel":"الأنفال: 17","question":"لماذا انتقل من الجمع في القتل إلى خطاب النبي منفردًا في الرمي؟","answer":"جُمع خطاب القتل لاشتراك المؤمنين فيه، وأُفرد الرمي لاختصاص النبي ﷺ بمباشرته يوم بدر.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص708، تحت عنوان «دلالة عطف جملة: ﴿وما رميت﴾ على ما قبلها»","url":""}]},{"id":"s8-100","number":100,"surah":8,"verses":[17],"references":[{"surah":8,"verses":[17]}],"verseLabel":"الأنفال: 17","question":"لماذا كرر: ﴿وما رميت إذ رميت﴾، فأثبت الرمي ونفاه في جملة واحدة؟","answer":"أثبت الرمي للنبي ﷺ من جهة المباشرة، ونفى عنه بلوغ أثره الخارق، ثم أثبته لله من جهة الإيصال والتأثير؛ فلا تناقض لاختلاف الجهتين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص712، تحت عنوان «دلالة الفعل ﴿رميت﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s8-101","number":101,"surah":8,"verses":[17],"references":[{"surah":8,"verses":[17]}],"verseLabel":"الأنفال: 17","question":"ما سرّ التعبير في قوله تعالى: ﴿وليبلي المؤمنين منه بلاء حسنًا﴾، وسمّى النصر بلاء؟","answer":"البلاء في أصل معناه الاختبار، ويكون بالخير كما يكون بالشر؛ فسُمّي النصر والغنيمة بلاءً حسنًا لأنهما نعمة واختبار يظهر به شكر المؤمنين وحسن طاعتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص702، تحت عنوان «شرح المفردات: ﴿بلاء﴾»","url":""}]},{"id":"s8-102","number":102,"surah":8,"verses":[17],"references":[{"surah":8,"verses":[17]}],"verseLabel":"الأنفال: 17","question":"ما مناسبة الختم بـ﴿إن الله سميع عليم﴾؟","answer":"ناسب ﴿سميع عليم﴾ ما في الموقف من دعاء المؤمنين وأقوالهم ونياتهم؛ فهو سميع لاستغاثتهم، عليم بإيمانهم واستعدادهم للابتلاء الحسن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص715، تحت «دلالة الختم بهاتين الصفتين الجليلتين ﴿سميع عليم﴾»","url":""}]},{"id":"s8-103","number":103,"surah":8,"verses":[18],"references":[{"surah":8,"verses":[18]}],"verseLabel":"الأنفال: 18","question":"لماذا افتتحت الآية باسم الإشارة: ﴿ذلكم﴾؟","answer":"يشير ﴿ذلكم﴾ إلى ما تقدم من القتل والرمي والنصر والبلاء الحسن، فيجمعه ويحضره أمام المخاطبين تمهيدًا لبيان أنه من تدبير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص718، تحت «دلالة التعبير باسم الإشارة في ﴿ذلكم﴾»","url":""}]},{"id":"s8-104","number":104,"surah":8,"verses":[18],"references":[{"surah":8,"verses":[18]}],"verseLabel":"الأنفال: 18","question":"ما الذي يضيفه لفظ ﴿موهن﴾ في قوله: ﴿موهن كيد الكافرين﴾ إلى تصوير هزيمتهم؟","answer":"الوهن ضعف يصيب القوة النفسية والإرادة والعزيمة؛ فالتعبير يصور أثر الهزيمة في باطنهم، بعد ما كانوا عليه من قوة وسيطرة. لقد نصر الله المؤمنين مع قلة عددهم، فانكسرت بذلك شوكة عدوهم ووهن كيده.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص722–723، تحت «الوهن والضعف»","url":""}]},{"id":"s8-105","number":105,"surah":8,"verses":[18],"references":[{"surah":8,"verses":[18]}],"verseLabel":"الأنفال: 18","question":"لماذا قال: ﴿موهن كيد الكافرين﴾ بصيغة الاسم، ولم يقل: الذين كفروا؟","answer":"صيغة الاسم تصور تمكن الكفر في هؤلاء الذين استحقوا الهزيمة وتوهين الكيد، وتربط ما أصابهم بوصف راسخ فيهم؛ فناسبت بيان حالهم في هذا السياق.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص721، تحت «سر التعبير بـ﴿الكافرين﴾، دون (الذين كفروا)»","url":""}]},{"id":"s8-106","number":106,"surah":8,"verses":[19],"references":[{"surah":8,"verses":[19]}],"verseLabel":"الأنفال: 19","question":"لماذا عبّر عن دعائهم بالحكم بـ﴿إن تستفتحوا﴾؟","answer":"الاستفتاح طلب الفتح، أي الحكم والفصل بالنصر؛ وقد دعا المشركون أن ينصر الله أهدى الطائفتين، فجاء اللفظ من جنس طلبهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص726–727، تحت «سر اختيار ﴿إن تستفتحوا﴾ دون الدعاء»","url":""}]},{"id":"s8-107","number":107,"surah":8,"verses":[19],"references":[{"surah":8,"verses":[19]}],"verseLabel":"الأنفال: 19","question":"ما سرّ التعبير التهكمي في قوله تعالى للمشركين: ﴿فقد جاءكم الفتح﴾، مع أن ما جاءهم كان الهزيمة؟","answer":"في ﴿فقد جاءكم الفتح﴾ تهكم بالمشركين؛ فقد طلبوا الحكم فجاءهم الفصل الذي تمنوه، لكنه ظهر به بطلانهم وكانت نتيجته هزيمتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص727، تحت عنوان «بلاغة الاستعارة في مجيء الفتح»","url":""}]},{"id":"s8-108","number":108,"surah":8,"verses":[19],"references":[{"surah":8,"verses":[19]}],"verseLabel":"الأنفال: 19","question":"لماذا تكرر الشرط في ﴿وإن تنتهوا فهو خير لكم وإن تعودوا نعد﴾؟","answer":"الشرط الأول يفتح لهم باب الانتهاء وما فيه من خير، والثاني يحذرهم من العودة إلى القتال بعودة العقوبة؛ فلكل شرط جهة وجزاء.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص730–731، تحت عنوان «دلالة حذف المتعلق في فعل الشرط ﴿تعودوا﴾ وجوابه ﴿نعد﴾»","url":""}]},{"id":"s8-109","number":109,"surah":8,"verses":[19],"references":[{"surah":8,"verses":[19]}],"verseLabel":"الأنفال: 19","question":"ما سرّ التعبير في قوله تعالى: ﴿ولن تغني عنكم فئتكم شيئًا ولو كثرت﴾؟","answer":"نُفي عن فئتهم كل إغناء بـ﴿لن﴾ و﴿شيئًا﴾، ثم أُلغي أثر كثرتها؛ فاجتمع تأكيد النفي والعموم لقطع اغترارهم بالعدد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص731، تحت عنوان «سر التعبير بقوله ﴿شيئًا﴾»","url":""}]},{"id":"s8-110","number":110,"surah":8,"verses":[19],"references":[{"surah":8,"verses":[19]}],"verseLabel":"الأنفال: 19","question":"ما مناسبة الختم بـ﴿وأن الله مع المؤمنين﴾؟","answer":"معية الله للمؤمنين هي علة نصرهم وعدم إغناء فئة الكافرين؛ فهي معية تأييد وحفظ، وبها ترجح الفئة المؤمنة وإن قلت.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص733–734، تحت عنوان «دلالة الواو في جملة ﴿وأن﴾»","url":""}]},{"id":"s8-111","number":111,"surah":8,"verses":[20],"references":[{"surah":8,"verses":[20]}],"verseLabel":"الأنفال: 20","question":"لماذا تكرر الأمر بطاعة الله ورسوله بعد وروده في أول السورة؟","answer":"الأمر الأول بالطاعة ورد في سياق قسمة الأنفال، أما هنا ففي الانقياد لأمر الجهاد، وهو أشد على النفس؛ فناسب تجديد الأمر بالطاعة لتثبيت المؤمنين على امتثال هذا التكليف.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص740، تحت «سر تكرار الأمر بالطاعة في السياق الحكيم»","url":""}]},{"id":"s8-112","number":112,"surah":8,"verses":[20],"references":[{"surah":8,"verses":[20]}],"verseLabel":"الأنفال: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تولوا عنه﴾ فأفرد الضمير بعد ذكر الله والرسول؟","answer":"يعود الضمير في ﴿عنه﴾ إلى الرسول ﷺ؛ لأن التولي عنه عند تبليغه هو تولٍّ عن أمر الله، وقد أفرد لتعيين جهة السماع والتلقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص742–743، تحت «سر التعبير بالضمير المفرد ﴿عنه﴾»","url":""}]},{"id":"s8-113","number":113,"surah":8,"verses":[20],"references":[{"surah":8,"verses":[20]}],"verseLabel":"الأنفال: 20","question":"ما سرّ التعبير في قوله تعالى: ﴿وأنتم تسمعون﴾، دون أن يقال: وأنتم تعلمون؟","answer":"لأن أوامر الله تبلغهم بقول الرسول ﷺ، والسمع أول طريق لتلقيها؛ فالنهي يشتد على من يعرض عن الطاعة وهو يسمع الأمر ويعرف ما يطلب منه، إذ لم يفقد وسيلة التلقي.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص744–745، تحت «سر اختيار السماع دون غيره»","url":""}]},{"id":"s8-114","number":114,"surah":8,"verses":[21],"references":[{"surah":8,"verses":[21]}],"verseLabel":"الأنفال: 21","question":"ما دلالة العطف بالواو في ﴿ولا تكونوا﴾؟","answer":"النهي يشبه حال من يدّعي السماع بلسانه ثم لا يقبل ولا يعمل.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص746–747، تحت عنوان «دلالة العطف بالواو في ﴿ولا تكونوا﴾»","url":""}]},{"id":"s8-279","number":279,"surah":8,"verses":[21],"references":[{"surah":8,"verses":[21]}],"verseLabel":"الأنفال: 21","question":"ما دلالة الغرض من التشبيه بقوله ﴿كالذين﴾؟","answer":"الغرض التحذير من أن يكون سماع المؤمنين صوتًا بلا استجابة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص746–747، تحت عنوان «الغرض من التشبيه بقوله ﴿كالذين﴾»","url":""}]},{"id":"s8-115","number":115,"surah":8,"verses":[21],"references":[{"surah":8,"verses":[21]}],"verseLabel":"الأنفال: 21","question":"لماذا نفى السماع عنهم بعد إثبات قولهم: ﴿سمعنا﴾؟","answer":"أثبتوا لأنفسهم سماع الأذن بقولهم ﴿سمعنا﴾، ونُفي عنهم سماع التدبر والقبول؛ فلا تعارض لاختلاف حقيقة السماع في الموضعين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص748–749، تحت «الغرض من التعبير بأسلوب طباق السلب»","url":""}]},{"id":"s8-116","number":116,"surah":8,"verses":[22],"references":[{"surah":8,"verses":[22]}],"verseLabel":"الأنفال: 22","question":"لماذا سمّى الكافرين ﴿شر الدواب﴾ مع أنهم بشر؟","answer":"سُمّوا شر الدواب لأنهم عطلوا السمع والنطق والعقل التي ميز بها الإنسان، فصار الحيوان الجاري على فطرته خيرًا ممن أبطل أدوات الهداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص753–754، تحت عنوان «سر التعبير بعبارة ﴿شر الدواب﴾»","url":""}]},{"id":"s8-117","number":117,"surah":8,"verses":[22],"references":[{"surah":8,"verses":[22]}],"verseLabel":"الأنفال: 22","question":"لماذا جمع بين ﴿الصم البكم﴾ ثم قال: ﴿الذين لا يعقلون﴾؟","answer":"الصمم يصور امتناعهم عن تلقي الحق، والبكم امتناعهم عن النطق به، ثم كشف ﴿لا يعقلون﴾ أصل الداء: تعطيل العقل الذي ينتفع بالمسموع ويهدي القول.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص754–755، تحت عنوان «سر وصفهم بعدم التعقل في قوله ﴿الذين لا يعقلون﴾»","url":""}]},{"id":"s8-118","number":118,"surah":8,"verses":[22],"references":[{"surah":8,"verses":[22]}],"verseLabel":"الأنفال: 22","question":"لماذا أضيف ﴿شر﴾ إلى ﴿الدواب﴾ في وصفهم؟","answer":"الإضافة تجعل المفاضلة في الشر شاملة جنس الدواب كله؛ فهؤلاء شر ما يدب على الأرض لتعطيلهم ما وهبوا من أدوات الإدراك، وفي هذا أقصى التقبيح لحالهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص753، تحت «بلاغة التعبير بالمسند إليه معرفًا بالإضافة»","url":""}]},{"id":"s8-119","number":119,"surah":8,"verses":[23],"references":[{"surah":8,"verses":[23]}],"verseLabel":"الأنفال: 23","question":"ما سر التعبير بقوله ﴿لأسمعهم﴾؟","answer":"المثبت لهم سماع الصوت، والمنفي سماع القبول والفهم النافع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص762، تحت عنوان «بلاغة التعبير بقوله ﴿لأسمعهم﴾»","url":""}]},{"id":"s8-280","number":280,"surah":8,"verses":[23],"references":[{"surah":8,"verses":[23]}],"verseLabel":"الأنفال: 23","question":"ما دلالة الغرض من التعبير بالكناية في الآية؟","answer":"لو علم الله في استعدادهم خيرًا لوهبهم إسماعًا يثمر هداية.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص762، تحت عنوان «الغرض من التعبير بالكناية في الآية»","url":""}]},{"id":"s8-120","number":120,"surah":8,"verses":[23],"references":[{"surah":8,"verses":[23]}],"verseLabel":"الأنفال: 23","question":"لماذا كرر الإِسماع: ﴿ولو أسمعهم لتولوا﴾ بعد نفي الخير؟","answer":"الإسماع الأول مشروط بوجود الخير فيهم، فهو إسماع فهم للهدى وانتفاع به. والثاني يفترض إسماعهم مع بقاء فساد نفوسهم، فلا يتبعه قبول؛ فمجرد فهم الكلام لا يوجب العمل به ممن أصر على الإعراض.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص763–764، تحت «المفارقة في المعنى بين الفعلين: ﴿لأسمعهم﴾ و﴿أسمعهم﴾»","url":""}]},{"id":"s8-121","number":121,"surah":8,"verses":[23],"references":[{"surah":8,"verses":[23]}],"verseLabel":"الأنفال: 23","question":"ما دلالة الجمع بين التولي والإعراض؟","answer":"التولي قد يقع لسبب عارض، أما ﴿وهم معرضون﴾ فيثبت أن الإعراض صفة راسخة فيهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص765–766، تحت عنوان «دلالة الجمع بين التولي والإعراض»","url":""}]},{"id":"s8-281","number":281,"surah":8,"verses":[23],"references":[{"surah":8,"verses":[23]}],"verseLabel":"الأنفال: 23","question":"ما وجه البلاغة في قيد التولي بالجملة الحالية؟","answer":"جمع بين الفعل الظاهر والدافع الباطن الملازم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص765–766، تحت عنوان «بلاغة قيد التولي بالجملة الحالية»","url":""}]},{"id":"s8-122","number":122,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"لماذا قيل: ﴿استجيبوا لله وللرسول﴾، دون «أجيبوا»؟","answer":"الاستجابة تدل على موافقة الإجابة لما أراده الداعي، فتحقق القبول لدعوته؛ أما الإجابة فقد تكون بالموافقة أو بالمخالفة. فناسبت الاستجابة الأمر بقبول دعوة الله ورسوله والعمل بها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص772، تحت «دلالة التعبير بالفعل ﴿استجيبوا﴾»","url":""}]},{"id":"s8-123","number":123,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"لماذا أفرد الضمير في ﴿إذا دعاكم﴾ بعد ذكر الله والرسول؟","answer":"دعوة الرسول ﷺ هنا متحدة مع دعوة الله من جهة وجوب الامتثال، وطاعته طاعة لله؛ فاكتفي بالضمير المفرد، وفيه تأكيد وحدة الدعوة التي يلزم المؤمنين الاستجابة لها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص774، تحت «دلالة التعبير بضمير الواحد ﴿دعاكم﴾»","url":""}]},{"id":"s8-124","number":124,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"لماذا وصف الوحي والتكليف بأنه ﴿لما يحييكم﴾؟","answer":"شُبه الوحي والإيمان بالحياة؛ لأنهما يخرجان العقل والقلب من موت الجهل والكفر، ويصلحان حياة الفرد والجماعة في الدنيا والآخرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص775–776، تحت «الغرض من التعبير بالاستعارة في قوله ﴿يحييكم﴾»","url":""}]},{"id":"s8-125","number":125,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"ما نكتة إيراد ﴿يحول﴾ في السياق؟","answer":"هو مطلع على ما يعزم عليه، وقادر على أن يحول بينه وبين إنفاذ عزمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص777–778، تحت عنوان «نكتة إيراد ﴿يحول﴾ في السياق»","url":""}]},{"id":"s8-282","number":282,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"ما سر التعبير بالاستعارة التمثيلية؟","answer":"تصور العبارة إحاطة علم الله بسرائر الإنسان ونفوذ قدرته في قلبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص777–778، تحت عنوان «بلاغة التعبير بالاستعارة التمثيلية»","url":""}]},{"id":"s8-283","number":283,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"ما دلالة التعبير بالظرف ﴿بين﴾؟","answer":"ي ذلك حث على إخلاص الاستجابة والمبادرة إليها، مع تفويض الأمر إلى الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص777–778، تحت عنوان «دلالة التعبير بالظرف ﴿بين﴾»","url":""}]},{"id":"s8-126","number":126,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"ما وجه المقابلة بين ﴿المرء﴾ و﴿قلبه﴾ في الآية؟","answer":"تقابل العبارة بين الإنسان في أعماله وتصرفاته الجسمانية وبين ما يعزم عليه في قلبه؛ فتدل على أن قدرة الله تحيط بظاهره وباطنه، وقد تحول بين عزمه وبين تنفيذ ما أراد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص778، تحت «دلالة التعبير بلفظ ﴿المرء﴾»","url":""}]},{"id":"s8-127","number":127,"surah":8,"verses":[24],"references":[{"surah":8,"verses":[24]}],"verseLabel":"الأنفال: 24","question":"لماذا ختم بـ﴿وأنه إليه تحشرون﴾؟","answer":"ذكر الحشر يؤكد وجوب المبادرة إلى الاستجابة؛ فإلى الله مرجعهم وحسابهم، ولا مهرب ممن يملك القلوب والمصير جميعًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص779، تحت «دلالة عطف قوله ﴿وأنه إليه تحشرون﴾»","url":""}]},{"id":"s8-128","number":128,"surah":8,"verses":[25],"references":[{"surah":8,"verses":[25]}],"verseLabel":"الأنفال: 25","question":"ما سر التعبير بقوله ﴿لا تصيبن﴾؟","answer":"لا يقتصر شر الفتنة على من باشر الظلم.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص786–787، تحت عنوان «سر التعبير بقوله ﴿لا تصيبن﴾»","url":""}]},{"id":"s8-284","number":284,"surah":8,"verses":[25],"references":[{"surah":8,"verses":[25]}],"verseLabel":"الأنفال: 25","question":"ما دلالة عدم إصابة الظالمين بالفتنة وحدهم؟","answer":"الأمر باتقائها يحث على منع أسبابها والأخذ على أيدي الظالمين.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص786–787، تحت عنوان «دلالة عدم إصابة الظالمين بالفتنة وحدهم»","url":""}]},{"id":"s8-129","number":129,"surah":8,"verses":[25],"references":[{"surah":8,"verses":[25]}],"verseLabel":"الأنفال: 25","question":"لماذا جيء بنون التوكيد في ﴿لا تصيبن﴾؟","answer":"تؤكد النون شدة التحذير من فتنة لا يقف شرها عند الظالمين. ومن توجيهات الأسلوب أن التحذير صيغ في صورة نهي الفتنة نفسها عن إصابتهم، وهو أبلغ في مطالبتهم باتقاء أسبابها.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص785–786، تحت عنوان «وجه المعنى على كون ﴿لا تصيبن﴾ جملة استئنافية»","url":""}]},{"id":"s8-130","number":130,"surah":8,"verses":[25],"references":[{"surah":8,"verses":[25]}],"verseLabel":"الأنفال: 25","question":"لماذا خُتمت بـ﴿واعلموا أن الله شديد العقاب﴾؟","answer":"ناسب ﴿شديد العقاب﴾ التحذير من فتنة عامة؛ ليعلموا أن ترك أسبابها والتهاون في دفع الظلم يعرضهم لعقاب شديد.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص788–789، تحت عنوان «سر التعبير بـ﴿شديد العقاب﴾ دون شديد العذاب»","url":""}]},{"id":"s8-131","number":131,"surah":8,"verses":[26],"references":[{"surah":8,"verses":[26]}],"verseLabel":"الأنفال: 26","question":"لماذا أمرهم بتذكر حال الضعف: ﴿واذكروا إذ أنتم قليل﴾ عقب التحذير من الفتنة؟","answer":"ذكّرهم بحال الضعف والخوف ثم بما أولاهم من الإيواء والنصر والرزق؛ ليعرفوا قدر النعمة، ويقابلوا إحسان الله بالشكر والطاعة، لا بالخيانة ومخالفة أمره.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص793، تحت عنوان «غرض الأمر»","url":""}]},{"id":"s8-132","number":132,"surah":8,"verses":[26],"references":[{"surah":8,"verses":[26]}],"verseLabel":"الأنفال: 26","question":"ما سرّ التعبير في قوله تعالى: ﴿مستضعفون في الأرض﴾، دون أن يقال: ضعفاء؟","answer":"﴿مستضعفون﴾ تدل على أن غيرهم كان يتعمد إضعافهم وقهرهم، لا أنهم ضعفاء في ذواتهم؛ ولذلك هي أدق من «ضعفاء».","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص796، تحت «دلالة السين والتاء»","url":""}]},{"id":"s8-133","number":133,"surah":8,"verses":[26],"references":[{"surah":8,"verses":[26]}],"verseLabel":"الأنفال: 26","question":"لماذا عبّر بـ﴿يتخطفكم الناس﴾؟","answer":"التخطف أخذ سريع فيه غلبة واستلاب؛ فاستعير لما كانوا يخافونه من استئصال عدوهم لهم. وهو يصور شدة ضعفهم وخوفهم من أن يفاجئهم الأعداء قبل أن يقدروا على الامتناع.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص798–799، تحت عنوان «نكتة استعمال أن المصدرية بدل المصدر الصريح»","url":""}]},{"id":"s8-134","number":134,"surah":8,"verses":[26],"references":[{"surah":8,"verses":[26]}],"verseLabel":"الأنفال: 26","question":"لماذا حُذف متعلق الإيواء في ﴿فآواكم﴾، فلم يقل: إلى المدينة؟","answer":"حُذف متعلق الإيواء لتتسع المنة لكل ما آواهم الله إليه من المدينة والأمن وجماعة الأنصار، ولأن المقصود نفس الانتقال من الخوف إلى المأمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص800، تحت «علة حذف المتعلقات وذكرها»","url":""}]},{"id":"s8-135","number":135,"surah":8,"verses":[26],"references":[{"surah":8,"verses":[26]}],"verseLabel":"الأنفال: 26","question":"لماذا رتّب: ﴿فآواكم وأيدكم بنصره ورزقكم من الطيبات﴾؟","answer":"بدأ بالإيواء لأنه أمن المكان، ثم التأييد بالنصر لأنه أمن من العدو، ثم الرزق لأنه تمام استقرار الحياة؛ فترتيب النعم جارٍ من دفع الخوف إلى كمال العيش.","sources":[{"label":"موسوعة التفسير البلاغي، ج15، ص801، تحت «بلاغة ترتيب الأفعال»","url":""}]},{"id":"s8-136","number":136,"surah":8,"verses":[27],"references":[{"surah":8,"verses":[27]}],"verseLabel":"الأنفال: 27","question":"لماذا سمّى مخالفة أمر الله ورسوله ﴿خيانة﴾؟","answer":"الخيانة نقض العهد في السر وإنقاص الحق؛ فمخالفة أمر الله ورسوله بعد الالتزام بالإيمان نقض للأمانة التي حملها المؤمن.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص14، تحت عنوان «دلالة التعبير بمفردة الخيانة»","url":""}]},{"id":"s8-137","number":137,"surah":8,"verses":[27],"references":[{"surah":8,"verses":[27]}],"verseLabel":"الأنفال: 27","question":"ما سرّ التعبير في قوله تعالى: ﴿وتخونوا أماناتكم﴾، فعطف الخيانة على الخيانة؟","answer":"الخيانة الأولى تتعلق بحق الله ورسوله في الطاعة، والثانية بحقوق الأمانات المتعددة بين الناس؛ وعطفها يبين تلازم الحقين مع اختلاف متعلقهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص17، تحت «دلالة تكرار الألفاظ»","url":""}]},{"id":"s8-138","number":138,"surah":8,"verses":[27],"references":[{"surah":8,"verses":[27]}],"verseLabel":"الأنفال: 27","question":"لماذا جمع ﴿أماناتكم﴾ ولم يفردها؟","answer":"إضافة جمع الأمانات إلى جماعة المخاطبين تفيد توزيعها عليهم: لكل مؤمن ما اؤتمن عليه من الحقوق والتكاليف. وتجمعها الآية في عهد مشترك يجب حفظه؛ فخيانة أمانة الفرد إخلال بما يجب على جماعة المؤمنين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص17–18، تحت «فائدة إضافة الجمع إلى مجموع المخاطبين»","url":""}]},{"id":"s8-139","number":139,"surah":8,"verses":[27],"references":[{"surah":8,"verses":[27]}],"verseLabel":"الأنفال: 27","question":"لماذا ختم بـ﴿وأنتم تعلمون﴾؟","answer":"جاءت الحال لتشنيع الخيانة مع علمهم بقبحها وما يترتب عليها؛ فهم أهل تمييز يدركون أن الخيانة لا تليق بالمؤمن. وليس المراد تقييد النهي بحالة العلم، بل تأكيد قبح الفعل ومسؤوليتهم عنه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص18–19، تحت «بلاغة الجملة الحالية»","url":""}]},{"id":"s8-140","number":140,"surah":8,"verses":[28],"references":[{"surah":8,"verses":[28]}],"verseLabel":"الأنفال: 28","question":"لماذا سمّى الأموال والأولاد ﴿فتنة﴾ مع أنهما نعمة؟","answer":"الفتنة هي الاختبار الذي يكشف موقف الإنسان؛ فالمال والولد نعمة في ذاتهما، وقد يصيران سببًا للانشغال عن الطاعة أو الوقوع في الخيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص22، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s8-141","number":141,"surah":8,"verses":[28],"references":[{"surah":8,"verses":[28]},{"surah":9,"verses":[55]}],"verseLabel":"الأنفال: 28؛ التوبة: 55","question":"ما سرّ تقديم الأموال على الأولاد؟","answer":"في الأنفال: 28: قدمت الأموال لأن الخيانة تتعلق بها أكثر، ولأنها تقضي أغراضًا كثيرة وتتسع بها دواعي الافتتان، فناسب تقديمها سياق النهي عن الخيانة.\n\nفي التوبة: 55: قدمت الأموال لأن فتنتها أعم من فتنة الأولاد؛ فالرغبة فيها تشمل من له ولد ومن لا ولد له، وهي أيضًا وسيلة إلى كثير من رغبات الحياة. فناسب تقديم الأعم في التحذير من الإعجاب بما عند المنافقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص25، تحت عنوان «نكتة تقديم الأموال على الأولاد»","url":""}]},{"id":"s8-142","number":142,"surah":8,"verses":[28],"references":[{"surah":8,"verses":[28]}],"verseLabel":"الأنفال: 28","question":"لماذا قابل الفتنة بقوله: ﴿وأن الله عنده أجر عظيم﴾؟","answer":"قوبل نفع المال والولد العاجل بالأجر العظيم عند الله؛ ليختار المؤمن الباقي الأعظم، فلا تحمله محبتهما على الخيانة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص26، تحت عنوان «فائدة العطف بالواو»","url":""}]},{"id":"s8-143","number":143,"surah":8,"verses":[29],"references":[{"surah":8,"verses":[29]}],"verseLabel":"الأنفال: 29","question":"لماذا كرر شرط التقوى بعد قوله في أول السورة: ﴿فاتقوا الله﴾؟","answer":"الأمر الأول بالتقوى جاء عقب النزاع في الأنفال، وهنا جُعلت التقوى شرطًا لمنحة الفرقان والتكفير والمغفرة؛ فتكرر لاختلاف المقام والثمرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص32، تحت عنوان «غرض الأمر بالتقوى بجملة الشرط»","url":""}]},{"id":"s8-144","number":144,"surah":8,"verses":[29],"references":[{"surah":8,"verses":[29]}],"verseLabel":"الأنفال: 29","question":"لماذا سمّى البصيرة الفاصلة ﴿فرقانًا﴾؟","answer":"الفرقان ما يفرق به بين الحق والباطل والهدى والضلال؛ فسمّيت البصيرة والنصرة فرقانًا لما تمنحه التقوى من تمييز وفصل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص34، تحت «سر اختيار الألفاظ»","url":""}]},{"id":"s8-145","number":145,"surah":8,"verses":[29],"references":[{"surah":8,"verses":[29]}],"verseLabel":"الأنفال: 29","question":"لماذا جمع بين تكفير السيئات والمغفرة؟","answer":"من وجوه الفرق أن التكفير ستر السيئات في الدنيا، والمغفرة عدم المؤاخذة بها في الآخرة؛ فجمع الوعدين إتمام للمنة على المتقين. ويذكر المصدر أيضًا توجيه التكفير إلى الصغائر والمغفرة إلى الكبائر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص36، تحت عنوان «بلاغة ترتيب المعطوفات»","url":""}]},{"id":"s8-146","number":146,"surah":8,"verses":[29],"references":[{"surah":8,"verses":[29]}],"verseLabel":"الأنفال: 29","question":"ما مناسبة الختم بـ﴿والله ذو الفضل العظيم﴾؟","answer":"خُتم بذي الفضل العظيم لأن الفرقان والتكفير والمغفرة عطايا زائدة من فضل الله، لا ثمناً تستقل التقوى باستحقاقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص37، تحت عنوان «بلاغة التذييل بالفاصلة»","url":""}]},{"id":"s8-147","number":147,"surah":8,"verses":[30],"references":[{"surah":8,"verses":[30]}],"verseLabel":"الأنفال: 30","question":"لماذا عُبر عن مؤامرة قريش بالمضارع: ﴿وإذ يمكر بك﴾؟","answer":"المضارع ﴿يمكر﴾ يستحضر المؤامرة الماضية كأنها حاضرة، ويصور تتابع تدبيرهم وتنوع حيلهم حول النبي ﷺ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص43، تحت «نكتة التعبير بالفعل المضارع»","url":""}]},{"id":"s8-148","number":148,"surah":8,"verses":[30],"references":[{"surah":8,"verses":[30]}],"verseLabel":"الأنفال: 30","question":"لماذا رتبت خياراتهم: ﴿ليثبتوك أو يقتلوك أو يخرجوك﴾؟","answer":"رتبت بحسب أثرها في الرسول ﷺ ودعوته: قدم الحبس لأنه يمنعه من لقاء الناس وتبليغ الحق، وهو أشد عليه؛ ثم القتل الذي ينال به الشهادة، ثم الإخراج وهو أهون من سابقَيه. فالترتيب يراعي ما يريده أعداؤه من تعطيل رسالته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص46–47، تحت «بلاغة ترتيب الأفعال»","url":""}]},{"id":"s8-149","number":149,"surah":8,"verses":[30],"references":[{"surah":8,"verses":[30]}],"verseLabel":"الأنفال: 30","question":"لماذا كرر ﴿ويمكرون ويمكر الله﴾؟","answer":"قوبل مكرهم بتدبير الله الذي يرد كيدهم ويبطل غرضهم. ويذكر المصدر المشاكلة وجهًا في تسمية جزاء المكر مكرًا؛ فمكرهم عدوان خفي، وتدبير الله إبطال له ومجازاة عليه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص50، تحت «فن المشاكلة»","url":""}]},{"id":"s8-150","number":150,"surah":8,"verses":[30],"references":[{"surah":8,"verses":[30]}],"verseLabel":"الأنفال: 30","question":"لماذا خُتم بـ﴿والله خير الماكرين﴾؟","answer":"﴿خير الماكرين﴾ تقرر أن تدبير الله غالب محكم يحيط بحيلهم ويردها عليهم، فناسبت ختام مشهد المؤامرة وإفشالها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص50–51، تحت «نكتة اختيار المفردات»","url":""}]},{"id":"s8-151","number":151,"surah":8,"verses":[31],"references":[{"surah":8,"verses":[31]}],"verseLabel":"الأنفال: 31","question":"ما دلالة تأكيدهم السماع بقولهم: ﴿قد سمعنا﴾؟","answer":"أكدوا تحقق السماع بـ﴿قد﴾ والفعل الماضي ليوهموا أنهم أحاطوا بما يسمعون، وأنهم لا يحتاجون إلى مزيد تلاوة أو تدبر. وقصدهم الاستهانة والإعراض؛ كأنهم يقولون: سمعنا ما تقول فلا حاجة إلى تكراره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص59، تحت عنوان «نكتة التعبير بصيغة الماضي»","url":""}]},{"id":"s8-152","number":152,"surah":8,"verses":[31],"references":[{"surah":8,"verses":[31]}],"verseLabel":"الأنفال: 31","question":"لماذا عبّروا عن القرآن بـ﴿أساطير الأولين﴾؟","answer":"الأساطير ما سطر من أخبار الأولين التي لا حقيقة لها في زعمهم؛ فوصفوا القرآن بها طعنًا في الوحي وفرارًا من حجته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص64، تحت عنوان «بلاغة النظم في التنبيه على غايات الخصم»","url":""}]},{"id":"s8-153","number":153,"surah":8,"verses":[31],"references":[{"surah":8,"verses":[31]}],"verseLabel":"الأنفال: 31","question":"ما دلالة قولهم: ﴿لو نشاء لقلنا مثل هذا﴾ ولم يأتوا بمثله؟","answer":"علقوا الإتيان بالمثل على مشيئتهم ليزعموا القدرة مع ترك الفعل، لكن عجزهم العملي فضح الدعوى؛ فلم يأتوا بمثله مع قيام التحدي.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص54، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s8-154","number":154,"surah":8,"verses":[32],"references":[{"surah":8,"verses":[32]}],"verseLabel":"الأنفال: 32","question":"ما دلالة قولهم: ﴿إن كان هذا هو الحق﴾ بضمير الفصل؟","answer":"ضمير الفصل ﴿هو﴾ يفيد القصر في دعواهم: إن كان هذا القرآن هو الحق وحده؛ وجاء كلامهم على سبيل المكابرة والتشكيك لا طلب اليقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص71، تحت عنوان «معنى التعريف في لفظ ﴿الحق﴾»","url":""}]},{"id":"s8-155","number":155,"surah":8,"verses":[32],"references":[{"surah":8,"verses":[32]}],"verseLabel":"الأنفال: 32","question":"لماذا طلبوا نزول الحجارة بدل أن يسألوا الهداية إن كان حقًا؟","answer":"طلبوا العذاب بدل الهداية مبالغة في الجحود والثقة بباطلهم؛ فقدموا المكابرة والتحدي على طلب النجاة لو ظهر الحق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص71–72، تحت «بلاغة فعل الأمر»","url":""}]},{"id":"s8-156","number":156,"surah":8,"verses":[32],"references":[{"surah":8,"verses":[32]}],"verseLabel":"الأنفال: 32","question":"ما دلالة قولهم: ﴿فأمطر علينا حجارة من السماء﴾؟","answer":"خصوا إمطار الحجارة لما فيه من ألم الأجسام وإذلال النفوس، ولما عرفوه من عذاب أصحاب الفيل. وزادوا ﴿من السماء﴾ تأكيدًا لطلب عقوبة خارقة من عند الله، تهكمًا وتحديًا للرسول ﷺ، لا رغبة في الاهتداء.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص72، تحت عنوان «توجيه المخصوص بالذكر»","url":""}]},{"id":"s8-157","number":157,"surah":8,"verses":[33],"references":[{"surah":8,"verses":[33]}],"verseLabel":"الأنفال: 33","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كان الله ليعذبهم وأنت فيهم﴾ بصيغة الجحود المؤكد؟","answer":"صيغة ﴿ما كان الله ليعذبهم﴾ أبلغ في النفي من «لا يعذبهم»؛ فهي تنفي ملاءمة العذاب لسنة الله ورسوله ﷺ بين أظهرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص81، تحت عنوان «بلاغة أسلوب النفي»","url":""}]},{"id":"s8-158","number":158,"surah":8,"verses":[33],"references":[{"surah":8,"verses":[33]}],"verseLabel":"الأنفال: 33","question":"لماذا انتقل من وجود النبي إلى الاستغفار: ﴿وما كان الله معذبهم وهم يستغفرون﴾؟","answer":"كان وجود الرسول ﷺ أمانًا مؤقتًا في حياته بينهم، والاستغفار أمانًا متجددًا يبقى بابه للأمة؛ فانتقل من المانع الخاص إلى السبب العام المستمر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص79، تحت عنوان «المعنى الإجمالي»","url":""}]},{"id":"s8-159","number":159,"surah":8,"verses":[33],"references":[{"surah":8,"verses":[33]}],"verseLabel":"الأنفال: 33","question":"لماذا جاءت الأولى ﴿ليعذبهم﴾ والثانية ﴿معذبهم﴾؟","answer":"الفعل ﴿ليعذبهم﴾ مع لام الجحود يناسب نفي وقوع العذاب في حال وجود الرسول، واسم الفاعل ﴿معذبهم﴾ يصور ثبات انتفاء وصف التعذيب حال استغفارهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص84، تحت عنوان «سر اختلاف التعبير بين المتقابلات»","url":""}]},{"id":"s8-160","number":160,"surah":8,"verses":[34],"references":[{"surah":8,"verses":[34]}],"verseLabel":"الأنفال: 34","question":"لماذا استدرك بقوله: ﴿وما لهم ألا يعذبهم الله﴾ بعد نفي العذاب؟","answer":"نفي العذاب مقيد بوجود الرسول والاستغفار، أما استحقاقهم له فثابت بسبب صدهم؛ فالاستدراك يفرق بين تأخير العذاب وانتفاء موجبه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص88، تحت عنوان «مناسبة الآية لما قبلها»","url":""}]},{"id":"s8-161","number":161,"surah":8,"verses":[34],"references":[{"surah":8,"verses":[34]}],"verseLabel":"الأنفال: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿وهم يصدون عن المسجد الحرام﴾ بالمضارع؟","answer":"المضارع ﴿يصدون﴾ يصور استمرارهم وتجدد منعهم الناس من المسجد الحرام، فكان الجرم قائمًا لا حادثة منقطعة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص92، تحت «دلالة التعبير بلفظ ﴿يصدون﴾»","url":""}]},{"id":"s8-162","number":162,"surah":8,"verses":[34],"references":[{"surah":8,"verses":[34]}],"verseLabel":"الأنفال: 34","question":"ما سرّ التعبير في قوله تعالى: ﴿وما كانوا أولياءه﴾ ثم حصر الولاية في المتقين؟","answer":"نُفيت ولايتهم للبيت رغم دعواهم، ثم قُصرت ولايته على المتقين؛ لأن الولاية حقها الحفظ والتعظيم والطاعة، لا الصد والكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص98، تحت عنوان «سر التعبير بالمتقين دون المؤمنين أو المسلمين»","url":""}]},{"id":"s8-163","number":163,"surah":8,"verses":[35],"references":[{"surah":8,"verses":[35]}],"verseLabel":"الأنفال: 35","question":"لماذا سمّى صفيرهم وتصفيقهم عند البيت ﴿صلاة﴾؟","answer":"سُمّي مكاؤهم وتصديتهم صلاة على سبيل التهكم أو بحسب زعمهم؛ إذ جعلوا الصفير والتصفيق بدل العبادة، فاشتد ذم فعلهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص105–106، تحت «الغرض من الاستعارة في لفظ ﴿صلاتهم﴾»","url":""}]},{"id":"s8-164","number":164,"surah":8,"verses":[35],"references":[{"surah":8,"verses":[35]}],"verseLabel":"الأنفال: 35","question":"لماذا نُكّر لفظا ﴿مكاء وتصدية﴾ في وصف صلاتهم؟","answer":"جاء التنكير لتحقير ما اتخذوه عبادة، وبيان استخفافهم بحرمة البيت؛ فما كان ينبغي أن يكون تعظيمًا وتذللًا صار صفيرًا وتصفيقًا ولهوًا واعتداء على المصلين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص107، تحت «فائدة تنكير لفظي ﴿مكاء وتصدية﴾ في الآية»","url":""}]},{"id":"s8-165","number":165,"surah":8,"verses":[35],"references":[{"surah":8,"verses":[35]}],"verseLabel":"الأنفال: 35","question":"ما دلالة الفاء في قوله: ﴿فذوقوا العذاب﴾؟","answer":"تربط الفاء العذاب بكفرهم، فتفيد أن ما يذوقونه نتيجة عاجلة مترتبة على إصرارهم على الكفر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص108، تحت عنوان «معنى الفاء في ﴿فذوقوا﴾»","url":""}]},{"id":"s8-285","number":285,"surah":8,"verses":[35],"references":[{"surah":8,"verses":[35]}],"verseLabel":"الأنفال: 35","question":"ما دلالة الأمر في قوله: ﴿فذوقوا﴾؟","answer":"الأمر للتهديد والتوبيخ، وفي لفظ الذوق تصوير لمباشرة العذاب وإحساسهم به إحساسًا لا مهرب منه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص109، تحت عنوان «فائدة الأمر ودلالته في ﴿فذوقوا﴾»","url":""}]},{"id":"s8-286","number":286,"surah":8,"verses":[35],"references":[{"surah":8,"verses":[35]}],"verseLabel":"الأنفال: 35","question":"لماذا عبّر بالمضارع في قوله: ﴿تكفرون﴾؟","answer":"يصور المضارع تجدد كفرهم واستمرارهم عليه، فيناسب تجدد استحقاقهم للعذاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص110، تحت عنوان «سر التعبير بالمضارع في ﴿تكفرون﴾»","url":""}]},{"id":"s8-167","number":167,"surah":8,"verses":[36,37],"references":[{"surah":8,"verses":[36,37]}],"verseLabel":"الأنفال: 36–37","question":"لماذا جمع ﴿أموالهم﴾ وأضافها إليهم في قوله: ﴿ينفقون أموالهم﴾؟","answer":"الجمع يدل على كثرة ما بذلوه وتنوعه، من نقود وكراع وسلاح وغيرها. وإضافتها إليهم تبرز شدة تعلقهم بها، فيعظم تقبيح إنفاقهم ما يحبون في الصد عن سبيل الله، ثم خيبتهم فيما قصدوا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص117، تحت «نكتة جمع لفظ الأموال وإضافتها إليهم»","url":""}]},{"id":"s8-168","number":168,"surah":8,"verses":[36,37],"references":[{"surah":8,"verses":[36,37]}],"verseLabel":"الأنفال: 36–37","question":"لماذا تحولت النفقة إلى ﴿حسرة عليهم﴾؟","answer":"تصير النفقة نفسها حسرة حين تذهب الأموال ولا تتحقق غايتهم، ثم يرونها سببًا لهزيمتهم وعقابهم؛ فتنقلب وسيلة القوة إلى ندم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص121، تحت عنوان «بلاغة الإخبار بالمصدر بلفظ ﴿حسرة﴾»","url":""}]},{"id":"s8-169","number":169,"surah":8,"verses":[36,37],"references":[{"surah":8,"verses":[36,37]}],"verseLabel":"الأنفال: 36–37","question":"لماذا قال: ﴿ثم يغلبون﴾ بعد قوله: ﴿ثم تكون عليهم حسرة﴾؟","answer":"لا تقف خيبتهم عند ذهاب المال من غير تحقيق الغرض، بل تعقبها الهزيمة. وتدل ﴿ثم﴾ على التراخي زمانًا أو رتبة؛ فالغلبة أشد عليهم من خسارة الأموال، وفي ترتيب الوعيد تصاعد في بيان سوء عاقبتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص122، تحت عنوان «معنى ثم العاطفة وأثرها في السياق»","url":""}]},{"id":"s8-170","number":170,"surah":8,"verses":[36,37],"references":[{"surah":8,"verses":[36,37]}],"verseLabel":"الأنفال: 36–37","question":"ما الصورة في قوله تعالى: ﴿ويجعل الخبيث بعضه على بعض فيركمه جميعًا﴾؟","answer":"يصوّر جمع أهل الكفر في ازدحام وتراكم، بعضهم فوق بعض، كحطب مركب يلقى في النار. وفيه إهانة لهم وإسقاط لكرامتهم، ويؤكد ﴿جميعًا﴾ أن المصير شامل لأفراد هذا الخبيث.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص131، تحت عنوان «نكتة التوكيد بلفظ ﴿جميعًا﴾»","url":""}]},{"id":"s8-171","number":171,"surah":8,"verses":[38],"references":[{"surah":8,"verses":[38]}],"verseLabel":"الأنفال: 38","question":"لماذا وُجه خطاب الكافرين بصيغة الغائب: ﴿قل للذين كفروا إن ينتهوا﴾؟","answer":"العدول إلى الغيبة يدل على أن المطلوب من الرسول ﷺ تبليغ مضمون الوعد والوعيد، فيجوز أن يؤديه بما يبين معناه، لا أن يكون مجرد ناقل للألفاظ بحروفها. وفي ذلك تشريف لمنزلته في البيان والتبليغ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص139–140، تحت «نكتة إسناد القول للغائبين»","url":""}]},{"id":"s8-172","number":172,"surah":8,"verses":[38],"references":[{"surah":8,"verses":[38]}],"verseLabel":"الأنفال: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿يغفر لهم ما قد سلف﴾، ولم يعدد جرائمهم؟","answer":"الموصول ﴿ما﴾ يفيد عموم ما مضى من جرائمهم وآثامهم؛ فيظهر سعة المغفرة عند الانتهاء عن الكفر. ولو قيل: ذنوبهم، لاحتمل قصر المراد على الكبائر، أما هذا اللفظ فيجمع ما سلف كله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص142، تحت «معنى ما في ﴿ما قد سلف﴾ في الآية»","url":""}]},{"id":"s8-173","number":173,"surah":8,"verses":[38],"references":[{"surah":8,"verses":[38]}],"verseLabel":"الأنفال: 38","question":"ما سرّ التعبير في قوله تعالى: ﴿فقد مضت سنة الأولين﴾ بدل التصريح بالعذاب؟","answer":"﴿سنة الأولين﴾ تحيل إلى قانون معلوم من هلاك المكذبين، فتغني عن تفصيل الوعيد وتجعله مؤيدًا بشواهد التاريخ.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص146، تحت عنوان «سر إضافة السنة للأولين»","url":""}]},{"id":"s8-175","number":175,"surah":8,"verses":[39,40],"references":[{"surah":8,"verses":[39,40]}],"verseLabel":"الأنفال: 39–40","question":"لماذا أفرد ﴿الدين﴾ ووصفه بـ﴿كله﴾؟","answer":"أُفرد ﴿الدين﴾ لأنه الملة والطاعة بوصفهما حقيقة واحدة، وأكد بـ﴿كله﴾ لنفي أن يبقى شيء من سلطان العبادة لغير الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص153، تحت عنوان «معنى أل الجنسية في لفظ ﴿الدين﴾ ودلالتها»","url":""}]},{"id":"s8-176","number":176,"surah":8,"verses":[39,40],"references":[{"surah":8,"verses":[39,40]}],"verseLabel":"الأنفال: 39–40","question":"لماذا ختم حال انتهائهم بـ﴿فإن الله بما يعملون بصير﴾؟","answer":"﴿بصير﴾ يناسب انتهاءهم الذي قد يخفى صدقه؛ فالله يرى أعمالهم وبواطنها، ويجازيهم على حقيقة ما يعملون.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص159، تحت «بلاغة اختيار اسم ﴿بصير﴾ لفاصلة الآية»","url":""}]},{"id":"s8-177","number":177,"surah":8,"verses":[39,40],"references":[{"surah":8,"verses":[39,40]}],"verseLabel":"الأنفال: 39–40","question":"ما مناسبة قوله تعالى عند توليهم: ﴿فاعلموا أن الله مولاكم﴾؟","answer":"عند توليهم ثُبّت المؤمنون بأن الله مولاهم؛ فهو متولي نصرهم وتدبيرهم، فلا يضرهم إعراض العدو ما دام الله ناصرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص160، تحت عنوان «بلاغة التعبير بالجملة الشرطية»","url":""}]},{"id":"s8-178","number":178,"surah":8,"verses":[41],"references":[{"surah":8,"verses":[41]}],"verseLabel":"الأنفال: 41","question":"ما سرّ التعبير في قوله تعالى: ﴿واعلموا أنما غنمتم من شيء﴾، فجمع «ما» و«من شيء»؟","answer":"﴿ما﴾ تعم كل ما غنم، و﴿من شيء﴾ تؤكد هذا العموم حتى أدنى شيء؛ فلا يخرج من حكم الخمس قليل ولا كثير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص175، تحت عنوان «نكتة التعبير بلفظ ﴿شيء﴾»","url":""}]},{"id":"s8-179","number":179,"surah":8,"verses":[41],"references":[{"surah":8,"verses":[41]}],"verseLabel":"الأنفال: 41","question":"لماذا أعاد ﴿لله﴾ في الخمس مع أن المال كله لله؟","answer":"ذُكر ﴿لله﴾ افتتاحًا للتقسيم لإظهار أن الخمس محكوم بأمره ومصرفه، لا لأن لله سهمًا ينتفع به؛ فالمال كله له ملكًا وهذا تخصيص حكم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص176، تحت عنوان «مناسبة إفراد اسم الله في المعاطيف»","url":""}]},{"id":"s8-180","number":180,"surah":8,"verses":[41],"references":[{"surah":8,"verses":[41]}],"verseLabel":"الأنفال: 41","question":"لماذا وصف يوم بدر بـ﴿يوم الفرقان يوم التقى الجمعان﴾؟","answer":"سمي بدر يوم الفرقان لأنه فصل بين الحق والباطل بالنصر، وفسره ﴿يوم التقى الجمعان﴾ بتعيين الواقعة التي ظهر فيها ذلك الفرق.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص187، تحت عنوان «مناسبة تخصيص الإنزال»","url":""}]},{"id":"s8-181","number":181,"surah":8,"verses":[41],"references":[{"surah":8,"verses":[41]}],"verseLabel":"الأنفال: 41","question":"ما مناسبة الختم بـ﴿والله على كل شيء قدير﴾؟","answer":"القدرة الإلهية هي التي دبرت اللقاء والنصر وقسمة الغنيمة على غير توقع البشر؛ فختم الآية يرد الأمر كله إلى قدرته.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص190، تحت عنوان «مناسبة إيثار لفظ ﴿قدير﴾»","url":""}]},{"id":"s8-182","number":182,"surah":8,"verses":[42],"references":[{"surah":8,"verses":[42]}],"verseLabel":"الأنفال: 42","question":"ما فائدة تفصيل موضعي الجيشين بالعدوة الدنيا والعدوة القصوى؟","answer":"يعيد التفصيل تصوير مشهد بدر وما فيه من أسباب ترجّح كفة المشركين؛ فموضعهم كان أصلح للاستقرار، وموضع المسلمين أصعب سيرًا. وبذلك يظهر أن النصر مع ضعف الأسباب الظاهرة كان من تدبير الله ولطفه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص196، تحت عنوان «براعة الإطناب في الآية قيد التفسير»","url":""}]},{"id":"s8-183","number":183,"surah":8,"verses":[42],"references":[{"surah":8,"verses":[42]}],"verseLabel":"الأنفال: 42","question":"ما فائدة ذكر موقع الركب في قوله: ﴿والركب أسفل منكم﴾ ضمن مشهد الجيشين؟","answer":"ذكر العير القريبة منهم يبين تعقد الموقف؛ فالمشركون جاءوا لحمايتها، والمسلمون كانوا يطلبونها، ثم صرفهم الله عنها إلى لقاء الجيش الذي يكرهونه. فكان جمع هذه الأطراف على ذلك الوجه من إحكام تدبيره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص196، تحت «دلالة الواو في قوله ﴿والركب أسفل منكم﴾»","url":""}]},{"id":"s8-184","number":184,"surah":8,"verses":[42],"references":[{"surah":8,"verses":[42]}],"verseLabel":"الأنفال: 42","question":"ما سرّ التعبير في قوله تعالى: ﴿ولو تواعدتم لاختلفتم في الميعاد﴾؟","answer":"لو كان اللقاء عن موعد سابق لاختلف الفريقان في زمانه أو مكانه لما في النفوس من رهبة وعدم استعداد؛ لكن الله جمعهم بغير تواعد ليقضي أمرًا مقدرًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص197، تحت عنوان «دلالة الواو في قوله ﴿ولو﴾»","url":""}]},{"id":"s8-185","number":185,"surah":8,"verses":[42],"references":[{"surah":8,"verses":[42]}],"verseLabel":"الأنفال: 42","question":"لماذا تكرر ﴿ليهلك من هلك عن بينة ويحيا من حي عن بينة﴾؟","answer":"قوبل الهلاك بالحياة لتصوير أثر البينة: من اختار الكفر بعد ظهورها فكأنه هلك، ومن آمن بها فقد حيي؛ وتكرار الصلة يثبت قيام الحجة على الفريقين.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص202، تحت عنوان «دلالة ﴿ليهلك﴾ و﴿ويحيا﴾ بين الحقيقة والمجاز»","url":""}]},{"id":"s8-186","number":186,"surah":8,"verses":[43,44],"references":[{"surah":8,"verses":[43,44]}],"verseLabel":"الأنفال: 43–44","question":"لماذا أراهم الله للنبي في المنام ﴿قليلًا﴾؟","answer":"أراه الله عدوه قليلًا في المنام، فأخبر أصحابه فثبتت قلوبهم وتشجعوا على اللقاء، بدل أن تحملهم رؤية الكثرة على الوهن والاختلاف. ونسبت الإراءة إلى الله لتأكيد صدق رؤيا النبي ﷺ وما تحقق بها من التثبيت.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص210، تحت عنوان «نكتة إسناد الفعل إلى الله تعالى في قوله ﴿يريكهم الله﴾»","url":""}]},{"id":"s8-187","number":187,"surah":8,"verses":[43,44],"references":[{"surah":8,"verses":[43,44]}],"verseLabel":"الأنفال: 43–44","question":"لماذا انتقل من خطاب المفرد في ﴿أراكهم﴾ إلى الجمع في ﴿لفشلتم ولتنازعتم﴾؟","answer":"أسندت الإراءة إلى النبي ﷺ وحده، ثم عُدل إلى جماعة المؤمنين عند ذكر الفشل والتنازع؛ تنزيهًا لمقام الرسول عن نسبة الوهن إليه، وتصويرًا لما قد يقع في أصحابه عند رؤيتهم كثرة العدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص212، تحت «بلاغة الالتفات في قوله ﴿ولو أراكهم كثيرًا لفشلتم﴾»","url":""}]},{"id":"s8-188","number":188,"surah":8,"verses":[43,44],"references":[{"surah":8,"verses":[43,44]}],"verseLabel":"الأنفال: 43–44","question":"لماذا قلّل كل فريق في عين الآخر عند اللقاء؟","answer":"قلل المؤمنين في أعين المشركين ليقدموا فلا ينسحبوا، وقلل المشركين في أعين المؤمنين ليثبتوا؛ وبذلك تم اللقاء الذي قضاه الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص221، تحت عنوان «حكمة التقليل في رؤية العين للفريقين»","url":""}]},{"id":"s8-189","number":189,"surah":8,"verses":[43,44],"references":[{"surah":8,"verses":[43,44]}],"verseLabel":"الأنفال: 43–44","question":"لماذا ختم المشهد بـ﴿وإلى الله ترجع الأمور﴾؟","answer":"الخاتمة تكشف أن تدبير الرؤيا وتقليل الفريقين وإنفاذ اللقاء كلها أمور مردها إلى الله، فلا تستقل بها الأسباب الظاهرة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص224، تحت عنوان «دلالة أل في لفظ ﴿الأمور﴾»","url":""}]},{"id":"s8-190","number":190,"surah":8,"verses":[44],"references":[{"surah":8,"verses":[44]}],"verseLabel":"الأنفال: 44","question":"كيف يُجمع بين قوله تعالى في الأنفال: ﴿ويقللكم في أعينهم﴾، وقوله في آل عمران: ﴿يرونهم مثليهم رأي العين﴾؟","answer":"كان التقليل في أول اللقاء ليقدم الفريقان، ثم أُري المشركون المؤمنين مثليهم عند اشتداد القتال فداخلهم الرعب؛ فهما مرحلتان مختلفتان لا تعارض بينهما.","sources":[{"label":"موسوعة التفسير البلاغي، ج4، ص608–609، تحت «توفيق بين ﴿ويقللكم في أعينهم﴾ وبين ﴿يرونهم مثليهم﴾»","url":""}]},{"id":"s8-191","number":191,"surah":8,"verses":[45],"references":[{"surah":8,"verses":[45]}],"verseLabel":"الأنفال: 45","question":"لماذا جمع بين الثبات وكثرة ذكر الله عند لقاء العدو؟","answer":"الثبات عمل الجوارح، وذكر الله قوة القلب؛ فجمعهما لأن ثبات الموقف لا يدوم إلا باستمداد اليقين والعون من الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص231، تحت «مناسبة العطف في جملة الجزاء»","url":""}]},{"id":"s8-192","number":192,"surah":8,"verses":[45],"references":[{"surah":8,"verses":[45]}],"verseLabel":"الأنفال: 45","question":"ما سرّ التعبير في قوله تعالى: ﴿اذكروا الله كثيرًا﴾ في أشد مواطن الانشغال؟","answer":"في شدة القتال يكثر الاضطراب والغفلة؛ فأُمروا بكثرة الذكر ليظل القلب متعلقًا بالله، مستمدًا منه الثبات والنصر.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص231، تحت عنوان «دلالة تنكير لفظ ﴿كثيرًا﴾»","url":""}]},{"id":"s8-193","number":193,"surah":8,"verses":[46,47],"references":[{"surah":8,"verses":[46,47]}],"verseLabel":"الأنفال: 46–47","question":"لماذا أعاد الأمر بالطاعة ثم نهى عن التنازع؟","answer":"أعيدت الطاعة هنا في أحكام مواجهة العدو، ثم خُص التنازع بالنهي لأنه أقرب أسباب الفشل وذهاب القوة في هذا الموطن.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص238، تحت عنوان «مناسبة عطف النهي عن المنازعة على الأمر بالطاعة»","url":""}]},{"id":"s8-194","number":194,"surah":8,"verses":[46,47],"references":[{"surah":8,"verses":[46,47]}],"verseLabel":"الأنفال: 46–47","question":"ما الصورة في ﴿فتفشلوا وتذهب ريحكم﴾؟","answer":"تصور الريح القوة والغلبة والهيبة لما فيها من نفاذ واندفاع؛ فذهابها صورة لزوال شوكة الجماعة. وقد ذكر المصدر في التعبير الاستعارة والكناية، وربط الصورة بالتنازع الذي يبدد القوة ويوقع الفشل.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص241، تحت عنوان «بلاغة العطف في جملتي الجزاء»","url":""}]},{"id":"s8-195","number":195,"surah":8,"verses":[46,47],"references":[{"surah":8,"verses":[46,47]}],"verseLabel":"الأنفال: 46–47","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا تكونوا كالذين خرجوا من ديارهم بطرًا ورئاء الناس﴾؟","answer":"جمع الوصف علل خروج المشركين: البطر الذي يحمل على الطغيان، والرياء الذي يطلب منزلة الناس، والصد الذي يقاوم سبيل الله؛ وهو نقيض إخلاص المؤمنين وثباتهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص247، تحت عنوان «بلاغة التشبيه في قوله ﴿ولا تكونوا كالذين﴾»","url":""}]},{"id":"s8-196","number":196,"surah":8,"verses":[46,47],"references":[{"surah":8,"verses":[46,47]}],"verseLabel":"الأنفال: 46–47","question":"ما مناسبة الختم بـ﴿والله بما يعملون محيط﴾؟","answer":"الإحاطة أوسع من العلم المجرد؛ فهي تصور أن أعمالهم لا يفوت منها شيء قدرةً وعلمًا وجزاءً، فناسبت تهديد الخارجين بطرًا ورياءً وصدًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص254، تحت عنوان «بلاغة قوله ﴿والله بما يعملون محيط﴾ بين التصريح والكناية»","url":""}]},{"id":"s8-197","number":197,"surah":8,"verses":[48],"references":[{"surah":8,"verses":[48]}],"verseLabel":"الأنفال: 48","question":"ما دلالة قول الشيطان: ﴿لا غالب لكم اليوم من الناس﴾؟","answer":"نفى وجود أي غالب لهم من جنس الناس ليطمئنهم ويغريهم بالإقدام على القتال. فجمع نفي الجنس والتقييد باليوم والناس في وعد زائف بالنصر، ثم كشف مشهد المعركة بطلان هذا التغرير.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص264، تحت عنوان «دلالة من في قوله ﴿من الناس﴾»","url":""}]},{"id":"s8-198","number":198,"surah":8,"verses":[48],"references":[{"surah":8,"verses":[48]}],"verseLabel":"الأنفال: 48","question":"ما الصورة في ﴿فلما تراءت الفئتان نكص على عقبيه﴾؟","answer":"﴿نكص على عقبيه﴾ يصور رجوعًا سريعًا مذعورًا إلى الخلف بعد التقدم، فكأن حركته انقلبت على أثر رؤية الملائكة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص268، تحت عنوان «فائدة ذكر قوله ﴿على عقبيه﴾»","url":""}]},{"id":"s8-199","number":199,"surah":8,"verses":[48],"references":[{"surah":8,"verses":[48]}],"verseLabel":"الأنفال: 48","question":"ما سرّ التعبير في قوله تعالى: ﴿إني أرى ما لا ترون﴾؟","answer":"أبهم ما يراه تهويلًا له؛ والمراد ما عاينه من الملائكة وأسباب التأييد التي لم يرها المشركون، فاتخذها ذريعة للتبرؤ والهرب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص271، تحت عنوان «مناسبة التعبير بالاسم الموصول وصلته»","url":""}]},{"id":"s8-200","number":200,"surah":8,"verses":[49],"references":[{"surah":8,"verses":[49]}],"verseLabel":"الأنفال: 49","question":"لماذا وصف المنافقون المؤمنين بقولهم: ﴿غر هؤلاء دينهم﴾؟","answer":"نسبوا إقدام المؤمنين إلى غرور الدين لأنهم قاسوا الموقف بالعدد والعدة، ولم يدركوا حقيقة التوكل ووعد الله؛ فكشف قولهم مرض قلوبهم وقصور نظرهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص281، تحت عنوان «دلالة قوله ﴿ومن يتوكل على الله﴾»","url":""}]},{"id":"s8-201","number":201,"surah":8,"verses":[49],"references":[{"surah":8,"verses":[49]}],"verseLabel":"الأنفال: 49","question":"لماذا عقب بقوله: ﴿ومن يتوكل على الله فإن الله عزيز حكيم﴾؟","answer":"جاءت الجملة ردًا على زعم المنافقين أن الدين غر المؤمنين؛ فبيّنت أن اعتمادهم ليس غرورًا، بل توكل على عزيز لا يُغلب وحكيم يضع النصر في موضعه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص284، تحت عنوان «مناسبة مجيء وصفي ﴿عزيز حكيم﴾ في الآية»","url":""}]},{"id":"s8-202","number":202,"surah":8,"verses":[50,51],"references":[{"surah":8,"verses":[50,51]}],"verseLabel":"الأنفال: 50–51","question":"ما سرّ التعبير في قوله تعالى: ﴿يضربون وجوههم وأدبارهم﴾؟","answer":"جمع الوجه والدبر كناية عن استيعاب الضرب والإهانة، أو مجاز مرسل يذكر الطرفين ويريد الجسد كله. فتجتمع الصورة على إحاطة العذاب بهم وشدة التنكيل، فلا يختص الألم بجهة واحدة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص293، تحت «ذكر الوجوه والأدبار بين الكناية والمجاز المرسل»","url":""}]},{"id":"s8-203","number":203,"surah":8,"verses":[50,51],"references":[{"surah":8,"verses":[50,51]}],"verseLabel":"الأنفال: 50–51","question":"ما دلالة قول الملائكة: ﴿وذوقوا عذاب الحريق﴾؟","answer":"قول الملائكة ﴿ذوقوا﴾ توبيخ وتهديد يصور مباشرة العذاب وإحساسهم به، و﴿الحريق﴾ يخص عذاب النار الشديد الذي ينتظرهم بعد عذاب النزع.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص295، تحت عنوان «مناسبة التعبير بقوله ﴿وذوقوا عذاب الحريق﴾»","url":""}]},{"id":"s8-204","number":204,"surah":8,"verses":[50,51],"references":[{"surah":8,"verses":[50,51]}],"verseLabel":"الأنفال: 50–51","question":"ما سرّ التعبير في قوله تعالى: ﴿ذلك بما قدمت أيديكم﴾ مع أن الذنوب تصدر عن جوارح متعددة؟","answer":"نُسب التقديم إلى الأيدي لأنها أكثر الجوارح مباشرة للأعمال واكتسابًا لها، فغلبت في التعبير عن كل ما قدمه الإنسان من ذنوب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص296، تحت عنوان «دلالة الباء في قوله ﴿ذلك بما قدمت أيديكم﴾»","url":""}]},{"id":"s8-205","number":205,"surah":8,"verses":[50,51],"references":[{"surah":8,"verses":[50,51]}],"verseLabel":"الأنفال: 50–51","question":"لماذا نفى الظلم بصيغة المبالغة: ﴿ليس بظلام للعبيد﴾؟","answer":"من وجوه التعبير أن المبالغة تراعي كثرة العبيد؛ فنفي الظلم موزع على كل واحد منهم، فلا يظلم أحدًا. ويذكر المصدر أيضًا أن ﴿ظلام﴾ قد تحمل على النسبة، أي ليس بذي ظلم؛ فالمقصود نفي أصل الظلم، لا نفي كثرته وحدها.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص299، تحت «دلالة صيغة فعال في قوله ﴿ليس بظلام للعبيد﴾»","url":""}]},{"id":"s8-207","number":207,"surah":8,"verses":[52,54],"references":[{"surah":8,"verses":[52,54]}],"verseLabel":"الأنفال: 52؛ الأنفال: 52، 54","question":"ما سرّ التعبير في قوله تعالى في الأولى: ﴿فأخذهم الله بذنوبهم﴾، وفي الثانية: ﴿فأهلكناهم بذنوبهم﴾؟","answer":"الأخذ يصور القبض عليهم بقوة بحيث لا يفلتون، و﴿بذنوبهم﴾ تبين سبب العقوبة. وهو أعم من الإهلاك؛ فجاء ﴿فأهلكناهم﴾ في الموضع الثاني ليصرح بنهاية ذلك الأخذ، ثم بيّن إغراق آل فرعون صورةً مخصوصة من الهلاك.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص328، تحت عنوان «وجه إيثار لفظ الإهلاك دون الأخذ»","url":""}]},{"id":"s8-208","number":208,"surah":8,"verses":[52,54],"references":[{"surah":8,"verses":[52,54]}],"verseLabel":"الأنفال: 52، 54","question":"ما سرّ اختلاف التعبير بين قوله تعالى أولًا: ﴿كفروا بآيات الله﴾، وقوله بعد آيتين: ﴿كذبوا بآيات ربهم﴾؟","answer":"جاء ﴿كفروا بآيات الله﴾ في سياق تظهر فيه قدرة الله وتسخيره الملائكة، فناسب اسم الجلالة. أما ﴿كذبوا بآيات ربهم﴾ فجاءت بعد ذكر النعمة وتغييرها، فناسب وصف الرب المنعم؛ وفيه تقبيح تكذيبهم بآيات من رباهم وأحسن إليهم. والتكذيب صورة أخص من الكفر، فكل تعبير ملائم لما قبله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص327، تحت عنوان «سر إيثار وصف الربوبية»","url":""}]},{"id":"s8-210","number":210,"surah":8,"verses":[53],"references":[{"surah":8,"verses":[53]}],"verseLabel":"الأنفال: 53","question":"ما سرّ اختلاف التعبير بين قوله تعالى في الأنفال: ﴿ذلك بأن الله لم يك مغيرًا نعمة أنعمها على قوم حتى يغيروا ما بأنفسهم﴾، وقوله تعالى في الرعد: ﴿إن الله لا يغير ما بقوم حتى يغيروا ما بأنفسهم﴾؟","answer":"صرحت آية الأنفال بالنعمة السابقة ﴿نعمة أنعمها﴾، وعبرت بنفي الكون واسم الفاعل ﴿لم يك مغيرًا﴾ لتقرير ثبوت هذه السنة: لا تسلب النعمة قبل تغيير أهلها ما بأنفسهم. وجاءت آية الرعد بلفظ ﴿ما بقوم﴾ وبالمضارع المنفي لتقرير استمرار السنة وعموم الأحوال التي يتناولها اللفظ؛ ويفسر المصدر حالهم هنا بالنعمة والعافية أيضًا، فلا يصح جعل الفرق أن الرعد مخصوصة بتغيير الشر إلى الخير. و﴿يك﴾ فعل مضارع مجزوم بـ﴿لم﴾، وليس فعلًا ماضيًا.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص316، تحت عنوان «نكتة التعبير عن التغيير باسم الفاعل»","url":""}]},{"id":"s8-211","number":211,"surah":8,"verses":[53],"references":[{"surah":8,"verses":[53]}],"verseLabel":"الأنفال: 53","question":"لماذا حذف النون من ﴿يك﴾؟","answer":"حذفت نون ﴿يكن﴾ للتخفيف مع الجزم وسكون النون. ويذكر المصدر لطيفة تناسب هذا الإيجاز، وهي تأكيد تنزيه الله عن أدنى تغيير لنعمة أنعمها قبل أن يغير أهلها ما بأنفسهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص314، تحت «بلاغة الحذف للتخفيف في لفظ ﴿يك﴾»","url":""}]},{"id":"s8-213","number":213,"surah":8,"verses":[54],"references":[{"surah":8,"verses":[54]}],"verseLabel":"الأنفال: 54","question":"لماذا كرر تشبيههم بآل فرعون بعد وروده في الآية 52؟","answer":"للتشبيه جهتان: الأول يشبههم بآل فرعون في الكفر وما استتبعه من الأخذ بالذنوب؛ والثاني يأتي بعد بيان سنة تغيير النعمة، فيشبههم بهم في زوال النعمة والإهلاك بسبب تغيير ما بأنفسهم. فإعادة التشبيه تقرر معنى جديدًا في سياقه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص323–324، تحت «بلاغة التشبيه في السياق»","url":""}]},{"id":"s8-214","number":214,"surah":8,"verses":[54],"references":[{"surah":8,"verses":[54]}],"verseLabel":"الأنفال: 54","question":"ما سرّ التعبير في قوله تعالى: ﴿وكل كانوا ظالمين﴾؟","answer":"التنوين في ﴿كل﴾ عوض عن المضاف إليه؛ أي كل من مشركي بدر وآل فرعون ومن قبلهم، و﴿كانوا ظالمين﴾ تجمعهم في علة الهلاك مع اختلاف صوره.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص332، تحت عنوان «غرض التنكير في لفظ ﴿وكل﴾»","url":""}]},{"id":"s8-215","number":215,"surah":8,"verses":[54],"references":[{"surah":8,"verses":[54]}],"verseLabel":"الأنفال: 54","question":"لماذا زاد في الموضع الثاني: ﴿وأغرقنا آل فرعون﴾، ولم يذكر الإغراق في الموضع الأول؟","answer":"الموضع الأول أجمل الأخذ بذنوبهم، أما الثاني فمقام تفصيل الهلاك؛ لذلك زاد إغراق آل فرعون ليعرض صورة مخصوصة من سنة العقاب.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص328، تحت عنوان «وجه إيثار لفظ الإهلاك دون الأخذ»","url":""}]},{"id":"s8-216","number":216,"surah":8,"verses":[55],"references":[{"surah":8,"verses":[55]}],"verseLabel":"الأنفال: 55","question":"لماذا أعاد وصفهم بـ﴿شر الدواب﴾ كما في الآية 22؟","answer":"الأولى فيمن عطل السمع والعقل عمومًا، والثانية في ناقضي العهود خاصة؛ فتكرر وصف ﴿شر الدواب﴾ لأن الصنفين أبطلا خصائص الإنسان، مع تخصيص كل سياق بجرمه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص340–341، تحت «بلاغة التشابه اللفظي بين آيتي الأنفال»","url":""}]},{"id":"s8-217","number":217,"surah":8,"verses":[55],"references":[{"surah":8,"verses":[55]}],"verseLabel":"الأنفال: 55","question":"لماذا ختم بـ﴿فهم لا يؤمنون﴾ بالمضارع؟","answer":"المضارع ﴿لا يؤمنون﴾ يدل على استمرار انتفاء الإيمان وتجدد أسبابه فيهم، لا على موقف ماضٍ انقضى.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص340، تحت «دلالة صوغ الإيمان المنفي مضارعًا»","url":""}]},{"id":"s8-218","number":218,"surah":8,"verses":[56],"references":[{"surah":8,"verses":[56]}],"verseLabel":"الأنفال: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿الذين عاهدت منهم﴾ بـ«من»؟","answer":"من أوجه توجيه ﴿من﴾ أن ﴿عاهدت﴾ ضُمّن معنى أخذ العهد؛ أي عاهدتهم آخذًا منهم التزامهم. فالمعاهدة تتضمن إعطاء العهد وأخذه من الجانبين، ويبرز الحرف ما التزموه ثم نقضوه.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص345، تحت عنوان «دلالة من في قوله ﴿منهم﴾»","url":""}]},{"id":"s8-219","number":219,"surah":8,"verses":[56],"references":[{"surah":8,"verses":[56]}],"verseLabel":"الأنفال: 56","question":"ما سرّ التعبير في قوله تعالى: ﴿ينقضون عهدهم في كل مرة﴾؟","answer":"﴿في كل مرة﴾ تكشف أن النقض عادة متكررة عقب تجديد العهد، لا زلة واحدة، ولذلك استحقوا تشديد المعاملة.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص347، تحت عنوان «بلاغة التعبير بجملة ﴿في كل مرة﴾»","url":""}]},{"id":"s8-220","number":220,"surah":8,"verses":[57],"references":[{"surah":8,"verses":[57]}],"verseLabel":"الأنفال: 57","question":"ما سرّ التعبير في قوله تعالى: ﴿فإما تثقفنهم في الحرب﴾، دون أن يقال: تجدهم؟","answer":"الثقف هنا الظفر بهم والتمكن منهم مع الحذق؛ فهو أخص من مجرد العثور أو المصادفة، لأن من يصادف عدوه قد يغلبه وقد لا يغلبه. فناسب اللفظ ما بعده من القدرة على التشريد بهم.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص353، تحت عنوان «بديع إيثار لفظ ﴿تثقفنهم﴾ على تصادفهم»","url":""}]},{"id":"s8-221","number":221,"surah":8,"verses":[57],"references":[{"surah":8,"verses":[57]}],"verseLabel":"الأنفال: 57","question":"ما الصورة في ﴿فشرد بهم من خلفهم﴾؟","answer":"المعنى: أوقع بهم من النكال ما يفرق ويخيف من وراءهم؛ فجعلهم وسيلة لتشريد غيرهم وردع كل من يفكر في النقض.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص354، تحت عنوان «بلاغة الكناية أو التضمين في فعل التشريد»","url":""}]},{"id":"s8-222","number":222,"surah":8,"verses":[58],"references":[{"surah":8,"verses":[58]}],"verseLabel":"الأنفال: 58","question":"ما سرّ التعبير في قوله تعالى: ﴿فانبذ إليهم على سواء﴾؟","answer":"النبذ إلقاء العهد وطرحه إليهم علنًا، و﴿على سواء﴾ تعني استواء الطرفين في العلم بانتهائه؛ فلا يبدأ قتال مع بقاء توهم الأمان.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص361، تحت عنوان «بلاغة الاستعارة في فعل الأمر ﴿فانبذ﴾»","url":""}]},{"id":"s8-223","number":223,"surah":8,"verses":[58],"references":[{"surah":8,"verses":[58]}],"verseLabel":"الأنفال: 58","question":"لماذا ختم بـ﴿إن الله لا يحب الخائنين﴾؟","answer":"الخاتمة تعلل وجوب إعلان نبذ العهد؛ فمباغتة المعاهدين من غير إعلام خيانة، والله لا يحب الخائنين ولو كانت الخيانة مع عدو.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص362، تحت عنوان «بلاغة الاستئناف البياني في جملة الفاصلة»","url":""}]},{"id":"s8-224","number":224,"surah":8,"verses":[59],"references":[{"surah":8,"verses":[59]}],"verseLabel":"الأنفال: 59","question":"ما سرّ التعبير في قوله تعالى: ﴿ولا يحسبن الذين كفروا سبقوا﴾؟","answer":"على قراءة الياء يجوز أن يكون ﴿الذين كفروا﴾ فاعلًا؛ أي لا يظنوا أنفسهم قد أفلتوا. وعلى قراءة التاء يكون الخطاب للنبي ﷺ: لا تحسبن الذين كفروا قد سبقوا. والسبق مستعار للإفلات من العقوبة، والمقصود إبطال ظن النجاة من قدرة الله.","sources":[{"label":"موسوعة التفسير البلاغي، ج16، ص369، تحت عنوان «دلالة النهي عن الحسبان»","url":""}]}]);
